-- Inserting report ID 22260
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Replace AGB Starter Clutch TC#2', 'Mechanic', 'CM', 'Completed', '2024-12-09', '<p><b>Problem.</b></p><p>TC#2 AGB clutch differential&nbsp; temperature "High Alarm" A26SD_DIF = 43 C</p><p>High alarm = 42.78 C / SD 47.78 C</p><p>Fire hour : 103670 hrs.</p><p><b>Possible Cause.</b></p><p>AGB Clutch failure, Cooling &amp; Sealing air block, Synthetic LO block.</p><p><b>Solution.</b></p><p><span style="font-size: 15px;">- Removed hydraulic motor start found motor shaft minor rusty then cleaned and lube.</span></p><p><span style="font-size: 15px;">- Removed exiting clutch assembly found synthetic oil minor seeping from gear box to clutch shaft chamber cleaned and inspected found O ring deformed.</span></p><p><span style="font-size: 15px;">- Inspected new clutch, new O ring and installed back to position then then torque 21 NM.</span></p><p><span style="font-size: 15px;">-&nbsp;</span><span style="font-size: 15px;">Inspected cooling and sealing air to clutch found tubing broken and leak then replaced with new tubing( provide by EI ).</span></p><p><span style="font-size: 15px;">- Inspected motor start spine shaft found 20% worn out.</span></p><p><span style="font-size: 15px;">- Installed exiting hydraulic motor start then applied torque 90 NM.</span></p><p><span style="font-size: 15px;">- Inspected chamber drain line between hydraulic motor start clutch found blocked then unblock.</span></p><p><span style="font-size: 15px;">- Inspected magnetic chip detector from gear box A&amp;B and return strainer 800U found normally</span></p><p><span style="font-size: 15px;">- Inspected synthetic LO sight glass found reading 75% on sight glass &nbsp;then top up from 59% to 75% reading form LT.</span></p><p><span style="font-size: 15px;">- Final checked all fitting, cleaned and normalize unit.</span></p>', '<p><a href="G:\\GBSShare\\Department Share\\03 Maintenance\\031 DBS_MM\\6. Picture\\61. PPS Equipment Picture\\Turbo Compressor\\2X-3300\\2024\\2024.12.09 Replace AGB clutch">2024.12.09 Replace AGB clutch</a><br></p>', '2024-12-10 14:07:25', '2024-12-15 15:19:32', 'PTTEP\\GBS.Turbine-Mech', 'PTTEP\\GBS.Turbine-Mech', false, 'G2S') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-2X-3300', 'GBS-2X-3300', 'GAS COMPRESSOR PACKAGES TRAIN 2', NULL, NULL, 'GAS COMPRESSOR PACKAGES TRAIN 2', 'GBS-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Jamroens.', NULL, 'EXTERNAL', '2024-12-10 14:07:25', '2024-12-15 15:19:32', 'PTTEP\\GBS.Turbine-Mech', 'PTTEP\\GBS.Turbine-Mech');
