-- Inserting report ID 22326
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Replace defective LED Optic Board at DG-002', 'Electrical & Instrument', 'CM', 'Completed', '2024-12-11', '<p><u><b>Today’s Activity</b></u></p><p>Replace defective LED Optic board (RPM sensor) at DG-0002.</p><p><br></p><p><u><b>Action Taken</b></u></p><p>- According to history record (07-Nov-2024), LED optic board was damaged.</p><p>- New spare part had received (11-Dec-2024)</p><p>- Replaced new spare part in DG002</p><p>- Test run generator 30 min</p><p>- RPM can be monitored around 1500 RPM</p><p>- Back to normal condition.</p><p><b><u><br></u></b></p><p><span style="background-color: rgb(255, 255, 0);"><b><u>History (7/11/2024)</u></b></span></p>  <p><span style="background-color: rgb(255, 255, 0);">Continue working on the TS DG-03.</span></p>  <p><b><u style="background-color: rgb(255, 255, 0);">Issue Identified</u></b></p>  <p><span style="background-color: rgb(255, 255, 0);">The LED optic board PCB assembly(GM74198) was found to be damaged.</span></p>  <p><b><u style="background-color: rgb(255, 255, 0);">Action Taken</u></b></p>  <p><span style="background-color: rgb(255, 255, 0);">&nbsp; 1. Performed a function test using the LED optic board from the DG-02.</span></p>  <p><span style="background-color: rgb(255, 255, 0);">&nbsp; 2. Verified that the DG-03 operated normally with the DG-02 LED optic board installed.</span></p>  <p><span style="background-color: rgb(255, 255, 0);">&nbsp;</span></p>  <p><span style="background-color: rgb(255, 255, 0);">The LED optic board in the DG-03 is confirmed to be damaged and needs to be replaced.</span></p>  <p><b><u style="background-color: rgb(255, 255, 0);">Next Steps</u></b></p>  <p><span style="background-color: rgb(255, 255, 0);">Plan to order a new LED optic board for the DG-03.</span></p>  <p><span style="background-color: rgb(255, 255, 0);">&nbsp;</span></p>  <p><span style="background-color: rgb(255, 255, 0);">&nbsp;<b><u>History(06/11/2024)</u></b></span></p>  <p><span style="background-color: rgb(255, 255, 0);">&nbsp;Troubleshoot DG-0003 with engine not start up alarm.</span></p>  <p><b><u style="background-color: rgb(255, 255, 0);">Action</u></b></p>  <p><span style="background-color: rgb(255, 255, 0);">-Started DG-0003</span></p>  <p><span style="background-color: rgb(255, 255, 0);">-found engine run a few second and then stop with alarm.</span></p>  <p><span style="background-color: rgb(255, 255, 0);">-RPM was not shown in display panel while engine running.</span></p>  <p><span style="background-color: rgb(255, 255, 0);">-found engine not startup alarm.</span></p>  <p><span style="background-color: rgb(255, 255, 0);">-Checked control card, no abnormality are found. (in progress)<br><br><br></span></p>  <p><u style="background-color: rgb(255, 255, 0);"><b>History&nbsp;</b><b>(29 Oct 2024)</b></u></p>  <p><span style="background-color: rgb(255, 255, 0);">1M PM ZOC DG-0003 TEST RUN</span></p>  <p><b><u style="background-color: rgb(255, 255, 0);">Action</u></b></p>  <p><span style="background-color: rgb(255, 255, 0);">- Found&nbsp; 12VDC battery was not working properly.</span></p>  <p><span style="background-color: rgb(255, 255, 0);">- Started with battery starter and run.</span></p>  <p><span style="background-color: rgb(255, 255, 0);">- Found fuel low alarm, Lube oil alarm and engine no-start alarm. (one by one)</span></p>  <p><span style="background-color: rgb(255, 255, 0);">- Top up fuel and reset alarm.</span></p>  <p><span style="background-color: rgb(255, 255, 0);">- Try to restart DG again.</span></p>  <p><span style="background-color: rgb(255, 255, 0);">- Engine can start 15 min (run only)</span></p>  <p><span style="background-color: rgb(255, 255, 0);">- Not successful for full test run.</span></p>  <p><span style="background-color: rgb(255, 255, 0);">&nbsp;</span><br></p>', NULL, '2024-12-11 17:32:45', '2024-12-11 17:34:14', 'PTTEP\\ZOC.Elec-Tec', 'PTTEP\\ZOC.Elec-Tec', false, 'ATL') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-DG-0002', 'ATL-OC-DG-0002', 'ZOC Mobile Generator 2', NULL, NULL, 'ZOC Mobile Generator 2', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Htet Aung', NULL, 'EXTERNAL', '2024-12-11 17:32:45', '2024-12-11 17:34:14', 'PTTEP\\ZOC.Elec-Tec', 'PTTEP\\ZOC.Elec-Tec');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Nay', NULL, 'EXTERNAL', '2024-12-11 17:32:45', '2024-12-11 17:34:14', 'PTTEP\\ZOC.Elec-Tec', 'PTTEP\\ZOC.Elec-Tec');
END $$;

