-- Inserting report ID 22372
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TG-5630, Replaced LO control block found a low LO ', 'Mechanic', 'CM', 'Complete', '2024-12-12', '<p>TG-5630, Replaced LO control block found a low LO header pressure alarm.</p><p><b style="background-color: rgb(255, 255, 0);">On 8 Dec 2024:</b></p><p>- Replaced the LO control block with a new spare part <b>(P/N. 1621079-300)</b> and changed the TCV element with a claimed part from SOLAR.</p><p><b><font style="background-color: rgb(255, 255, 0);">On 9 Dec 2024:</font></b></p><p>- After starting the engine, we observed the LO header pressure still reading 582 kpag with an LO temperature of about 60°C.</p><p>- Our target was to fine-tune and adjust the LO header pressure at control valve PCV-901 to an operating pressure of 60 psi / 420 Kpag. during unit running with no load at 100% NGP.</p><p>- When adjusting the screw of PCV-901 counterclockwise (CCW) by 1/8 turn at a time, the LO header pressure still read about 582 kpag. with no sign of reduction.</p><p>- After adjusting the screw of PCV-901 to CCW (fully open = 2 1/4 turns) or clockwise (CW, fully closed = 2 1/4 turns), the result remained the same.</p><p><b style="background-color: rgb(255, 0, 0);"><font color="#ffffff">Action to T/S step 1:</font></b></p><p>- We replaced PCV-901 with a new spare part <b>(P/N. 1859015-1)</b> and fine-tuned and adjusted the LO header pressure.</p><p>- The LO header pressure still read about 500 kpag.</p><p>- When adjusting the screw of PCV-901 to CCW by 1/8 turn at a time, the LO header pressure still read about 500 kpag with no sign of reduction.</p><p>- After adjusting the screw of PCV-901 to CCW (open = 1 3/4 turns), the unit tripped due to low LO header pressure.</p><p><b><font color="#ffffff" style="background-color: rgb(255, 0, 0);">Action to T/S step 2:</font></b></p><p>- We replaced PCV-901 with a new spare part <b>(P/N. 1008942-6)</b> and fine-tuned and adjusted the LO header pressure.</p><p>- After starting the engine, we observed the LO header pressure is reading about 410 kpag.</p><p>- Adjusted the screw of PCV-901 to CW with 1/4 turn, and the LO header pressure increasing and reading about 420 kpag under load</p><p>- Now, TG-5630 is running and loaded with an LO header pressure reading of about 427 kpag.</p><p>&nbsp;</p><p></p><p><br></p><p><br></p><p><br></p><p><br></p>', NULL, '2024-12-12 16:55:07', CURRENT_TIMESTAMP, 'PTTEP\\Bongkot.turbine-Mech', NULL, false, 'G2N') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBN-TG-5630', 'GBN-TG-5630', 'TURBO GENERATOR 3 PACKAGE', NULL, NULL, 'TURBO GENERATOR 3 PACKAGE', 'GBN-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Numchoke P.', NULL, 'EXTERNAL', '2024-12-12 16:55:07', CURRENT_TIMESTAMP, 'PTTEP\\Bongkot.turbine-Mech', NULL);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Teerayut C.', NULL, 'EXTERNAL', '2024-12-12 16:55:07', CURRENT_TIMESTAMP, 'PTTEP\\Bongkot.turbine-Mech', NULL);
END $$;

