-- Inserting report ID 22393
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Perform YPM of G-8010 at ZBV-1(Day-2)', 'Mechanic', 'PM', 'Completed', '2024-12-13', '<div>Performed YPM for G-8010 (Day-2)</div><div><br></div><div>Action:</div><div><br></div><div>- Drained the engine coolant from the radiator.</div><div><br></div><div>- Removed and cleaned the radiator unit with water jet.</div><div><br></div><div>- Removed the radiator fan and fan belt.</div><div><br></div><div>- Removed the tappet cover &amp; check the valve rocker assembly.</div><div><br></div><div>- Check all tappet valve clearance. (feeler gauge-40)</div><div><br></div><div>- Applied correct torque to valve tappet locknut.(14Nm)</div><div><br></div><div>- Re-install the tappet cover with new gasket and apply with correct torque.(10Nm,14Nm)</div><div><br></div><div>- Re-install the radiator fan &amp; fan belt(with new one).</div><div><br></div><div>- Adjust the engine fan belt tension.</div><div><br></div><div>- Topped up the engine coolant about 4 liters.(Premix coolant)</div><div><br></div><div>- Perform housekeeping &amp; test running.</div><div><br></div><div>- Visual checking any abnormality &amp; logging genset parameters.</div><div><br></div><div>Required Tools</div><div><br></div><div><div>-8mm,10mm, 12mm, 17mm spanners. (one set of spanners)</div><div>-One socket box with ratchet</div><div>-36mm socket with extension.</div><div>-New spare lube filter, fuel filter, air filter, fan belt (Follow up Job Card)</div><div>-WD-40</div><div>-Oiler 1</div><div>-Water jet</div><div>-Blower</div><div>-Extension cable.</div><div>-Big Umbrella</div><div>-Plastic hammer</div><div>-Screwdriver</div><div>-Feeler Gauge set</div><div>-etc</div></div>', NULL, '2024-12-13 15:55:58', '2024-12-13 16:05:32', 'PTTEP\\ZOC.Mech-Tec', 'PTTEP\\ZOC.Mech-Tec', false, 'ATL') RETURNING id INTO new_report_id;
