  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Neymar', NULL, 'EXTERNAL', '2024-12-13 15:55:58', '2024-12-13 16:05:32', 'PTTEP\\ZOC.Mech-Tec', 'PTTEP\\ZOC.Mech-Tec');
