  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S air dryer A8990B auto drain at air comp unit', 'Electrical & Instrument', 'CM', 'Completed', '2024-12-14', '<h3 class="modal-title displayform"><p><u><b>Today Activity</b></u></p><p>Troubleshoot A-8990B air dryer auto drain issued at air compressor unit</p><p><br></p><p><b><u>Issued&nbsp;</u></b></p><p>-&nbsp; OP team inform that auto drain solenoid valve of air dryer A-8990B was opened continuously.</p><p>- OP team taken action air dyer-B process isolation and swap run to air dryer-A.</p><p><br></p><p><b><u>Action</u></b></p><p>- Visual checking auto drain solenoid valve condition.</p><p>- Disassemble solenoid valve.</p><p>- Checked pilot valve and seal O-ring. (Normal)</p><p>- Found some compensated moisture inside valve.</p><p>- Found one cable was disconnected in socket of solenoid valve.</p><p>- Cleaned solenoid and correct socket terminals.</p><p>- Re-installed solenoid valve.</p><p>- Performed manual test for solenoid valve.</p><p>- Solenoid valve can be active normally.</p><p>- Checked valve action after process service air dryer-B.</p><p>- Back to normal.</p><p><br></p><p><br></p></h3><h3 class="modal-title displayform"><p><br></p></h3>', NULL, '2024-12-14 14:09:55', '2025-01-03 17:03:34', 'PTTEP\\ZOC.Elec-Tec', 'PTTEP\\ZOC.Elec-Tec', false, 'ATL') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-A-6510B', 'ATL-OC-A-6510B', 'ZOC IA Air Dryer B', NULL, NULL, 'ZOC IA Air Dryer B', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
