  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'WPS-11 platform startup and battery charging.', 'Electrical', 'CM', 'Completed', '2024-12-17', '<p>WPS-11 platform startup and battery charging due to battery voltage Low. (On board at 15.00)</p><p>- Performed a reset on the battery circuit breaker (CB), solar charger system, and started charging the batteries at 25V DC, 20A</p><p>- At 17:00, the platform startup process begins, and the batteries in Bank-B are charged using a portable charger with 25V DC and 13A. (Batteries charging 17:00 - 22:00)</p><p>- At 18:00, the TEG startup process began. The TEG-D started normally</p><p>- The TEG-A, B, C, E ignition control boards were found to be defective, and the batteries were too low.</p><p>- All TEGs starting and finetune output voltage @28Vdc completed.&nbsp;</p><p>- At 20:00, all TEGs started, and the output voltage was fine-tuned to 28Vdc.</p><p>- At 22:00, the platform DC system is normal working, Battery @245Vdc, Battery discharge @-0.7A, Hybrid voltage @28.1Vdc, Total platform load @12A.</p>', NULL, '2024-12-18 19:00:48', '2024-12-18 19:09:57', 'PTTEP\\GBS.EI-Workshop', 'PTTEP\\GBS.EI-Workshop', false, 'G2S') RETURNING id INTO new_report_id;
