  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, '2TG-5520 Perform CAV', 'Mechanic', 'PDM', 'Completed', '2024-12-20', '<p>2TG-5520 Perform CAV (Condition Assessment Visit)</p><p>Visual check turbo gen package equipment.</p><p style="margin-left: 25px;">- Air filter housing.</p><p style="margin-left: 25px;">- Air inlet duct.</p><p style="margin-left: 25px;">- Generator.</p><p style="margin-left: 25px;">- Lube oil cooler.</p><p>Perform borescope inspection engine.</p><p style="margin-left: 25px;">- Air inlet duct panel (East side), Unplug bore scope port (Port C,D,E,G), Remove 1 of 12 injector at 10 O''-clock, Remove 1 of 12 T5 probe (H), Exhaust collector (Port I).</p><p style="margin-left: 25px;">- Gear Box open 2 bore scope ports.</p><p>Vibration Record</p><p style="margin-left: 25px;">- Install vibration sensor on gear box. insert vibration wire through atmosphere tube cover.</p><p style="margin-left: 25px;">- Start TG#2, at 100% NGP, Visual check engine.</p><p style="margin-left: 25px;">- Sync TG#2 then on load, TG#1 Unload and run at 100%NGP (Not stop).</p><p style="margin-left: 25px;">- TG#2 take load 50%, Share load at 2,800-2,900 watt between TG#3.</p><p style="margin-left: 25px;">- Keep record vibration for 1 hour by Solar vendor.</p><p style="margin-left: 25px;">- TG#2 Unload, shade load to TG#1.</p><p style="margin-left: 25px;">- TG#2 run at 100% NGP. Remove vibration sensor at Gear Box and close atmosphere tube cover.</p><p style="margin-left: 25px;">- Sync TG#2 then on load.</p><p style="margin-left: 25px;">- TG#1 Stop for crank soak wash on the next day for CAV.</p><p >Completed CAV TG#2</p>', NULL, '2024-12-22 09:31:50', '2024-12-23 10:55:38', 'PTTEP\\GBS.Mechanic-WorkS', 'PTTEP\\GBS.Mechanic-WorkS', false, 'G2S') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-2TG-5520', 'GBS-2TG-5520', 'GAS TURBINE GENERATOR SOLAR TAURUS 70', NULL, NULL, 'GAS TURBINE GENERATOR SOLAR TAURUS 70', 'GBS-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Kawinwipart N.', NULL, 'EXTERNAL', '2024-12-22 09:31:50', '2024-12-23 10:55:38', 'PTTEP\\GBS.Mechanic-WorkS', 'PTTEP\\GBS.Mechanic-WorkS');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Kittipong S.', NULL, 'EXTERNAL', '2024-12-22 09:31:50', '2024-12-23 10:55:38', 'PTTEP\\GBS.Mechanic-WorkS', 'PTTEP\\GBS.Mechanic-WorkS');
END $$;

