-- Inserting report ID 22780
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Fix water leak of 6" PVC pipe in water treatment', 'Mechanic', 'CM', 'Waiting for Material', '2024-12-19', '<p>Operator informed that water seeping rate is coming higher than before.&nbsp;</p><p><br></p><p>-Measure the dimension of old assembly (old pipe is SCB brand, 13.5 Class)&nbsp;</p><p>-Cut the new pipe ( Pipe are Sogo brand -8.5 class)&nbsp;</p><p>-</p><p><br></p><p>-Isolate power package (at 1:30 PM)</p><p>-drain water on the pipe line&nbsp;</p><p>-Cut old pipe by grinder&nbsp;</p><p>-separate the flange and remove the the old assembly.&nbsp;</p><p>-1st time Install new pipe and fitting, remove 45 elbow and change 90elbow line&nbsp;</p><p>and test with gravity pressure&nbsp;</p><p>- found leaking from the flange and pipe glue connection ( little glue amount and long exposer time)&nbsp;</p><p><br></p><p>-2nd time install new fitting and old flange and elbow&nbsp;</p><p>&nbsp;remove 45 elbow and change 90elbow line&nbsp;</p><p>-found water leak from and old pipe cutting crack&nbsp;</p><p>-during pressure up 2.8 bar, pipe connection splash out from the elbow fitting&nbsp;</p><p>-</p><p>3rd time install same as 2nd step item and use screw for joint connection&nbsp;</p><p>&nbsp;remove 45 elbow and change 90elbow line&nbsp;</p><p>-pipe splash out after 2 bar&nbsp;</p><p><br></p><p>4th time&nbsp;</p><p>-reinstall with new fitting and use 45elbow line&nbsp;</p><p>-tight the screw&nbsp;</p><p>-use high amount of glue&nbsp;</p><p>- test run and found small amount of water leak from screw joint&nbsp;</p><p><br></p><p><br></p><p>Equipment&nbsp;</p><p>New</p><p>- 6" PVC Pipe - 8.5 Class Sogo brand - 6 meter&nbsp;</p><p>-6" PVC Elbow - 8.5 Class Sogo brand - 4 EA&nbsp;</p><p>- 6" PVC&nbsp; 45 elbow - 8.5 Class Sogo brand - 2 EA&nbsp;</p><p>- 6" PVC Socket - 8.5 Class Sogo brand - 4 EA&nbsp;</p><p>- Glue 25g - 2 CAN&nbsp;</p><p>From surplus&nbsp;</p><p>-6" PVC flange - 2 EA&nbsp;&nbsp;</p><p><br></p>', '<br>', '2024-12-22 11:02:03', CURRENT_TIMESTAMP, 'PTTEP\\ZOC.Se-Mech', NULL, false, 'ATL') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-PSV-88216', 'ATL-OC-PSV-88216', 'PSV on 2"UW-88021-A2 water treatment pac', NULL, NULL, 'PSV on 2"UW-88021-A2 water treatment pac', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Neon', NULL, 'EXTERNAL', '2024-12-22 11:02:03', CURRENT_TIMESTAMP, 'PTTEP\\ZOC.Se-Mech', NULL);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Saw Set', NULL, 'EXTERNAL', '2024-12-22 11:02:03', CURRENT_TIMESTAMP, 'PTTEP\\ZOC.Se-Mech', NULL);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Junior', NULL, 'EXTERNAL', '2024-12-22 11:02:03', CURRENT_TIMESTAMP, 'PTTEP\\ZOC.Se-Mech', NULL);
END $$;

