-- Inserting report ID 22803
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S VESDA 2EWSD-59204 fault alarm frequently.', 'Instrument', 'CM', 'Under Monitoring', '2024-12-22', '<div class="ewa-rteLine">Troubleshooting Early Warning Smoke Detector VESDA VLS : 2EWSD-59204 at PPS chiller room mezzanine deck was alarm frequently.</div><div class="ewa-rteLine">- Monitor device event log and found the fault alarm as detail below,&nbsp;</div><div class="ewa-rteLine"> &nbsp;fault code 58 : Too many auto scan in one week</div><div class="ewa-rteLine">&nbsp;Cause : It have been more than 500 auto scans in a seven days period.</div><div class="ewa-rteLine">&nbsp;Action to clear fault : Increase the scan threshold by setting a higher alert threshold.</div><div class="ewa-rteLine">- Monitor valve operation and found pipe 2 valve operation was more than 500 times in one week while other pipe valve operation were in span limit.</div><div class="ewa-rteLine">- Tried to change scan threshold setting as per recommend in manual but it couldn''t be change setting value.</div><div class="ewa-rteLine">- Perform normalize air flow, adjust device date time.</div><div class="ewa-rteLine">- Keep monitor.</div><div class="ewa-rteLine"><br></div><div class="ewa-rteLine"><br></div>', NULL, '2024-12-22 18:23:53', '2024-12-23 08:18:24', 'PTTEP\\GBS.EI-Workshop', 'PTTEP\\GBS.EI-Workshop', false, 'G2S') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-2EWSD-59204', 'GBS-2EWSD-59204', 'EARLY WARNING SMOKE DETECTOR VESDA', NULL, NULL, 'EARLY WARNING SMOKE DETECTOR VESDA', 'GBS-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Theeraphan', NULL, 'EXTERNAL', '2024-12-22 18:23:53', '2024-12-23 08:18:24', 'PTTEP\\GBS.EI-Workshop', 'PTTEP\\GBS.EI-Workshop');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Sompong', NULL, 'EXTERNAL', '2024-12-22 18:23:53', '2024-12-23 08:18:24', 'PTTEP\\GBS.EI-Workshop', 'PTTEP\\GBS.EI-Workshop');
END $$;

