  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, '2TG-5530 Perform CAV', 'Mechanic', 'PDM', 'Completed', '2024-12-18', '<p>2TG-5530 Perform CAV (Condition Assessment Visit)</p><p>Day 1, 18 December 2024</p><p>Visual check turbo gen package equipment.</p><p>- Air filter housing.</p><p>- Air inlet duct.</p><p>- Generator.</p><p>- Lube oil cooler.</p><p>Perform borescope inspection engine.</p><p>- Air inlet duct panel (East side), Unplug bore scope port (Port C,D,E,G), Remove 1 of 12 injector at 10 O''-clock, Remove 1 of 12 T5 probe (H), Exhaust collector (Port I).</p><p>- Gear Box open 2 bore scope ports.</p><p><br></p><p>Day 2, 19 December 2024</p><p>Vibration Record</p><p>- Install vibration sensor on gear box. insert vibration wire through atmosphere tube cover.</p><p>- Start TG#3, at 100% NGP, Visual check engine.</p><p>- Sync TG#3 then on load, TG#2 Unload and run at 100%NGP (Not stop).</p><p>- TG#3 take load 50%, Share load at 2,800-2,900 watt between TG#1.</p><p>- Keep record vibration for 1 hour by Solar vendor.</p><p>- TG#3 Unload, shade load to TG#2.</p><p>- TG#3 run at 100% NGP. Remove vibration sensor at Gear Box and close atmosphere tube cover.</p><p>- Sync TG#3 then on load.</p><p>- TG#2 Stop for CAV on the next day.</p><p>Completed CAV TG#3</p>', NULL, '2024-12-23 10:58:54', '2024-12-23 11:04:40', 'PTTEP\\GBS.Mechanic-WorkS', 'PTTEP\\GBS.Mechanic-WorkS', false, 'G2S') RETURNING id INTO new_report_id;
