-- Inserting report ID 22892
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Power Cable installation diesel generator for FSD', 'Electrical & Instrument', 'OTH', 'Completed', '2024-12-21', '<p><u>21.12.24</u><u>&nbsp;</u><u>Activity</u></p><p>Power Cable installation diesel generator for FSD</p><p><u><br></u></p><p><u>Action</u></p><p><u>Rental Gen 1 (200KW)</u></p><p><br></p><p>-Termination on Rental Generator side and G-8925 power cable side</p><p>-Tightened all electrical connection</p><p>-Use insulation tape and rubber for phase by phase and phase by natural and earth</p><p>-Test run Rental Generator 1 (200KW) with no load</p><p>- Test phase sequence meter&nbsp;</p><p>-Measure voltage with multimeter</p><p>-Stop Generator test run Rental Generator 1 (200KW)&nbsp;</p><p>-De-Isolation for G-8925</p><p>-Start the generator&nbsp; test run Rental Generator 1 (200KW)&nbsp;</p><p>-EDG G-8935 selector switch off position&nbsp;</p><p>-G-8930 generator running , Only G-8930 ACB breaker open</p><p>-At that time, there is no bus power but UPS give the power to essential load for plant</p><p>- Rental Generator 1 (200KW) field breaker close</p><p>-G-8925&nbsp; ACB breaker close .There is a voltage but self breaker close the time, ELCB breaker trip</p><p>-Tom will continue for this one&nbsp;</p><p><br></p><p>&nbsp;</p><p><u><br></u></p><p><u><br></u></p><p><u>20.12.24&nbsp;</u><u>Activity</u><u></u></p><p>Power Cable installation diesel generator for FSD</p><p><u><br></u></p><p><u>Action</u></p><p><u><br></u></p><p><u>Kholer DG-03&nbsp; (50KW) at Admin</u></p><p><u><br></u></p><p>-Put the traffic cones around the generator&nbsp;</p><p>-Use barrier tape around generator&nbsp;</p><p>-Status 100 %</p><p><u><br></u></p><p><u>Denyo DG01&nbsp; (200KW)&nbsp; at Catering &amp; Laundry&nbsp;</u></p><p><u><br></u></p><p>-Install cable lug 8 numbers jamper power cable for DB to DB.</p><p>-Status 100 %</p><p><br></p><p><u>Rental Gen 2 (135KW) at HVAC Unit</u></p><p><u><br></u></p><p>-Install cable lug power cable&nbsp;</p><p>-Termination on Generator side</p><p>-Ready to install HVAC Panel&nbsp;</p><p>-Status 100 %</p><p><br></p><p><u>Rental Gen 1 (200KW)</u></p><p><br></p><p>-Perform Electrical Isolation for G-8925</p><p>-Termination on Rental Generator side</p><p>-Tightened all electrical connection</p><p>-Disconnect power cable from G-8925 one by one.</p><p>-Install rental generator power cable and G-8925 power cable.</p><p>-Status 90 %</p><p><br></p><p><u>19.12.24&nbsp;</u><u>Activity</u></p><p>Power Cable installation diesel generator for FSD</p><div><u><br></u></div><div><u>Action</u></div><div><p><u>Kholer DG-03&nbsp; (50KW) at Admin</u></p></div><p>-Measure the cable length&nbsp;</p><p>-Cut the 50SQMM wire for 4 pieces (19M Each)</p><p>-Install cable lug power cable&nbsp;</p><p>-Termination on Generator side</p><p>-Ready to install Admin Panel ACDB8104</p><p>-Status 90 %</p><p><br></p><p><u>Rental Gen 1 (200KW)</u></p><p>-Cable arrangement from G-8930 to G-8925</p><p>-At that time G-8925 is on duty.</p><p>-Start the generator G-8930&nbsp;</p><p>-Duty transfer G-8925 to G-8930</p><p>-G-8930 is on duty, G8925 is standby</p><p>-Install cable lug for one power cable (120SQMM)</p><p>--Status 60 %</p><p><br></p><p><u>18.12.24 Activity</u></p><p>Power Cable installation diesel generator for FSD</p><div><u><br></u></div><div><u>Action</u></div><div><p><br></p><p><u>Rental Gen 2 (135KW) at HVAC Unit</u></p><p>-Install cable lug power cable&nbsp;</p><p>-Termination on Generator side</p><p>-Ready to install HVAC Panel&nbsp;</p><p>-Status 90 %</p><p><br></p><p><u>YDN Gen 2 (8.4KW)&nbsp; at Water Treatment Unit</u></p><p>-Install cable lug power cable&nbsp;</p><p>-Termination on Generator side</p><p>-Ready to install&nbsp; UCP 8825 water treatment unit panel</p><p>-Status 100 %</p><p><br></p><p><u>Rental Gen 3&nbsp; (30KW)&nbsp; at Junior Accommodation</u></p><p>-Install cable lug power cable&nbsp;</p><p>-Termination on Generator side</p><p>-Ready to install ACDB8102 panel</p><p>-Status 100 %</p><p><br></p><p><u>YDN Gen 3&nbsp; (5KW)&nbsp; at Junior Accommodation</u></p><p>-Install cable lug power cable&nbsp;</p><p>-Termination on Generator side</p><p>-Ready to install Local DB panel at Clinic</p><p>-Status 100 %</p><p><br></p><p><u>Denyo DG01&nbsp; (200KW)&nbsp; at Catering &amp; Laundry&nbsp;</u></p><p>-Install cable lug power cable&nbsp;</p><p>-Termination on Generator side</p><p>-Arrange power cable lay down from generator to electrical room&nbsp;</p><p>-Need to press cable lug for looping cable</p><p>-Status 70 %</p></div>', NULL, '2024-12-24 16:15:43', '2024-12-24 16:16:14', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.Inst-Tec', false, 'ATL') RETURNING id INTO new_report_id;
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Nay', NULL, 'EXTERNAL', '2024-12-24 16:15:43', '2024-12-24 16:16:14', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.Inst-Tec');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Htet Aung', NULL, 'EXTERNAL', '2024-12-24 16:15:43', '2024-12-24 16:16:14', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.Inst-Tec');
