  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Verify air flow of vesda.', 'Instrument', 'CM', 'Completed', '2024-12-25', '<p>Verify air flow of vesda.</p><p>-&nbsp;Verify on Vesda in SWG Room, LER Room and Essential      Room.</p><p>-&nbsp;Normally,      the air flow rate of each pipe is displayed at 100% during normal      operation.</p><p>-&nbsp;The      test results of SWG Room and LER Room show that the air flow when the      vinyl tube is removed from the nozzle,&nbsp;the simulation at the first nozzle and the end nozzle of each main pipe has only slight, but changed when the vinyl was removed from the main pipe.</p><p>-&nbsp;Airflow threshold settings:      High Acceleration @ 130% and Minor High @ 120%, which when the vinyl tube      is removed from the nozzle will not produce any alarming results.</p><p>&nbsp; &nbsp; &nbsp;</p><p></p><ul type="disc"> </ul>', NULL, '2024-12-25 15:44:01', CURRENT_TIMESTAMP, 'PTTEP\\Art-Tech-Prod-Maint', NULL, false, 'ART') RETURNING id INTO new_report_id;
