  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Kraiwut', NULL, 'EXTERNAL', '2024-12-26 19:45:20', CURRENT_TIMESTAMP, 'PTTEP\\GBS.EI-Workshop', NULL);
