DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'DEP-8210 fire water pump (6MPM)', 'Mechanic', 'PM', 'Complete', '2024-12-27', '<p>DEP-8210 Fire water pump&nbsp;</p><p>- Perform mechanical 6MPM</p><p><b><u>Diesel engine.</u></b></p><p><b><u><br></u></b></p><ul type="disc">  <li>General inspection of engine for debris, foreign objects or      broken fittings OK.</li>  <li>Checked the condition of gauges OK.</li>  <li>Checked engine crankcase lube oil level OK.</li>  <li>Cleaned up engine crankcase breathers.</li>  <li>Checked belt tension OK.</li>  <li>Checked and lubricated all linkages OK.</li> </ul><ul type="disc">  <li>Checked engine coolant level OK.</li>  <li>Inspect zinc rod in row water system&nbsp;</li>  <li>Checked water cooling PH = 9</li>  <li>Found radiator cap seal damaged and replaced.</li>  <li>Visual inspected coolant line connection and hoses OK.</li>  <li>Visual inspected coolant pump OK.</li>  <li>Cleaned cooling water strainer.</li> </ul><p><b><u>&nbsp;</u></b></p><p><b><u>Fuel system.</u></b></p><p><b><u>&nbsp;</u></b></p><ul type="disc">  <li>Checked for leak, keep fuel tank full OK.</li>  <li>Drained sediment and water from fuel tank.</li>  <li>Cleaned up the fuel primary filter.</li> </ul><p><b><u>&nbsp;</u></b></p><p><b><u>Air induction system.</u></b></p><ul type="disc">  <li>Inspected air inlet system OK.</li>  <li>Cleaned up air filter.</li> </ul><p><b><u>&nbsp;</u></b></p><p><b><u>Hydraulic.</u></b></p><p><b><u>&nbsp;</u></b></p><ul type="disc">  <li>Checked Hyd. oil level was OK.</li>  <li>Cleaned up filter.</li>  <li>General cleaned.</li>  <li>Checked Hyd. oil start pressure found normal.&nbsp;&nbsp;&nbsp;&nbsp; </li> </ul><p><b><u>Pump.</u></b></p><p><b><u>&nbsp;</u></b></p><ul type="disc">  <li>Inspected      gland packing was OK.<b><u></u></b></li>  <li>Inspected      for coupling element crack and bolt tightness.<b><u></u></b></li>  <li>Lubricate      universal joint.<b><u></u></b></li>  <li>Inspected      right angle gear box was no leak.<b><u></u></b></li> </ul><p>&nbsp;</p><p>&nbsp;</p><p>                                        </p><p>&nbsp;</p>', '<p>Replace: Radiator cap Item: 19.09.43.007.3</p><p></p><table id="tableItem" class="display dataTable" cellspacing="0" aria-describedby="tableItem_info" style="border-collapse: separate; background-color: rgb(255, 255, 255); width: 1512px; margin: 0px auto; clear: both; color: rgb(85, 85, 85); font-family: Tahoma; font-size: 14px;"><tbody><tr class="even" style="background-color: transparent;"><td style="box-sizing: content-box; padding: 8px 10px; border-top: 1px solid rgba(0, 0, 0, 0.15); box-shadow: inset 0 0 0 9999px rgba(var(--dt-row-hover), 0.035);">Replace: Zinc rod Item: 19.09.45.205.3</td></tr></tbody></table><p></p>', '2024-12-27 18:53:58', '2024-12-28 17:41:38', 'PTTEP\\Mech_WS', 'PTTEP\\Mech_WS', false, 'G2N') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBN-DEP-8210', 'GBN-DEP-8210', 'FIRE WATER PUMP PACKAGE', NULL, NULL, 'FIRE WATER PUMP PACKAGE', 'GBN-SPP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
