  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS gas generator G-8920 unable to handle full load', 'Electrical & Instrument', 'CM', 'In Progress', '2024-12-27', '<p><b><u>Activity (Day 2)</u></b><br></p><p>Continue troubleshoot gas generator G-8920 "unable to handle full load"</p><p><b><u>Action</u></b></p><p>Measured the insulation resistance value and resistance value of the alternator.<br>No abnormal.<br>Plan to test run after FSD.<br><br><br></p><p><b ><u style="background-color: rgb(255, 255, 0);">History (24-Dec-2024)</u></b></p><p><span style="background-color: rgb(255, 255, 0);">Troubleshoot gas generator G-8920 "unable to handle full load"</span></p><div><b><u style="background-color: rgb(255, 255, 0);">Action</u></b></div><p><span style="background-color: rgb(255, 255, 0);">Troubleshoot gas generator G-8920 "unable to handle full load"&nbsp;&nbsp;</span></p><p><span style="background-color: rgb(255, 255, 0);">Replaced new AVR and swapped the oil pressure switch from G-8925.&nbsp;<br class="SCXW30501690 BCX0">Tested with full load, but G-8920 tripped after approximately 30 minutes.&nbsp;<br class="SCXW30501690 BCX0">Plan to troubleshoot.</span></p>', NULL, '2024-12-27 20:47:09', '2024-12-27 20:47:31', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.Inst-Tec', false, 'ATL') RETURNING id INTO new_report_id;
