-- Inserting report ID 23036
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'WP-20: Verify BC trip by remote SD from HIMA', 'Instrument', 'CM', 'Under Monitoring', '2024-12-27', '<p><b>Verify BC trip by remote SD from HIMA</b></p><p><b>Found</b> : "Remote ESD hard wire from client &lt;shutdown&gt;" alarm message at booster compressor HMI, but not found any US alarm to trip BC at platform HMI.</p><p><b>Action</b> :&nbsp; Measured supply voltage at backplane of rack 4 as found is 5.4 Vdc.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Adjusted 5Vdc power supply F7126 (3 modules) until voltage at backplane of rack4 drop to 5.0 Vdc.&nbsp; &nbsp;</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; - As Found : PS1 = 5.57 Vdc(Max position adjustment) ,PS2 = 5.58 Vdc ,PS3 = 5.86 Vdc</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - As Left&nbsp; &nbsp; &nbsp;: PS1 = 5.29 Vdc(Max position adjustment) ,PS2 = 5.43 Vdc ,PS3 = 5.41 Vdc</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Removed, visual inspection and clean PLC card as below by contact cleaner spray.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; - Card F7553 (Rack4 Slot17) watchdog.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; - Card F3430 (Rack4 Slot12) contact output card to trip BC activated.&nbsp; &nbsp; &nbsp; &nbsp;</p><p><br></p><p>/ **Platform total shutdown cause from CPU stop after install back the card F7553.&nbsp;</p><p><br></p><p><u>After resume platform</u>, found CPU show alarm "<b>3V3!</b>"</p><p><b>Found</b> : Supply voltage increase by itself from last adjustment point.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;PS1 = 5.9Vdc(Max position adjustment) ,PS2 = 6.3Vdc ,PS3 = 5.8Vdc, Rack4 = 5.7Vdc, V-input = 24.0Vdc.&nbsp;&nbsp;</p><p><b>Action</b> : Re-adjusted again after load platform stable and BC running.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;PS1 = 5.33Vdc(Max position adjustment) ,PS2 = 5.60Vdc ,PS3 = 5.36Vdc (Max position adjustment), Rack4 = 5.08Vdc, V-input = 23.6Vdc.&nbsp;&nbsp;</p><p><b>Result</b> : CPU alarm "<b>3V3!</b>" was disappeared and show normal running.</p>', NULL, '2024-12-27 20:56:37', '2024-12-27 21:49:26', 'PTTEP\\Bongkot.Inst-Lead', 'PTTEP\\Bongkot.Inst-Lead', false, 'G2N') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBN-X20-1003', 'GBN-X20-1003', 'BOOSTER COMPRESSOR PACKAGE WP20', NULL, NULL, 'BOOSTER COMPRESSOR PACKAGE WP20', 'GBN-WP20', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Anugoon', NULL, 'EXTERNAL', '2024-12-27 20:56:37', '2024-12-27 21:49:26', 'PTTEP\\Bongkot.Inst-Lead', 'PTTEP\\Bongkot.Inst-Lead');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Mech BC team', NULL, 'EXTERNAL', '2024-12-27 20:56:37', '2024-12-27 21:49:26', 'PTTEP\\Bongkot.Inst-Lead', 'PTTEP\\Bongkot.Inst-Lead');
