  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'DEP-8220 Fire water pump 6MPM', 'Mechanic', 'PM', 'Complete', '2024-12-28', '<p>DEP-8220 Fire water pump&nbsp;</p><p>- Perform mechanical 6MPM</p><p><u>Diesel engine.</u></p><p><u><br></u></p><ul type="disc"><li>General inspection of engine for debris, foreign objects or broken fittings OK.</li><li>Checked the condition of gauges OK.</li><li>Checked engine crankcase lube oil level OK.</li><li>Cleaned up engine crankcase breathers.</li><li>Checked belt tension OK.</li><li>Checked and lubricated all linkages OK.</li></ul><ul type="disc"><li>Checked engine coolant level OK.</li><li>Inspect zinc rod in row water system&nbsp;</li><li>Checked water cooling PH = 9</li><li>Found radiator cap seal damaged and replaced.</li><li>Visual inspected coolant line connection and hose&nbsp;</li><li>Visual inspected coolant pump OK.</li><li>Cleaned cooling water strainer OK</li></ul><p><u>&nbsp;</u></p><p><u>Fuel system.</u></p><p><u>&nbsp;</u></p><ul type="disc"><li>Checked for leak, keep fuel tank full OK.</li><li>Drained sediment and water from fuel tank.</li><li>Cleaned up the fuel primary filter.</li></ul><p><u>&nbsp;</u></p><p><u>Air induction system.</u></p><ul type="disc"><li>Inspected air inlet system OK.</li><li>Cleaned up air filter.</li></ul><p><u>&nbsp;</u></p><p><u>Hydraulic.</u></p><p><u>&nbsp;</u></p><ul type="disc"><li>Checked Hyd. oil level was OK.</li><li>Cleaned up filter.</li><li>General cleaned.</li><li>Checked Hyd. oil start pressure found normal.&nbsp;&nbsp;&nbsp;&nbsp;</li></ul><p><u>Pump.</u></p><p><u>&nbsp;</u></p><ul type="disc"><li>Inspected gland packing was OK.<u></u></li><li>Inspected for coupling element crack and bolt tightness.<u></u></li><li>Lubricate universal joint.<u></u></li><li>Inspected right angle gear box was no leak.</li></ul>', '<p>Found : Water seep leak at cooling water strainer body detail as picture.</p><p>Replace : Radiator cap Item: 19.09.43.007.3</p><p></p><table id="tableItem" class="display dataTable" cellspacing="0" aria-describedby="tableItem_info" style="border-collapse: separate; background-color: rgb(255, 255, 255); font-size: 14px; width: 1512px; margin: 0px auto; clear: both; color: rgb(85, 85, 85); font-family: Tahoma;"><tbody><tr class="even" style="background-color: transparent;"><td style="box-sizing: content-box; padding: 8px 10px; border-top: 1px solid rgba(0, 0, 0, 0.15); box-shadow: inset 0 0 0 9999px rgba(var(--dt-row-hover), 0.035);">Replace: Zinc rod Item: 19.09.45.205.3</td></tr></tbody></table>', '2024-12-28 18:06:27', '2025-09-13 13:58:21', 'PTTEP\\Mech_WS', 'PTTEP\\Bongkot.Valve', false, 'G2N') RETURNING id INTO new_report_id;
