  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Perform Ball Valve (12"900#) Hydrostatic Testing.', 'Mechanic', 'OTH', 'In Progress', '2024-12-29', '<p>Ball Valve (900#12") Valve Flushing and Greasing.</p><p>-Place the valve at vertical orientation.</p><p>-Exercise the valve and perform valve flushing.</p><p>-Perform valve grease injection.</p><p>-Cleaning the remaining old grease from valve cavity.&nbsp;</p><p><br></p><p>Ball Valve (900#12") Flange bolt tightening (By Hydra Tightening)</p><p>-Lift and position the valve at vertical orientation.</p><p>-Lift and install the blind flange (with fitting side) and RTJ Gasket to valve flange connection.</p><p>-Prepare the Hydra Tightening tools and equipment.</p><p>-Perform the bolts torque tightening sequence step by step.</p><p><br></p><p>Ball Valve (900#12") Hydrostatic Testing</p><p>-Prepare the scaffolding for position the valve.</p><p>-Lift and position the valve at horizontal orientation at scaffolding structure to secure.</p><p>-Install the air supply pressure fitting and vent fitting at blind flange.</p><p>-Prepare the Hydrostatic Testing tools and equipment.&nbsp;</p><p>-Perform the Hydrostatic leak testing sequence step by step by increasing the pressure.</p><p>1st step-50 bar (hold time-2mins)</p><p>&nbsp; No leakage found.</p><p>2nd step-80 bar&nbsp;</p><p>Found leakage at one end blind flange connection.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</p>', NULL, '2024-12-29 18:34:19', CURRENT_TIMESTAMP, 'PTTEP\\ZOC.Mech-Tec', NULL, false, 'ATL') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'OTH', 'OTH', 'Other', NULL, NULL, 'Other', 'ATL', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Neon', NULL, 'EXTERNAL', '2024-12-29 18:34:19', CURRENT_TIMESTAMP, 'PTTEP\\ZOC.Mech-Tec', NULL);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Saw Set', NULL, 'EXTERNAL', '2024-12-29 18:34:19', CURRENT_TIMESTAMP, 'PTTEP\\ZOC.Mech-Tec', NULL);
