  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, '2X-5310B, T/S air leak and malfunction auto drain', 'Mechanic', 'CM', 'Completed', '2024-12-28', '<p><u><i>To trouble shoot air leak at bottom joint O-ring of HP air passage pipe and malfunction auto drain.</i></u></p><p><i>- </i>Remove both of air passage pipes #1020 for O-rings seal inspection.(found one O-ring at leak point was melt damaged that caused of air leak ref#1030)</p><p>-Remove HP element inlet check valve for seat condition check.(found worn out condition)</p><p>-Clean all removed parts.</p><p>-Re-install HP C/V with new disc and its spring&nbsp; ref#6020/6030 and all new O-rings.</p><p>-Re-install air passage pipes with all new O-rings # 1030.</p><p>-Install monitoring gauge at after cooler auto drain and running test in lag mode.</p>', NULL, '2024-12-30 17:25:17', CURRENT_TIMESTAMP, 'PTTEP\\GBS.Mechanic-WorkS', NULL, false, 'G2S') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-2X-5310B', 'GBS-2X-5310B', 'AIR COMPRESSOR PACKAGE B', NULL, NULL, 'AIR COMPRESSOR PACKAGE B', 'GBS-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Naris P.', NULL, 'EXTERNAL', '2024-12-30 17:25:17', CURRENT_TIMESTAMP, 'PTTEP\\GBS.Mechanic-WorkS', NULL);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Dilok T.', NULL, 'EXTERNAL', '2024-12-30 17:25:17', CURRENT_TIMESTAMP, 'PTTEP\\GBS.Mechanic-WorkS', NULL);
