-- Inserting report ID 23128
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Yearly PM Inst and ESD Test AWP1', 'Instrument', 'PM', 'Completed', '2024-12-30', '<p>Perform Yearly PM Inst and&nbsp;ESD Test AWP1</p><p>- Found Water Ingress JBN-01001 and JBN-01007, then cleaned and tighten side plate of junction box</p><p>&nbsp;&nbsp;&nbsp;</p><p><br></p><p>&nbsp;&nbsp;&nbsp;&nbsp;<br></p><p><br></p><p>- Found HP1 pressure drop from 363 Bar to 6.9 Bar after activated ESD1</p><p>&nbsp;</p><p><br></p><p>- Verified by Reset and Activated ESD1 again by keep DHSV Selector Valve bloct at neutral position that found HP1 able to maintain pressure PT-01801 around 363 Bar as normal operation.</p><p>&nbsp;</p><p><br></p><p>- Trial to close DHSV Selector Valve one by one until HP1 was decresing rapidly by HS-01J1, suspected the selector valve was passing inside from open to close side.</p><p><br></p><p><br></p><p>- Replaced new selector valve HS-01J1 then test function.&nbsp;</p><p>&nbsp;&nbsp;&nbsp;</p><p><br></p><p>&nbsp;&nbsp;&nbsp;<br></p><p><br></p><p>- Found Export Valve SDV-01001 unable to open after replace new solenoid and pilot valve by quick exhaust was always vent during energized solenoid, then replaced new quick exhaust valve and function test.</p><p>Quick Exhaust Valve: Versa&nbsp;QE-5-316</p><p>&nbsp;&nbsp;</p><p><br></p><p><br></p>', '<p>Keep always open DHSV-01E1 of Water Injection Well-E by Select HYD Supply from External HP1 Accumulator and connect pressure gauge for monitor pressure during perform ESD test.</p><p>&nbsp;&nbsp;&nbsp;</p><p><br></p><p>Refer to :&nbsp;13236-PDR-1-WIS-1-STI-042-R01 SWITCH HYDRAULIC SUPPLY SOURCE FOR PDIW 1</p><hr><p><br></p><p>AWP1 ESD Test Data:</p><p>https://pttep.sharepoint.com/sites/THART/EI/Forms/AllItems.aspx?id=%2Fsites%2FTHART%2FEI%2F04%20%2D%20Electrical%5FInstrument%2F00%2DESD%20Test%20Report%20and%20Yearly%20PM%20report%2F01%2DESD%20Reports%20and%20HS%20test%2F2024%2FAWP01&amp;viewid=415f9878%2Da53c%2D45fe%2D8639%2De524c6aa2067</p>', '2024-12-30 17:34:06', '2025-01-05 22:04:58', 'PTTEP\\Art-Tech-Prod-Maint', 'PTTEP\\Art-Tech-Prod-Maint', false, 'ART') RETURNING id INTO new_report_id;
