  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Perform stroke test HOV82009 of MOGE outlet line', 'Electrical & Instrument', 'OTH', 'In Progress', '2024-12-30', '<p><u><b>Today Activity&nbsp;</b></u><br>Perform stroke test for HOV-82009 of MOGE outlet line.</p><p><br></p><p><u><b>Issued</b></u></p><p>&nbsp;- Failed closed signal and showed travelling on DCS.</p><p><br></p><p><u><b>Action</b></u></p><p>- Checked limit switch for CLOSE and OPEN</p><p>- Found loop termination for CLOSE signal.</p><p>- Change termination and retightened.</p><p>- Showed CLOSE signal correctly.</p><p>- Back to normal.</p><p>- Found OPEN limit switch was low reliability.</p><p>( common &amp; NO = 98 Ohm)</p><p>- Perform exercise for OPEN limit switch.</p><p>- Back to normal condition.</p><p>- Performed stroke test HOV-82009.</p><p>- Opening time - 4.01 sec)</p><p>- Found Close command was failed and valve not action.</p><p>- Continue troubleshoot tomorrow.</p><p><br></p><p><br></p>', NULL, '2024-12-30 18:15:16', '2024-12-30 18:15:43', 'PTTEP\\ZOC.Elec-Tec', 'PTTEP\\ZOC.Elec-Tec', false, 'ATL') RETURNING id INTO new_report_id;
