  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Troubleshooting AWP-13 power loss', 'Electrical', 'CM', 'Completed', '2024-12-30', '<p>Troubleshooting AWP-13 power loss.</p><p>- First verify not found Q1,Q2 and Q3 trip.</p><p>- Found VSM of load disconnect due to VDC low.</p><p>- Measure battery bank total@27.48 VDC and out put DC-DC 25.64 VDC</p><p>- Measure battery performance of 13 cell volt average 2.10 VDC and internal resistance average 0.9 Ohm.&nbsp;</p><p>- Then start up platform and boost charge battery bank from 27.48 to 29.00 VDC</p><p>- Found valve TEG gas supply closed. T/R by replace new solenoid and pilot completed set.</p>', 'G:\\ARTShare\\Selective Access\\02-PAT-M\\02-PAT-M_El\\04 - Electrical_Instrument\\18-EI Pictures Database\\2 AWP\\AWP_PHASE1C (11-14)\\AWP13\\02 DC System\\DCDB-440\\TR DCDB loss power', '2024-12-30 19:01:14', '2024-12-30 19:08:37', 'PTTEP\\Art-Tech-Prod-Maint', 'PTTEP\\Art-Tech-Prod-Maint', false, 'ART') RETURNING id INTO new_report_id;
