-- Inserting report ID 23159
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Support Exterran BC team to T/S BC AWP20 shutdown', 'Automation', 'CM', 'Under Monitoring', '2024-12-30', '<div class="ewa-rteLine">Support Exterran BC team to troubleshooting BC AWP20 shutdown.</div><div class="ewa-rteLine">- Asfound at site. BC tripped by no show alarm.</div><div class="ewa-rteLine">- Tried to reset package. Found PLC rack 0 24 VDC power lose.</div><div class="ewa-rteLine">- Tried turn on breaker found power supply PLC no power. Checked incoming 24 VDC found normal but power supply cannot operated.</div><div class="ewa-rteLine">- Information BC team to remove all PLC module then turn on power again. Found still lose power.</div><div class="ewa-rteLine">- Information BC team remove power supply module out of rack. Then turn on power found power supply working properly.</div><div class="ewa-rteLine">- Suspect PLC rack malfunction. BC team removed rack for cleaned by contact cleaner. Then function test. Found it was working properly.</div><div class="ewa-rteLine">- BC team replaced new communication card. Case of BC communication failure.</div><div class="ewa-rteLine">- BC team replaced the new one of PLC.</div><div class="ewa-rteLine">- Restart BC.</div><div class="ewa-rteLine"><div class="ewa-rteLine">Preparation BC spare part and handover to Exterran BC team.</div><div class="ewa-rteLine">- Download HMI project to the recondition HMI to replace BC package AWP20. Due to HMI&nbsp;defeted.</div><div class="ewa-rteLine"><br></div></div>', NULL, '2024-12-30 22:10:18', CURRENT_TIMESTAMP, 'PTTEP\\Art.Automation', NULL, false, 'ART') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-WP20-PRO-PROD-3C2061-PKG', 'ART-WP20-PRO-PROD-3C2061-PKG', 'BOOSTER COMPRESSOR ON AWP20 PACKAGE', NULL, NULL, 'BOOSTER COMPRESSOR ON AWP20 PACKAGE', 'ART-WP20', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Piriyut K.', NULL, 'EXTERNAL', '2024-12-30 22:10:18', CURRENT_TIMESTAMP, 'PTTEP\\Art.Automation', NULL);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'BC Exterran', NULL, 'EXTERNAL', '2024-12-30 22:10:18', CURRENT_TIMESTAMP, 'PTTEP\\Art.Automation', NULL);
