-- Inserting report ID 23178
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Perform stroke test HOV82009 of MOGE outlet line', 'Electrical & Instrument', 'OTH', 'In Progress', '2024-12-31', '<p><u><b>Today Activity&nbsp;</b></u><br>Perform stroke test for HOV-82009 of MOGE outlet line. (Day-2)<u><b></b></u></p><p><u><b>Issued</b></u></p><p>&nbsp;- HOV was not closed by CLOSE command at HOV-82009.</p><p><u><b>Action</b></u></p><p>- Checked incoming voltage of solenoid valve for CLOSE in local junction box.</p><p>- Remove HOV cover.</p><p>- Checked termination of CLOSE solenoid valve.</p><p>- Found cable loosen.</p><p>- Retighten termination.</p><p>- Performed HOV-82009 full stroke test for OPEN and CLOSE by remote and local.</p><p>- Passed and normal condition.</p><p><br></p><p><span style="background-color: rgb(255, 255, 0);"><u><b>History (31-Dec-2024)</b></u><br>Perform stroke test for HOV-82009 of MOGE outlet line.</span></p><p><u><b style="background-color: rgb(255, 255, 0);">Issued</b></u></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;- Failed closed signal and showed travelling on DCS.</span></p><p><u><b style="background-color: rgb(255, 255, 0);">Action</b></u></p><p><span style="background-color: rgb(255, 255, 0);">- Checked limit switch for CLOSE and OPEN  </span></p><p><span style="background-color: rgb(255, 255, 0);">- Found loosen termination for CLOSE signal.</span></p><p><span style="background-color: rgb(255, 255, 0);">- Change termination and retightened.</span></p><p><span style="background-color: rgb(255, 255, 0);">- Showed CLOSE signal correctly.</span></p><p><span style="background-color: rgb(255, 255, 0);">- Back to normal.</span></p><p><span style="background-color: rgb(255, 255, 0);">- Found OPEN limit switch was low reliability.</span></p><p><span style="background-color: rgb(255, 255, 0);">( common &amp; NO = 98 Ohm)</span></p><p><span style="background-color: rgb(255, 255, 0);">- Perform exercise for OPEN limit switch.</span></p><p><span style="background-color: rgb(255, 255, 0);">- Back to normal condition.</span></p><p><span style="background-color: rgb(255, 255, 0);">- Performed stroke test HOV-82009.</span></p><p><span style="background-color: rgb(255, 255, 0);">- Opening time - 4.01 sec)</span></p><p><span style="background-color: rgb(255, 255, 0);">- Found Close command was failed and valve not action.</span></p><p><span style="background-color: rgb(255, 255, 0);">- Continue troubleshoot tomorrow.</span></p><p><br></p><p><br></p>', NULL, '2024-12-31 18:00:43', '2024-12-31 19:23:45', 'PTTEP\\ZOC.Elec-Tec', 'PTTEP\\ZOC.Inst-Tec', false, 'ATL') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-HOV-82009', 'ATL-OC-HOV-82009', 'HOV,12"PG-81031 underground line to MOGE', NULL, NULL, 'HOV,12"PG-81031 underground line to MOGE', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Htet', NULL, 'EXTERNAL', '2024-12-31 18:00:43', '2024-12-31 19:23:45', 'PTTEP\\ZOC.Elec-Tec', 'PTTEP\\ZOC.Inst-Tec');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Nay', NULL, 'EXTERNAL', '2024-12-31 18:00:43', '2024-12-31 19:23:45', 'PTTEP\\ZOC.Elec-Tec', 'PTTEP\\ZOC.Inst-Tec');
