-- Inserting report ID 23234
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S Suvival Craft2 (X-5950) lighting malfunction', 'Electrical', 'CM', 'Completed', '2025-01-02', '<p>T/S lighting of Suvival Craft2 (X-5950) malfunction.</p><p>- Found all lighting (Instrument, Navigation, Cabin and Spot Light) in life boat2 are not function when turned on switch.</p><p>- Measured the voltage at outgoing of Main and Emergency switch is 13.41 VDC as normal condition but no voltage at incoming of sub-switch while the fuses is normal.</p><p>- Measure resistance of cable from Main switch to Fuses and Sub-Switch that found the resistance is 1.5 kOhm which quite high.</p><p>- Found the temperature at cable junction (under insulation tape) is quite high when turned on Main and Emergency switch.&nbsp;</p><p>&nbsp;&nbsp;<br></p><p><br></p><p>- Found loose cable while unpacking tape for verified due to improper connecting.</p><p>&nbsp;&nbsp;<br></p><p><br></p><p>- Fixed the cable junction&nbsp;by cable lugs and function test.</p><p>&nbsp;&nbsp;&nbsp;&nbsp;<br></p>', '<p>More Picture:</p><p><b>https://pttep.sharepoint.com/sites/THART/EI/Forms/AllItems.aspx?id=%2Fsites%2FTHART%2FEI%2F04%20%2D%20Electrical%5FInstrument%2F18%2DEI%20Pictures%20Database%2F3%5FAQP%2FSurvival%20Craft%5FLife%20Boat%5F59xx%2FSURVIVAL%5FCRAFT2%5FX%2D5950%2F20250102%5FLighting%5FFail&amp;viewid=415f9878%2Da53c%2D45fe%2D8639%2De524c6aa2067</b></p>', '2025-01-02 16:22:45', '2025-01-02 17:56:28', 'PTTEP\\Art-Tech-Prod-Maint', 'PTTEP\\Art-Tech-Prod-Maint', false, 'ART') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-X-5950', 'ART-X-5950', 'SURVIVAL CRAFT NO.2', NULL, NULL, 'SURVIVAL CRAFT NO.2', 'ART-QP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Meechai D.', NULL, 'EXTERNAL', '2025-01-02 16:22:45', '2025-01-02 17:56:28', 'PTTEP\\Art-Tech-Prod-Maint', 'PTTEP\\Art-Tech-Prod-Maint');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Nitipong I.', NULL, 'EXTERNAL', '2025-01-02 16:22:45', '2025-01-02 17:56:28', 'PTTEP\\Art-Tech-Prod-Maint', 'PTTEP\\Art-Tech-Prod-Maint');
