  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBN-TG-8610', 'GBN-TG-8610', 'TURBO GENERATOR 4 PACKAGE', NULL, NULL, 'TURBO GENERATOR 4 PACKAGE', 'GBN-SPP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
