-- Inserting report ID 23318
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S HCDP analyzer was not displaying correct readi', 'Instrument', 'CM', 'Completed', '2025-01-04', '<div>T/S HCDP analyzer&nbsp;was not displaying correct reading in CCR</div><div><br></div><div>- The dew point analyzer (2AIT-36315) was not providing valid readings in the CCR but showed a reading locally at 16°C and sample pressure of 52 bar.</div><div>- Applied standard gas (propane 99.95%) to the system and tested the dew point analyzer at a point with 2.1 bar. The expected dew point was -12.19°C ±1°C, and the result measured by the analyzer was -13.6°C. This result was normal&nbsp;indicating the analyzer could provide accurate measurements</div><div>- Verified the loop by opening the 2RIO-1303 and found that the power supply (KDF2-STC4-Ex1) indicator light was off. perform tightened the wiring connections, which restored the power supply to normal,&nbsp;</div><div>- After restoring the power supply, the analyzer readings returned to normal, and it was able to show accurate dew point values at 17°C and 52 bar sample pressure. The analyzer was able to provide accurate readings again.</div><div><br></div><div><br></div>', NULL, '2025-01-04 14:52:47', '2025-01-04 16:57:37', 'PTTEP\\GBS.Turbine-Tech', 'PTTEP\\PooritadT', false, 'G2S') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-2AIT-36315', 'GBS-2AIT-36315', 'HC DEW POINT AIT', NULL, NULL, 'HC DEW POINT AIT', 'GBS-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'PooritadT', NULL, 'EXTERNAL', '2025-01-04 14:52:47', '2025-01-04 16:57:37', 'PTTEP\\GBS.Turbine-Tech', 'PTTEP\\PooritadT');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'WiroteO', NULL, 'EXTERNAL', '2025-01-04 14:52:47', '2025-01-04 16:57:37', 'PTTEP\\GBS.Turbine-Tech', 'PTTEP\\PooritadT');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'SorodP', NULL, 'EXTERNAL', '2025-01-04 14:52:47', '2025-01-04 16:57:37', 'PTTEP\\GBS.Turbine-Tech', 'PTTEP\\PooritadT');
