  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S 3XA-21970 Navigation common alarm', 'Electrical', 'CM', 'In Progress', '2025-01-04', '<div class="ewa-rteLine">T/S 3XA-21970 Navigation common alarm from battery low-low.</div><div class="ewa-rteLine">- Found battery deep discharged at 2.19Vdc (24Vdc system) and hight internal resistant morethan 3.1Ohm per cell.</div><div class="ewa-rteLine">- Charged battery by portable charger about 6 hrs. at charging current 25A.</div><div class="ewa-rteLine">- After charging by portable charger found battery voltage 25.43 Vdc and internal resistance between 2.6-38 mOhm.</div><div class="ewa-rteLine">- Function tested solar charger, found normal ( Solar 42.24V / 2.8A ).</div><div class="ewa-rteLine">- Keep navigation aid lanterns fed power from 3DCDB-21-440 system until battery fully charge.</div><div class="ewa-rteLine"><br></div>', NULL, '2025-01-04 18:23:37', '2025-01-04 19:06:28', 'PTTEP\\Art-Tech-Prod-Maint', 'PTTEP\\Art-Tech-Prod-Maint', false, 'ART') RETURNING id INTO new_report_id;
