  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S the trend data log of SCADA2 HMI Servers', 'Automation', 'CM', 'Completed', '2025-01-05', '<p>T/S the trend data log of SCADA2 HMI Servers (AWP18-38) has not been recording since 21 Nov 2024.</p><p>Delete the data log models program for AWP18-38 on SCADA2 HMI Server01. Then, copy the data log model MDF file from SCADA2 HMI Server02 and import it to SCADA2 HMI Server01 and function test step as below.</p><p>1.Copy MDF file from SCADA2 HMIServer02</p><p></p><p><br></p><p>2.Delete datalog model AWP18-38 at HMIServer01</p><p></p><p><br></p><p>3.Delete all file DLGLOG at HMISERVER01</p><p></p><p><br></p><p>4.Add component MDF from HMIServer02</p><p></p><p><br></p><p>5.Restart the HMIserver01 and command DataLogOn awp18_20</p><p></p><p><br></p><p>Refer FactoryTalk View SE: Error unknown error occurred in the server Framework solution 1 and solution 4</p><p><br></p><p><br></p><p><br></p><p><br></p>', '<a href="https://pttep.sharepoint.com/:f:/s/THART/EoK3Dk_RIhJHk3_IKfhgV20BlI31gZ0rbmQjzkuF8BUQgQ?e=aytfTV">20250105_SCADA2_HMI_cannot_recordDatalog</a>', '2025-01-05 22:08:29', '2025-01-05 22:13:36', 'PTTEP\\Art.Automation', 'PTTEP\\Art.Automation', false, 'ART') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-PP-SCADA.ASY', 'ART-PP-SCADA.ASY', 'APP SCADA RADIO ASSEMBLY', NULL, NULL, 'APP SCADA RADIO ASSEMBLY', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
