  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Pooritad', NULL, 'EXTERNAL', '2025-01-07 16:44:14', '2025-01-07 16:46:00', 'PTTEP\\GBS.Turbine-Tech', 'PTTEP\\GBS.Turbine-Tech');
