  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-P-8845A', 'ATL-OC-P-8845A', 'Treated Water Transfer Pump A', NULL, NULL, 'Treated Water Transfer Pump A', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Neon', NULL, 'EXTERNAL', '2025-01-07 16:52:53', '2025-01-08 14:23:05', 'PTTEP\\ZOC.Mech-Tec', 'PTTEP\\ZOC.Se-Mech');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Chan', NULL, 'EXTERNAL', '2025-01-07 16:52:53', '2025-01-08 14:23:05', 'PTTEP\\ZOC.Mech-Tec', 'PTTEP\\ZOC.Se-Mech');
