  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS G8920 shutdown with radiator fault alarm', 'Electrical & Instrument', 'CM', 'Completed', '2025-01-07', '<p><b><u>Today Activity</u></b></p><p>Troubleshoot G8920 due to shutdown with radiator fan fault.</p><p><br></p><p><b><u>Action</u></b></p><p>Isolated G8920 for troubleshooting.</p><p>Checked and verified the G8920 panel condition.</p><p>Found that ventilation fan1 overload trip.</p><p>Opened the hatch of Ventilation fans.</p><p>Checked the fans condition&nbsp;</p><p>Ohm, Mega testing of all winding and wires are good and still in normal rating.</p><p>Opened the Junction box.</p><p>Found that fan 1 wire connections were burned.&nbsp;</p><p>Rectified the connection with new terminal blocks.</p><p>After that test run G8920.</p><p>Test run G8920 with share and full load.&nbsp;</p><p>G8920 are back in service. (complete)</p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">History (1.1.2025)</span></p><p><span style="background-color: rgb(255, 255, 0);"><u>Today Activity&nbsp;</u><br>Verify rad fan fault alarm at G8920.</span></p><p><u style="background-color: rgb(255, 255, 0);">Issued</u></p><p><span style="background-color: rgb(255, 255, 0);">- G-8920 was not ready to start due to Rad Fan Fault alarm.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><u style="background-color: rgb(255, 255, 0);">Action</u></p><p><span style="background-color: rgb(255, 255, 0);">- Checked relays in GCP-8920.</span></p><p><span style="background-color: rgb(255, 255, 0);">- Checked magnetic connector MS1 and MS2.</span></p><p><span style="background-color: rgb(255, 255, 0);">- Checked radiator fan cable termination condition.</span></p><p><span style="background-color: rgb(255, 255, 0);">- Found Radiator breaker contact was closed. (Abnormal)</span></p><p><span style="background-color: rgb(255, 255, 0);">- Found cable loosen in breaker.</span></p><p><span style="background-color: rgb(255, 255, 0);">- Then, retighten cables.</span></p><p><span style="background-color: rgb(255, 255, 0);">- Alarm can be cleared.</span></p><p><span style="background-color: rgb(255, 255, 0);">-Back to normal</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">History (28.12.24)</span></p><p><span style="background-color: rgb(255, 255, 0);"><u>Activity (Day 3)</u></span></p><p><span style="background-color: rgb(255, 255, 0);">Continue troubleshoot gas generator G-8920 " Unable to handle full load".</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><u style="background-color: rgb(255, 255, 0);">Action</u></p><p><span style="background-color: rgb(255, 255, 0);">- Checked relay contact resistance.</span></p><p><span style="background-color: rgb(255, 255, 0);">- Found 1GR relay was high value.&nbsp;</span></p><p><span style="background-color: rgb(255, 255, 0);">- Replace new one.</span></p><p><span style="background-color: rgb(255, 255, 0);">- Other relays are normal condition.<br>-Plan to function after FSD completed.<br><br></span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><u style="background-color: rgb(255, 255, 0);">History (Day 2) (27-Dec-2024)</u></p><p><span style="background-color: rgb(255, 255, 0);">Continue troubleshoot gas generator G-8920 "unable to handle full load"</span></p><p><u style="background-color: rgb(255, 255, 0);">Action</u></p><p><span style="background-color: rgb(255, 255, 0);">Measured the insulation resistance value and resistance value of the alternator.<br>No abnormal.<br>Plan to test run after FSD.<br><br><br></span></p><p><u style="background-color: rgb(255, 255, 0);">History (24-Dec-2024)</u></p><p><span style="background-color: rgb(255, 255, 0);">Troubleshoot gas generator G-8920 "unable to handle full load"</span></p><div><u style="background-color: rgb(255, 255, 0);">Action</u></div><p><span style="background-color: rgb(255, 255, 0);">Troubleshoot gas generator G-8920 "unable to handle full load"&nbsp;&nbsp;</span></p><p><span style="background-color: rgb(255, 255, 0);">Replaced new AVR and swapped the oil pressure switch from G-8925.&nbsp;<br class="SCXW30501690 BCX0">Tested with full load, but G-8920 tripped after approximately 30 minutes.&nbsp;<br class="SCXW30501690 BCX0">Plan to troubleshoot.</span></p>', NULL, '2025-01-07 21:16:02', '2025-01-13 19:57:57', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.Inst-Tec', false, 'ATL') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-G-8920-PACK', 'ATL-G-8920-PACK', 'Gen, ZOC Gas Generator package1', NULL, NULL, 'Gen, ZOC Gas Generator package1', 'ATL', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Noble', NULL, 'EXTERNAL', '2025-01-07 21:16:02', '2025-01-13 19:57:57', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.Inst-Tec');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Bone', NULL, 'EXTERNAL', '2025-01-07 21:16:02', '2025-01-13 19:57:57', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.Inst-Tec');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Jack', NULL, 'EXTERNAL', '2025-01-07 21:16:02', '2025-01-13 19:57:57', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.Inst-Tec');
