  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Anuchit P.', NULL, 'EXTERNAL', '2025-01-08 13:55:13', '2025-01-08 14:05:47', 'PTTEP\\Turbine', 'PTTEP\\Turbine');
END $$;

