-- Inserting report ID 23526
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S check valve passing in P8845A ', 'Mechanic', 'CM', 'Waiting for Material', '2025-01-08', '<p>Continuous report of&nbsp;Verify and fix abnormal backflow at water treatment pump P-8845A</p><p><br></p><p>- Cleaning good check valve (2" 150 class) from surplus and make new gasket&nbsp;</p><p>- remove upstream check valve&nbsp;</p><p>- install new check valve and found 5mm gap because good check valve is shorter 5mm</p><p>-good check valve 20mm, and defective old check valve 20.5mm length&nbsp;</p><p>- insert new addition rubber gasket as a spacer (4mm)&nbsp;</p><p>- test run again. and found up upstream is OK and downstream check valve is passing.&nbsp;</p><p><br></p><p>- found start stop is too short about 10 sec and check the outlet transmitter&nbsp;</p><p>- found the small stone blockage&nbsp;</p><p>-test run again and found bladder A pressure drop to zero&nbsp;</p><p>-drain water from bladder A (T8950A)</p><p>-Refill air to the bladder B with portable air compressor.&nbsp;</p><p>- Fill up-to 2.2 Bar and test run again&nbsp;</p><p>-found start and stop pump time is about 1 minutes&nbsp;</p><p><br></p><p>- Drain water from Bladder B (T8950)&nbsp;</p><p>- Refill air to bladder A about 2.4 bar&nbsp;</p><p>- test run again ad found start and stop pump time about 2 minutes&nbsp;</p><p>- found air passing at the outlet PSV popping valve.&nbsp;</p><p>- discuss with operator and pipe sup.&nbsp;</p><p>- waiting for material&nbsp;</p><p>- line up to B line&nbsp;</p><p><br></p><p>-Inform to PMO/E, Ma Khaing for spare part&nbsp;</p><p>-She transfer to EEM. team&nbsp;</p><p><br></p>', NULL, '2025-01-08 18:09:26', CURRENT_TIMESTAMP, 'PTTEP\\ZOC.Se-Mech', NULL, false, 'ATL') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-MCC-8845A', 'ATL-OC-MCC-8845A', 'CLP of Treat water tranfer pump A', NULL, NULL, 'CLP of Treat water tranfer pump A', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Neon', NULL, 'EXTERNAL', '2025-01-08 18:09:26', CURRENT_TIMESTAMP, 'PTTEP\\ZOC.Se-Mech', NULL);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Chan', NULL, 'EXTERNAL', '2025-01-08 18:09:26', CURRENT_TIMESTAMP, 'PTTEP\\ZOC.Se-Mech', NULL);
