  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'harry', NULL, 'EXTERNAL', '2025-01-08 18:09:26', CURRENT_TIMESTAMP, 'PTTEP\\ZOC.Se-Mech', NULL);
