  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Adjust WHRU-4840 Power Pack pressure ', 'Turbine E&I', 'CM', 'In Progress', '2025-01-12', '<p>Due to PIT-4840 got high-pressure alarm from time to time.&nbsp;</p><p>&nbsp;- Found the reading pressure from PIT-4840 compare with the local pressure were equalized.</p><p>&nbsp;- 1st found the pressure was increased to 136 barg vai the unit was stopped.</p><p>&nbsp; &nbsp;Then with little release pressure, the Hyd pressure was claimed down to 115 barg the high alarm on CCR was reset.</p><p>&nbsp;- 2nd, During the unit FGC#1 was running, found the Hyd power pack pressure was increased to 125 barg ( high alarm). This time required operator assistance and released some out pressure, also declined litter on the Unloading valve adjusting screw. After the PIT-4840 was reading 115 barg the alarm in CCR was cleared.</p><p><br></p><p>Under monitoring.&nbsp;</p><p><br></p>', NULL, '2025-01-12 22:25:49', CURRENT_TIMESTAMP, 'PTTEP\\Arthit.EI-Turbine', NULL, false, 'ART') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-HPU-4840', 'ART-HPU-4840', 'HYDRAULIC POWER PACK - FEED GAS COMP', NULL, NULL, 'HYDRAULIC POWER PACK - FEED GAS COMP', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Tawatchai', NULL, 'EXTERNAL', '2025-01-12 22:25:49', CURRENT_TIMESTAMP, 'PTTEP\\Arthit.EI-Turbine', NULL);
