  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Performed Monthly PM for Two Post Car Lift', 'Mechanic', 'PM', 'Completed', '2025-01-13', '<div>Performed Monthly PM of two post car lift</div><div><br></div><div><br></div><div>Working steps:</div><div><br></div><div>-Performed electrical isolation by emergency stop button.&nbsp;</div><div><br></div><div>-Checked two post mounting bolts tightness. (Torque 100 N-m)</div><div><br></div><div>-Checked cylinders (primary and secondary) for any leakage.</div><div><br></div><div>-Checked hydraulic hoses if any damage and leakage.</div><div><br></div><div>-Checked wiring sling rope condition and greasing.</div><div><br></div><div>-Checked mechanical locks and limit switch functional test.</div><div><br></div><div>-Checked arm gear if any corrosion and damage.</div><div><br></div><div>-Test without load and check if any abnormal noise and condition.</div><div><br></div><div><br></div><div><br></div><div>Required tools</div><div><br></div><div>-Torque wrench and Open wrench 30mm.</div>', NULL, '2025-01-13 10:32:37', CURRENT_TIMESTAMP, 'PTTEP\\ZOC.Mech-Tec', NULL, false, 'ATL') RETURNING id INTO new_report_id;
