-- Inserting report ID 23696
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Weekly running test Fire water Pump.', 'Mechanic', 'PM', 'Completed', '2025-01-13', '<p>- Inform CCR to Open RTJ.</p><p>- Checked Fire water pump condition and recorded parameter in log sheet before start unit.</p><p>- Asked Production operator to run Hypochorite injection 10 Minute.</p><p>- Co-ordinated with Production Operator for start function.</p><p>- Start running fire water pump and observe condition and recorded parameter in log sheet.</p><p>- Running test approximately 20-30 Minute</p><p>- Stop Hypochorite injection.</p><p>- Inform CCR to stop fire water pump by Manual stop at local panel.</p><p>- Inform to Closed RTJ.</p><p><br></p><p>Note:</p><p>P-5700 Started by manual start at local panel with Electrical.&nbsp;</p><p>P-5720 Started by manual start at local panel with Electrical.</p><p>P-5740 Started by manual start at local panel with Air</p><p>And All of above stopped by manual stop at local panel.</p>', NULL, '2025-01-13 16:02:45', CURRENT_TIMESTAMP, 'PTTEP\\Art.MechBC', NULL, false, 'ART') RETURNING id INTO new_report_id;
