  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Performed Monthly PM on G-8020 at ZBV-1', 'Mechanic', 'PM', 'Completed', '2025-01-14', '<div><b style="font-size: 14px;"><i><u>Today Activity</u></i></b></div><div><p>Performed Monthly PM Diesel Generator, G-8020.</p><p><br></p><p><b><u><i>Action</i></u></b></p><p>- Checked and cleaned the air filter.</p><p>- Checked the air service indicator.</p><p>- Checked the radiator cap condition.</p><p>- Checked the coolant level and its condition.</p><p>- Checked the lube oil level and its condition.</p><p>- Checked and adjusted the belt tension and its condition.</p><p>- Checked and tightened the loosening bolts and nuts.</p><p>- Replaced the exhaust rain flapper.</p><p>- Housekeeping and test run.</p><p>- Recorded the parameters and checked any abnormalities.</p></div>', NULL, '2025-01-14 14:58:01', CURRENT_TIMESTAMP, 'PTTEP\\ZOC.Mech-Tec', NULL, false, 'ATL') RETURNING id INTO new_report_id;
