  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S 2PIT-31622 and 2PIT-31607 their readings are s', 'Instrument', 'CM', 'Completed', '2025-01-16', '<div>T/S Two pressure transmitters (2PIT-31622 and 2PIT-31607) were installed at the same point and with the same calibration range of 0-20 Bar. but their readings are slightly different</div><div>2PIT-31622:</div><div>Zero error was observed at 0.86 Bar.</div><div>Recalibration and accuracy checks were performed, and the readings returned to normal.</div><div>After being put online, the reading stabilizes at 10.68 Bar.</div><div><br></div><div>2PIT-31607:</div><div>Span error was observed at 20.04 Bar.</div><div>Recalibration and accuracy checks were performed, and the readings returned to normal.</div><div>After being put online, the reading stabilizes at 10.66 Bar.</div><div><br></div><div>After calibration, the readings of both transmitters are very close: 10.68 Bar (2PIT-31622) and 10.66 Bar (2PIT-31607). The small difference (0.02 Bar) might be within the normal tolerance range of the instruments</div>', NULL, '2025-01-16 10:57:09', '2025-01-16 11:04:06', 'PTTEP\\PooritadT', 'PTTEP\\PooritadT', false, 'G2S') RETURNING id INTO new_report_id;
