-- Inserting report ID 23885
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS G8920 with new timing sensors.', 'Electrical & Instrument', 'CM', 'In Progress', '2025-01-18', '<p><u>Today Activity</u></p><p>TS G8920 can''t start during cranking.</p><p><u><br></u></p><p><u>Action&nbsp;</u></p><p>Replace with new timing sensors.</p><p>Connect AFR with laptop and monitor the speed.</p><p>Test run G8920.</p><p>Still can''t start RPM (125RPM).</p><p>In Progress.</p><p><br></p><p><span style="background-color: rgb(255, 255, 0);">History (17.01.2025)</span></p><p><u style="background-color: rgb(255, 255, 0);">Today Activity</u></p><p><span style="background-color: rgb(255, 255, 0);">Troubleshoot G8920 start fail.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><u style="background-color: rgb(255, 255, 0);">Action.</u></p><p><span style="background-color: rgb(255, 255, 0);">Isolate the G8920.</span></p><p><span style="background-color: rgb(255, 255, 0);">Replace with old iAVR inside display panel.</span></p><p><span style="background-color: rgb(255, 255, 0);">Clean the magnetic pick up of G8920&nbsp;</span></p><p><span style="background-color: rgb(255, 255, 0);">Test run with battery jump charger.</span></p><p><span style="background-color: rgb(255, 255, 0);">G8920 is stuck in cracking state</span></p><p><span style="background-color: rgb(255, 255, 0);">found that gas valve actuator is not operated. (In Progress)</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">History (16.01.2024)</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp;<u>Today Activity</u></span></p><p><span style="background-color: rgb(255, 255, 0);">Troubleshoot and full load test G8920.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><u style="background-color: rgb(255, 255, 0);">Action</u></p><p><span style="background-color: rgb(255, 255, 0);">Swap the relays from G8930 to G8930.</span></p><p><span style="background-color: rgb(255, 255, 0);">Start the test run with full load.</span></p><p><span style="background-color: rgb(255, 255, 0);">Trip after 1 hour and 30 min running.</span></p><p><span style="background-color: rgb(255, 255, 0);">Change Lube oil pressure sensors from G8930 to G8920.</span></p><p><span style="background-color: rgb(255, 255, 0);">Can''t start the engine with low RPM alarm G8920.</span></p><p><span style="background-color: rgb(255, 255, 0);">However, G8930 can start normally with G8920 sensors and relays. (In Progress)</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">History (13.01.2025)</span></p><p><u style="background-color: rgb(255, 255, 0);">Activity</u></p><p><span style="background-color: rgb(255, 255, 0);">TS G8920 trip with under speed alarm during full load test 1:30 hr.</span></p><p><u style="background-color: rgb(255, 255, 0);"><br></u></p><p><u style="background-color: rgb(255, 255, 0);">Action&nbsp;</u></p><p><span style="background-color: rgb(255, 255, 0);">Test run with full load for 2 hr.</span></p><p><span style="background-color: rgb(255, 255, 0);">Trip at 1.30 hr.</span></p><p><span style="background-color: rgb(255, 255, 0);">Check all sensor and relay condition.</span></p><p><span style="background-color: rgb(255, 255, 0);">Found that 1CR relay is defective.</span></p><p><span style="background-color: rgb(255, 255, 0);">Replace with spare relay.</span></p><p><span style="background-color: rgb(255, 255, 0);">Test run with shared load for 2 hr.</span></p><p><span style="background-color: rgb(255, 255, 0);">No abnormality are found. (completed)</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">History (12.1.2025)</span></p><p><u style="background-color: rgb(255, 255, 0);">Activity</u></p><p><span style="background-color: rgb(255, 255, 0);">TS G8920 trip alarm under alarm.</span></p><p><span style="background-color: rgb(255, 255, 0);"><u>Found&nbsp;</u><br>Lube oil pressure sensor (S2) malfunction<br><u>Action</u></span></p><p><span style="background-color: rgb(255, 255, 0);">Remove and check ohm skill of all sensor. (S2 = 25.4 Ohm, S5 =9.5 Ohm)</span></p><p><span style="background-color: rgb(255, 255, 0);">Replace one old oil pressure sensor.</span></p><p><span style="background-color: rgb(255, 255, 0);">test run with shared load for 1 hour.</span></p><p><span style="background-color: rgb(255, 255, 0);">G8920 is back in service.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">History (11.1.2025)</span></p><p><u style="background-color: rgb(255, 255, 0);">Activity</u></p><p><span style="background-color: rgb(255, 255, 0);">TS G8920 trip alarm SD low oil pressure alarm</span></p><p><span style="background-color: rgb(255, 255, 0);"><u>Found&nbsp;</u><br>Lube oil pressure sensor malfunction<br><u>Action</u></span></p><p><span style="background-color: rgb(255, 255, 0);">Remove and check ohm skill of all sensor. (S2 = 11.5 Ohm, S5 =63.1 Ohm)</span></p><p><span style="background-color: rgb(255, 255, 0);">Replace one new oil pressure sensor.</span></p><p><span style="background-color: rgb(255, 255, 0);">test run with shared load for 1 hour.</span></p><p><span style="background-color: rgb(255, 255, 0);">G8920 is back in service.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">History (7.1.25)</span></p><p><u style="background-color: rgb(255, 255, 0);">Today Activity</u></p><p><span style="background-color: rgb(255, 255, 0);">Troubleshoot G8920 due to shutdown with radiator fan fault.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><u style="background-color: rgb(255, 255, 0);">Action</u></p><p><span style="background-color: rgb(255, 255, 0);">Isolated G8920 for troubleshooting.</span></p><p><span style="background-color: rgb(255, 255, 0);">Checked and verified the G8920 panel condition.</span></p><p><span style="background-color: rgb(255, 255, 0);">Found that ventilation fan1 overload trip.</span></p><p><span style="background-color: rgb(255, 255, 0);">Opened the hatch of Ventilation fans.</span></p><p><span style="background-color: rgb(255, 255, 0);">Checked the fans condition&nbsp;</span></p><p><span style="background-color: rgb(255, 255, 0);">Ohm, Mega testing of all winding and wires are good and still in normal rating.</span></p><p><span style="background-color: rgb(255, 255, 0);">Opened the Junction box.</span></p><p><span style="background-color: rgb(255, 255, 0);">Found that fan 1 wire connections were burned.&nbsp;</span></p><p><span style="background-color: rgb(255, 255, 0);">Rectified the connection with new terminal blocks.</span></p><p><span style="background-color: rgb(255, 255, 0);">After that test run G8920.</span></p><p><span style="background-color: rgb(255, 255, 0);">Test run G8920 with share and full load.&nbsp;</span></p><p><span style="background-color: rgb(255, 255, 0);">G8920 are back in service. (complete)</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">History (1.1.2025)</span></p><p><span style="background-color: rgb(255, 255, 0);"><u>Today Activity&nbsp;</u><br>Verify rad fan fault alarm at G8920.</span></p><p><u style="background-color: rgb(255, 255, 0);">Issued</u></p><p><span style="background-color: rgb(255, 255, 0);">- G-8920 was not ready to start due to Rad Fan Fault alarm.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><u style="background-color: rgb(255, 255, 0);">Action</u></p><p><span style="background-color: rgb(255, 255, 0);">- Checked relays in GCP-8920.</span></p><p><span style="background-color: rgb(255, 255, 0);">- Checked magnetic connector MS1 and MS2.</span></p><p><span style="background-color: rgb(255, 255, 0);">- Checked radiator fan cable termination condition.</span></p><p><span style="background-color: rgb(255, 255, 0);">- Found Radiator breaker contact was closed. (Abnormal)</span></p><p><span style="background-color: rgb(255, 255, 0);">- Found cable loosen in breaker.</span></p><p><span style="background-color: rgb(255, 255, 0);">- Then, retighten cables.</span></p><p><span style="background-color: rgb(255, 255, 0);">- Alarm can be cleared.</span></p><p><span style="background-color: rgb(255, 255, 0);">-Back to normal</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">History (28.12.24)</span></p><p><span style="background-color: rgb(255, 255, 0);"><u>Activity (Day 3)</u></span></p><p><span style="background-color: rgb(255, 255, 0);">Continue troubleshoot gas generator G-8920 " Unable to handle full load".</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><u style="background-color: rgb(255, 255, 0);">Action</u></p><p><span style="background-color: rgb(255, 255, 0);">- Checked relay contact resistance.</span></p><p><span style="background-color: rgb(255, 255, 0);">- Found 1GR relay was high value.&nbsp;</span></p><p><span style="background-color: rgb(255, 255, 0);">- Replace new one.</span></p><p><span style="background-color: rgb(255, 255, 0);">- Other relays are normal condition.<br>-Plan to function after FSD completed.<br><br></span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><u style="background-color: rgb(255, 255, 0);">History (Day 2) (27-Dec-2024)</u></p><p><span style="background-color: rgb(255, 255, 0);">Continue troubleshoot gas generator G-8920 "unable to handle full load"</span></p><p><u style="background-color: rgb(255, 255, 0);">Action</u></p><p><span style="background-color: rgb(255, 255, 0);">Measured the insulation resistance value and resistance value of the alternator.<br>No abnormal.<br>Plan to test run after FSD.<br><br><br></span></p><p><u style="background-color: rgb(255, 255, 0);">History (24-Dec-2024)</u></p><p><span style="background-color: rgb(255, 255, 0);">Troubleshoot gas generator G-8920 "unable to handle full load"</span></p><div><u style="background-color: rgb(255, 255, 0);">Action</u></div><p><span style="background-color: rgb(255, 255, 0);">Troubleshoot gas generator G-8920 "unable to handle full load"&nbsp;&nbsp;</span></p><p><span style="background-color: rgb(255, 255, 0);">Replaced new AVR and swapped the oil pressure switch from G-8925.&nbsp;<br class="SCXW30501690 BCX0">Tested with full load, but G-8920 tripped after approximately 30 minutes.&nbsp;<br class="SCXW30501690 BCX0">Plan to troubleshoot.</span></p>', NULL, '2025-01-18 18:06:43', '2025-03-06 14:55:55', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.Se-EI', false, 'ATL') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-G-8920-PACK', 'ATL-G-8920-PACK', 'Gen, ZOC Gas Generator package1', NULL, NULL, 'Gen, ZOC Gas Generator package1', 'ATL', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Noble', NULL, 'EXTERNAL', '2025-01-18 18:06:43', '2025-03-06 14:55:55', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.Se-EI');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Bone', NULL, 'EXTERNAL', '2025-01-18 18:06:43', '2025-03-06 14:55:55', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.Se-EI');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Stephan', NULL, 'EXTERNAL', '2025-01-18 18:06:43', '2025-03-06 14:55:55', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.Se-EI');
