  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'QP: T/S Freezer room unit stop ', 'Electrical', 'CM', 'Under Monitoring', '2025-01-18', '<p>QP: T/S Freezer room unit stop.</p><p>- Found refrigerant leak at service valve for discharge of compressor, performed fully open service valve and installed cap, Checked leak and not found refrigerant leak.</p><p>- Found solenoid valve on evaporator damage, replaced by new spare and function tested is working.</p><p>- Re-filled refrigerant R404A.</p><p>- Resume unit back to normal and running tested, unit stop at room temperature -21 degree Celsius and unit running at room temperature 16 degree Celsius. (Compressor running current 11.3 A and pressure Low = 20 Psi / Hi = 290 Psi)</p><p><br></p>', NULL, '2025-01-18 18:34:43', '2025-01-19 17:36:17', 'PTTEP\\Bongkot.Elec-Lead', 'PTTEP\\Bongkot.Elec-Lead', false, 'G2N') RETURNING id INTO new_report_id;
