-- Inserting report ID 23906
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'FGC#2 Strt-up Trouble shooting, T455 Overtemp', 'Turbine E&I', 'OTH', 'Completed', '2025-01-17', '<div>T/S the FGC#2 could not start by alarm T455 Software Overtemp Coolstop</div><div>- As found the parameter Gas Start Step Fuel Flow&nbsp; &nbsp;2000 kW and Gas Start Fuel Flow Rate from Ignition to Idle&nbsp; &nbsp;120 kW/S , Attempts were made to adjust the parameters and restart the engine as per the steps below, but they were not successful.</div><div>1.Gas Start Step Fuel Flow 1800 kW , Gas Start Fuel Flow Rate from Ignition to Idle 120 kW/S</div><div>2.Gas Start Step Fuel Flow 1700 kW , Gas Start Fuel Flow Rate from Ignition to Idle 100 kW/S</div><div>3.Gas Start Step Fuel Flow 2100 kW , Gas Start Fuel Flow Rate from Ignition to Idle&nbsp; 120 kW/S</div><div>4.Gas Start Step Fuel Flow 1700 kW , Gas Start Fuel Flow Rate from Ignition to Idle&nbsp; 80 kW/S</div><div>5.Gas Start Step Fuel Flow&nbsp; 2000 kW , Gas Start Fuel Flow Rate from Ignition to Idle&nbsp; 120 kW/S</div><div>6.Gas Start Step Fuel Flow&nbsp; 2000 kW , Gas Start Fuel Flow Rate from Ignition to Idle&nbsp; 80 kW/S</div><div>7.Gas Start Step Fuel Flow&nbsp; 2000 kW , Gas Start Fuel Flow Rate from Ignition to Idle&nbsp; 80 kW/S and select knife switch to change running from normal CO2 22.43% mole to high CO2 mode 29.82%mole and dry crank</div><div>8.Gas Start Step Fuel Flow&nbsp; &nbsp;2000 kW , Gas Start Fuel Flow Rate from Ignition to Idle&nbsp; 120 kW/S and exercise solenoid 20GGBV ( GG Blees Valve Solenoid )</div><div>9.Gas Start Step Fuel Flow 2200 kW , Gas Start Fuel Flow Rate from Ignition to Idle 140 kW/S</div><div>10.Gas Start Step Fuel Flow&nbsp; &nbsp;2000 kW , Gas Start Fuel Flow Rate from Ignition to Idle&nbsp; &nbsp;120 kW/S and change the gas composition refer billing report of AIT-1683 on today , CO2&nbsp; &nbsp;21.8% Mole</div><div><br></div><div>- Performed crank soak wash and flushed fuel gas. Used the following parameters: Gas Start Step Fuel Flow&nbsp; &nbsp;2000 kW and Gas Start Fuel Flow Rate from Ignition to Idle&nbsp; 120 kW/s. As a result, the</div><div> engine started successfully</div><div><br></div><div></div><div><br></div><div></div>', NULL, '2025-01-18 20:49:09', '2025-01-26 08:44:12', 'PTTEP\\Arthit.EI-Turbine', 'PTTEP\\Arthit.EI-Turbine', false, 'ART') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-GT-2220-UCP', 'ART-GT-2220-UCP', 'TURBINE UNIT CONTROL PANEL (CH2010)', NULL, NULL, 'TURBINE UNIT CONTROL PANEL (CH2010)', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
