  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Jatuporn', NULL, 'EXTERNAL', '2025-01-18 20:49:09', '2025-01-26 08:44:12', 'PTTEP\\Arthit.EI-Turbine', 'PTTEP\\Arthit.EI-Turbine');
