  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Punyawut', NULL, 'EXTERNAL', '2025-01-18 21:00:07', '2025-05-20 10:15:04', 'PTTEP\\Arthit.EI-Turbine', 'PTTEP\\Arthit.EI-Turbine');
