  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TEK-3300, Performed crank soak wash on 18 Jan 2024', 'Mechanic', 'PM', 'Complete', '2025-01-18', '<ul type="disc"><li>TEK-3300, Performed engine crank soak wash and firing the unit.&nbsp;</li><li>- Prepared equipment and tools to perform crank soak wash by follow up&nbsp;<i>PROCEDURE.</i></li><li>- Request laboratory technician to took sample before and after crank soak wash.</li><li>- Performed solution wash 2 times.</li><li>- Kept 30 minutes for soaking time.</li><li>- Performed rinse water wash 4 times. (300 Litters).</li><li>- Purged crank for 2 times for crank drying about 10 minutes.</li><li>- Reinstalled all accessories and parts back to their normal conditions.</li><li>- General cleaned and cleaning inside the enclosure / air inlet filter room.&nbsp;</li><li>- Started the engine for firing about 10 minutes.</li><li>- Unit stop and keep stand by.,R/H. 253,276.7 hrs.</li></ul><p>&nbsp;</p><p>&nbsp;The results of Chloride content on Stainless Steel Surface of&nbsp;Turbo Compressor train#2 (TEK-3300) on 18-Jan-2024</p><p></p><table border="0" cellspacing="0" cellpadding="0" width="337"><tbody><tr><td width="270" nowrap=""><p align="center">Sample Point</p></td><td width="67" nowrap=""><p align="center">Cl-(µg/cm2)</p></td></tr><tr><td width="270" nowrap=""><p align="center">Air Inlet&nbsp;before cleaning</p></td><td width="67" nowrap=""><p align="center">15.14</p></td></tr><tr><td width="337" nowrap="" colspan="2"><p align="center">&nbsp;</p></td></tr><tr><td width="270" nowrap=""><p align="center">Area below rotor&nbsp;before cleaning</p></td><td width="67" nowrap=""><p align="center">8.26</p></td></tr><tr><td width="270" nowrap=""><p align="center">Area below rotor&nbsp;after cleaning</p></td><td width="67" nowrap=""><p align="center">5.86</p></td></tr><tr><td width="337" nowrap="" colspan="2"><p align="center">&nbsp;</p></td></tr><tr><td width="270" nowrap=""><p align="center">Area rotor&nbsp;before cleaning</p></td><td width="67" nowrap=""><p align="center">16.98</p></td></tr><tr><td width="270" nowrap=""><p align="center">Area rotor&nbsp;after cleaning</p></td><td width="67" nowrap=""><p align="center">5.47</p></td></tr></tbody></table><p>&nbsp;</p><p></p><p>Remark : (Criteria) Chloride content is not over 20 ug/cm2</p>', NULL, '2025-01-18 21:51:15', '2025-01-18 21:53:32', 'PTTEP\\Bongkot.Valve', 'PTTEP\\Bongkot.Valve', false, 'G2N') RETURNING id INTO new_report_id;
