  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Overhauled HP pump shaft assembly ', 'Mechanic', 'CM', 'Complete', '2025-01-19', '<p>Overhauled HP pump shaft assembly.</p><p>Disassembly&nbsp;&nbsp; &nbsp; :</p><p>-&nbsp; &nbsp; Hold the impeller with special tool and removed the head with left hand thread.</p><p>-&nbsp; &nbsp; Lifted up the impeller with flat screwdriver.</p><p>-&nbsp; &nbsp; Removed rotation mechanical seal.</p><p>-&nbsp; &nbsp; Marked the housing position.</p><p>-&nbsp; &nbsp; Unscrewed set screws 2 Ea and removed the mechanical seal housing body.</p><p>-&nbsp; &nbsp; Removed the shaft collar and lip seal bushing.</p><p>-&nbsp; &nbsp; Unscrew bearing housing cover and removed the shaft from housing.</p><p>- Removed stationary mechanical seal from housing.</p><p>-&nbsp; &nbsp; Cleaned the parts and checked the correct seal kit.</p><p><br></p><p>Assembly&nbsp; &nbsp; :</p><p>-&nbsp; &nbsp; Installed the inbound bearing at shaft.</p><p>-&nbsp; &nbsp; Installed stationary mechanical seal.&nbsp; (O-ring 02501)</p><p>-&nbsp; &nbsp; Installed lip seal and bushing at the housing. (O-ring 02502)</p><p>-&nbsp; &nbsp; Installed shaft at the housing.</p><p>- Installed shaft collar.</p><p>-&nbsp; &nbsp; Installed back the housing same as marked position.</p><p>-&nbsp; &nbsp; Installed rotation mechanical seal.</p><p>-&nbsp; &nbsp; Installed impeller and head. (O-ring 01036, 01033)</p><p>-&nbsp; &nbsp; Applied torque 45Nm as per manual document.</p><p>- Packed the shaft assembly and keep for hot spare.</p><p><br></p><p><br></p>', 'G:\\Department Share\\Archive folders\\02-PBN-M\\03 MM\\06. Pictures\\PP Resize\\X 8150 Water Maker\\2025\\2025-Jan-19 Overhauled shaft assembly', '2025-01-19 17:44:10', CURRENT_TIMESTAMP, 'PTTEP\\Mech_WS', NULL, false, 'G2N') RETURNING id INTO new_report_id;
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Narongsak', NULL, 'EXTERNAL', '2025-01-19 17:44:10', CURRENT_TIMESTAMP, 'PTTEP\\Mech_WS', NULL);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Thanapon', NULL, 'EXTERNAL', '2025-01-19 17:44:10', CURRENT_TIMESTAMP, 'PTTEP\\Mech_WS', NULL);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Win', NULL, 'EXTERNAL', '2025-01-19 17:44:10', CURRENT_TIMESTAMP, 'PTTEP\\Mech_WS', NULL);
