  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Assist FGC#1, Single fan running, Main LO ', 'Turbine E&I', 'OTH', 'Completed', '2025-01-20', '<p>Assist Mechanic to rectify BM-1245 (Main lube oil cooler fan) Belt slip.</p><p><br></p><p>According to the Feed Gas Compressor package, the main lube oil system requires both cooler fans to be running as per the logic control.</p><p></p><p>However, BM-1245 needs to be rectified due to a belt slip under a mechanical task. Electrical isolation should support this rectification task. The fan can only be remotely stopped before electrical isolation by forcing off the logic in the PLC.</p><p></p><p>        </p><p>For more information, although the unit requires two cooler fans running, a single fan can maintain the main lube oil temperature. In a case study, after running a single cooler fan, the temperature rose from 50.4°C to 51°C, an increase of only 0.6°C.</p>', NULL, '2025-01-20 16:46:42', '2025-01-26 08:35:33', 'PTTEP\\Arthit.EI-Turbine', 'PTTEP\\Arthit.EI-Turbine', false, 'ART') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-BM-1245', 'ART-BM-1245', 'MOTOR,ELECTRICAL,LUBE OIL COOLER FAN', NULL, NULL, 'MOTOR,ELECTRICAL,LUBE OIL COOLER FAN', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
