-- Inserting report ID 24028
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, '2P-5030C Replace balancing drum', 'Mechanic', 'CM', 'In Progress', '2025-01-18', '<p>2P-5030C Replace balancing drum.</p><p>Running hours: 47,599 hrs.</p><p>- Completed process and electrical isolation.</p><p>1. Drain NDE barrier fluid and connect piping.</p><p>2. Drain NDE lube oil.</p><p>3. Remove NDE bearing housing accessory.</p><p>4. Remove coupling spacer and measure DBSF (Around: 250.5mm.)</p><p>5. Set up shaft locking device and dial gauge for check axial end play.</p><p>6. Check axial end play. (As found 0.21mm.) and move to center.</p><p>7. Lock setting plate of NDE Mech seal.</p><p>8. Remove bearing housing.</p><p>9. Remove NDE bearing, measure shaft end to locking nut reading 131.86mm. (for reference)</p><p>10. Remove Mech seal.</p><p>11. Remove stuffing box.</p><p>12. Check Balance drum clearance. (As found total 1.1mm.)&nbsp;</p><p>13. Remove balance drum.</p><p>14. Remove balancing line and flushing.</p><p>15. Remove discharge casing and cup spring.</p><p>16. Remove insert for balance drum from discharge casing.</p><p>17. Clean all part and visual check condition.</p><p>18. Flushing line balance drum pressure line to pressure transmitter 2PIT-50356C (found sand accumulated)&nbsp;</p><p>19. Install new insert for balance drum into discharge casing.</p><p>20. Re-install discharge casing with new O-ring and cup spring.</p><p>21. Install new balance drum onto shaft.</p><p>22. Re-install stuffing box.</p><p>20. Re-install balancing line with new RTJ Gasket.</p>', '<p><br><br></p>', '2025-01-21 15:44:07', '2025-05-26 22:04:50', 'PTTEP\\GBS.Mechanic-WorkS', 'PTTEP\\KittipongSam', false, 'G2S') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-2P-5030C', 'GBS-2P-5030C', 'PRODUCED WATER RE-INJECTION PUMP C', NULL, NULL, 'PRODUCED WATER RE-INJECTION PUMP C', 'GBS-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Apinan I.', NULL, 'EXTERNAL', '2025-01-21 15:44:07', '2025-05-26 22:04:50', 'PTTEP\\GBS.Mechanic-WorkS', 'PTTEP\\KittipongSam');
