  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, '2P-5030C Replace balancing drum', 'Mechanic', 'CM', 'In Progress', '2025-01-19', '<p>2P-5030C Replace balancing drum.</p><p>1. Remove old bearing by press machine and install new bearing on sleeve by heat method at 110 degrees Celsius.&nbsp;&nbsp;</p><p>2. Measurement bore of bearing housing and bearing outer race. for make sure bearing properly seated.</p><p>3. Re-install Mech seal. (Used old one)</p><p>4. Re-install bearing and tighten locking nut. (measure distance from shaft end to locking nut is 132.12mm.)</p><p>5. Re-install bearing housing and set leveling.</p><p>6. Check axial end play. (Total 0.8mm. set center at 0.4mm.)</p><p>7. Fill lube oil with PTT Hydraulic 46.</p><p>8. Re-connect barrier fluid and charge at 11.64 bar. (monitor leak for 1 night)</p>', NULL, '2025-01-21 15:47:01', '2025-01-21 18:03:41', 'PTTEP\\GBS.Mechanic-WorkS', 'PTTEP\\GBS.Mechanic-WorkS', false, 'G2S') RETURNING id INTO new_report_id;
