  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'WP14 T/S platform DC power system negative to grou', 'Electrical', 'CM', 'In Progress', '2025-01-21', '<div>WP14 T/S platform DC power system negative to ground and verify platform unexpected shut down.</div><div>- Measurement voltage total 24.95 V, positive to ground 24.17V negative to ground 1.17V.</div><div>- Insulation on load output form RTU relay found loop command foghorn low insulation due to foghorn switch damaged, after isolate voltage negative to ground increase to 2 V.</div><div>- Disconnected loop RTU relay found negative voltage to ground increases to 7 V. and after re-connected one by one found voltage drop to 2 V.&nbsp;</div><div>- Finding voltage negative to ground form RTU load circuit still on going.&nbsp;</div><div><br></div><div>****Pictures*****</div><div><span style="background-color: rgb(255, 255, 0);">G:\\Selective Access\\02-PBN-M\\02 MEI\\19 Photos\\00 Electrical Photos\\WPs PICTURES\\WP14\\TELEMETRY BATTERY-SOLAR-CHARGER\\WP14 TS platform DC power system negative to ground and verify platform unexpected shut down</span></div>', NULL, '2025-01-21 19:26:32', CURRENT_TIMESTAMP, 'PTTEP\\Bongkot.Elec-Lead', NULL, false, 'G2N') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBN-WP14-CRS-PLCS', 'GBN-WP14-CRS-PLCS', 'PLC CONTROL AND SCADA SYSTEM WP14', NULL, NULL, 'PLC CONTROL AND SCADA SYSTEM WP14', 'GBN-WP14', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
