  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S VFD-5520 fault alarm IGBT over temperature.', 'Electrical', 'CM', 'In Progress', '2025-01-21', '<p>Found the VFD-5520 fault alarm indicating IGBT over temperature, which could not be reset.</p><p><br></p><p>-&nbsp;Measured the air outlet temperature as 24°C, approximately the same as the VFD-5510 at 23.8°C and the VFD-5530 at 23°C.</p><p>- Verified the alarm and found the unit temp 4 to be 59°C, which is abnormally high.</p><p>- Verified all parameters and consulted with an electrical engineer.</p><p>- Temporarily used a fan blower to reduce the IGBT temperature, but it was not effective.</p><p>- Suspected that the temperature transistors, measurement board, and/or IGBT are defective.</p><p>-&nbsp;Checked and prepared spare parts onboard.</p><p>- Further, a new spare part has been ordered for replacement.</p><p><br></p>', NULL, '2025-01-21 19:26:51', '2025-01-21 19:42:21', 'PTTEP\\GBS.EI-Workshop', 'PTTEP\\GBS.EI-Workshop', false, 'G2S') RETURNING id INTO new_report_id;
