-- Inserting report ID 24095
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, '2P-5030C Replace balance drum', 'Mechanic', 'CM', 'Completed', '2025-01-22', '<p>2P-5030C Replace balance drum.</p><p>Running hour: 47,616 hrs.</p><p>Background. On 21 Jan 2025 CMMS perform measure vibration. (<font color="#ff0000">NDE Bearing is new bearing</font>, it was changed on 19 Jan 2025)</p><p>- Found NDE Bearing a<font color="#ffff00">t<span style="background-color: rgb(206, 0, 0);"> 4A Env3 4.61 gE, (alarm)</span></font></p><p>- Pump has run over night for 18 hrs.</p><p><br></p><p>Remedy:&nbsp;</p><p>1. Drain lube oil and remove cover plate.</p><p>2. Measure distance shaft end - lock nut at 132.12mm. <span style="background-color: rgb(0, 255, 255);">(As found)</span></p><p>3. Loosen lock nut then tighten by hand.</p><p>4. Measure distance shaft end - lock nut at 131.92mm. <span style="background-color: rgb(0, 255, 0);">(Final)</span></p><p></p><p>5. Fold locking plate on lock nut.</p><p>6. Reinstall cover plate and fill lube oil with PTT Hydraulic 46.</p><p>7. Test run and measurement vibration.</p><p>&nbsp; &nbsp; &nbsp;- Found NDE Bearing at 4A Env3 2.63 gE, <font style="background-color: rgb(0, 255, 0);">(Normal)</font></p><p>&nbsp; &nbsp; &nbsp;- NDE bearing temp at 55.1 degrees Celsius.</p><p>&nbsp; &nbsp; &nbsp;- Balancing line pressure: 8.0 bar.</p><p>&nbsp; &nbsp; &nbsp;- Suction pressure: 5.0 bar.</p><p>&nbsp; &nbsp; &nbsp;- Discharge pressure: 100 bar.</p><p>8. Normal operation.</p>', NULL, '2025-01-22 18:57:39', '2025-02-02 14:52:46', 'PTTEP\\KittipongSam', 'PTTEP\\KittipongSam', false, 'G2S') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-2P-5030C', 'GBS-2P-5030C', 'PRODUCED WATER RE-INJECTION PUMP C', NULL, NULL, 'PRODUCED WATER RE-INJECTION PUMP C', 'GBS-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Kittipong S.', NULL, 'EXTERNAL', '2025-01-22 18:57:39', '2025-02-02 14:52:46', 'PTTEP\\KittipongSam', 'PTTEP\\KittipongSam');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Apinan I.', NULL, 'EXTERNAL', '2025-01-22 18:57:39', '2025-02-02 14:52:46', 'PTTEP\\KittipongSam', 'PTTEP\\KittipongSam');
