  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Replaced TG-1 Bckup-Batt regarding Unit alrm', 'Turbine E&I', 'CM', 'Completed', '2025-01-23', '<p>Problem:&nbsp; Unit alarm: “AL_Contoller_Battery_Low”&nbsp;</p><p>Verification :&nbsp;</p><div>1. Verified the Unit PLC and found “LED BAT” was showing red on the CPU PLC status.</div><p>      </p><p></p><p></p><div>2. The&nbsp; “BAT LED” it typically means that the battery is either low or needs to be replaced</div><div><br></div><div><p>Action:&nbsp;</p>  <div>1. Performed online replacement the Battery while the TG-1 onload controlled.</div>  <div>2.(The Existing Batt was Manufacturing Dec 2009 and installed on Jan 2010), Well, the new replacement was manufacturing in JAN 2021.</div>  <div><br></div><div><p>Material Used :&nbsp;</p>  <div>1.1 Ea of backup battery: 60.02.42.040.3 : PN.1756-BA2</div><div><br></div><div><p>Recommendation. </p>  <div>1.The backup battery replacement needs to be done while the system is powered up with 24Vdc power.</div>  <div>2.To avoid any unexpected events or potential tripping of the TG unit during the replacement activities:</div>  <div class="O1">1.It is advisable to offload or normally stop the unit before performing the replacement.</div>  <p></p>  <div>3.If it is not possible to change over the running TG unit.</div>  <div class="O1">1.The replacement can still be performed while the unit is under controlled load, as in this case.</div>  <div class="O1"><br></div><div class="O1"></div>  <p></p>  <p></p></div></div></div>', NULL, '2025-01-23 15:14:06', '2025-01-26 08:23:04', 'PTTEP\\Arthit.EI-Turbine', 'PTTEP\\Arthit.EI-Turbine', false, 'ART') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-A-6100', 'ART-A-6100', 'MAIN POWER GENERATOR PACKAGE', NULL, NULL, 'MAIN POWER GENERATOR PACKAGE', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-A-6100-FIG410', 'ART-A-6100-FIG410', 'TURBINE CONTROL PANEL,BGS.49635.0,4.10', NULL, NULL, 'TURBINE CONTROL PANEL,BGS.49635.0,4.10', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
