-- Inserting report ID 24123
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS FRC meter of the water treatment system', 'Electrical & Instrument', 'CM', 'Completed', '2025-01-23', '<p><b><u>Today Activity</u></b></p><p>Troubleshoot FRC meter of water treatment system.</p><p><br></p><p><b><u>Finding</u></b></p><p>Issue 1: The measurement point cannot reach the set point.<b><u></u></b></p><p><b><u><br></u></b></p><p><b><u>Action taken</u></b></p><p>For Issue 1: Cleaned the sensor of the FRC meter due to open circuit</p><p>The sensor ohm value appear after cleaning.</p><p><br></p><p><u>Relay 1 Set Points</u></p><p>Close set point: 0.20</p><p>Open set point: 0.40&nbsp;</p><p><br></p><p><u>Temperature setting&nbsp;</u></p><p>Change to "manual mode"</p><p><br></p><p>The FRC meter is now functioning properly and is under monitoring.</p><p><b><u><br></u></b></p><p><b><u style="background-color: rgb(255, 255, 0);">History (11.11.2024)</u></b></p><p><b><u style="background-color: rgb(255, 255, 0);">Today''s Activity</u></b></p><p><span style="background-color: rgb(255, 255, 0);">Troubleshoot the FRC meter of the water treatment system.</span></p><p><b><u style="background-color: rgb(255, 255, 0);">Findings</u></b></p><p><span style="background-color: rgb(255, 255, 0);">Issue 1: The display is not visible.</span></p><p><span style="background-color: rgb(255, 255, 0);">Issue 2: The measurement point cannot reach the set point.</span></p><p><b><u style="background-color: rgb(255, 255, 0);">Actions Taken</u></b></p><p><span style="background-color: rgb(255, 255, 0);">For Issue 1: Performed a hard reset on the FRC meter. The display returned to normal.</span></p><p><span style="background-color: rgb(255, 255, 0);">For Issue 2: Cleaned the sensor of the FRC meter.</span></p><p><u style="background-color: rgb(255, 255, 0);">Output power relay changes</u></p><p><span style="background-color: rgb(255, 255, 0);">The output power switched from Relay 1 to Relay 2. The relay was tested for functionality.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">Relay 2 Set Points</span></p><p><span style="background-color: rgb(255, 255, 0);">Close set point: 0.8 ppm</span></p><p><span style="background-color: rgb(255, 255, 0);">Open set point: 1.0 ppm</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">The FRC meter is now functioning properly and is under monitoring.</span></p>', NULL, '2025-01-23 18:16:33', '2025-01-23 18:17:24', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.Inst-Tec', false, 'ATL') RETURNING id INTO new_report_id;
