  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'WP-33 : Investigate platform unexpected shutdown', 'Electrical', 'CM', 'Under Monitoring', '2025-01-25', '<p>WP-33 : Investigate platform unexpected shutdown</p><p>- The platform voltage was measured at a total of 26.97V, with 18.56V from positive to ground and 8.43V from negative to ground. The platform load current was 12.6A.<br> - The loop command ESD signal was re-tightened.<br> - The operator discovered that 4 circuit breakers had tripped: F71 and F73 (tripped by command from the PCB77 battery high/low voltage protection card) and F23 and F24 (tripped by command from ESD1).<br> - The root cause of the trip in circuit breakers F71 and F73 was suspected to be a malfunction of the PCB77.&nbsp;<br> - The PCB77 was replaced with a new spare, and the voltage sensing wiring was cleaned and re-tightened.</p>', '<a href="https://pttep.sharepoint.com/sites/THG2N/DL_Selective_Access/Forms/AllItems.aspx?id=%2Fsites%2FTHG2N%2FDL%5FSelective%5FAccess%2F02%2DPBN%2DM%2F02%20MEI%2F19%20Photos%2F00%20Electrical%20Photos%2FWPs%20PICTURES%2FWP33%2FDCDB%2DHYBRID%2DSOLAR%2DBATTERY%2F2025%2D01%2D25%20Investigate%20platform%20unexpected%20shutdown&amp;viewid=dce8e204%2D2273%2D4c5e%2Da20c%2Dcbf12e9b5007">BONGKOT NORTH (G2N) - 2025-01-25 Investigate platform unexpected shutdown - All Documents (sharepoint.com)</a>', '2025-01-25 18:39:28', CURRENT_TIMESTAMP, 'PTTEP\\Bongkot.Elec-Lead', NULL, false, 'G2N') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBN-WP33-ELE', 'GBN-WP33-ELE', 'Electrical System', NULL, NULL, 'Electrical System', 'GBN-WP33', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Peera', NULL, 'EXTERNAL', '2025-01-25 18:39:28', CURRENT_TIMESTAMP, 'PTTEP\\Bongkot.Elec-Lead', NULL);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Phoothorn', NULL, 'EXTERNAL', '2025-01-25 18:39:28', CURRENT_TIMESTAMP, 'PTTEP\\Bongkot.Elec-Lead', NULL);
