-- Inserting report ID 24222
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Engine cylinder head replacement.', 'Mechanic', 'CM', 'Completed', '2025-01-25', '<p><b style="background-color: rgb(255, 255, 0);"><u>Engine cylinder head replacement 20-25 Jan 2025</u></b></p><p><br></p><p><span style="background-color: rgb(255, 255, 0);"><b>20-Jan-2025&nbsp;</b></span></p><p>- Assisted construction team to erect scaffold around power pack.&nbsp;</p><p>- Removed exhaust pipe, AC generator, PLC generator junction box and top cover on power pack.</p><p>- Remove flame arrestor, turbocharger, exhaust manifold and sent to mechanic workshop to reparation.</p><p><span style="background-color: rgb(255, 255, 0);"><b>21-Jan-2025</b></span></p><p>- Drained coolant water from the radiator and engine block.</p><p>- Remove the cylinder head follow to procedure.</p><p>- Cleaned the cylinder block deck surface and cleaned around the engine.</p><p>- Inspected cylinder head long cap screws and inspected cylinder head short cap screws.</p><p><span style="background-color: rgb(255, 255, 0);"><b>22-Jan-2025</b></span></p><p>- Checked the new cylinder head combustion surface for flatness End-to-End and Side to Side,&nbsp;Checked the valve depth dimension.</p><p>- Installed new cylinder head and follow procedure.</p><p>- Adjusted the valve clearance, intake vale, exhaust valve and tighten torque.</p><p><b style="background-color: rgb(255, 255, 0);">23-Jan-2025.</b></p><p>- Installed the air aftercooler.</p><p>- Installed the injector supply line, injector drain line tube and tube of all fuel system line.</p><p>- Changed engine lube oil PTT15W-40.</p><p>- Replaced the lube oil filter,&nbsp;fuel filter.</p><p><span style="background-color: rgb(255, 255, 0);"><b>24-Jan-2025</b></span></p><p>- Installed the exhaust manifold and gasket</p><p>- Installed the turbocharger and turbocharger outlet elbow, Flame arrestor.</p><p>- Top up water coolant 22 liters with supplemental coolant additive 1 liter.</p><p>- Tested run engine for check condition.</p><p><b style="background-color: rgb(255, 255, 0);">25-Jan-2025</b></p><p>- Rechecked and adjusted valve clearance and tested run engine 20-mintue for check abnormal noise.</p><p>- Installed powerpack cover, AC generator, exhaust pipe and PLC generator junction box.&nbsp;</p><p>- Tested run engine one hour for check condition.</p><p>- Operated test crane function auxiliary hoist, main hoist, boom cylinder and swing found normal condition.</p><p><br></p><p style="box-sizing: border-box; margin: 0px; font-size: 14px; line-height: 1.6; color: black; vertical-align: bottom; padding: 0px;"><span style="box-sizing: border-box; background-color: rgb(255, 255, 0);"><u style="box-sizing: border-box;">* Please find crane daily report of ART-Crane-AWP13-CM on&nbsp; detail attached file.*</u></span></p><p><br></p><p style="box-sizing: border-box; margin: 0px; font-size: 14px; line-height: 1.6; color: black; vertical-align: bottom; padding: 0px;"><br style="box-sizing: border-box; color: rgb(0, 0, 0); font-family: Montserrat, Lato, &quot;Open Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Calibri, Arial, sans-serif; font-size: 14px; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: 400; letter-spacing: normal; orphans: 2; text-align: start; text-indent: 0px; text-transform: none; widows: 2; word-spacing: 0px; -webkit-text-stroke-width: 0px; white-space: normal; background-color: rgb(255, 255, 255); text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial;"></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p>&nbsp;</p><p>&nbsp;</p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p>&nbsp;&nbsp;&nbsp;</p><p>&nbsp;</p><p><br></p>', '<p><u>Crane daily report of ART-Crane-AWP13-CM on&nbsp; detail attached file</u></p><p><u><br></u></p><p>20-Jan-2025&nbsp; &nbsp;<a href="https://pttep.sharepoint.com/:b:/s/THART/EZwXQMTBfIhJr115_TALbOUBhGsC2wlcZ5WhctEq2xwWyg?e=lKupii">https://pttep.sharepoint.com/:b:/s/THART/EZwXQMTBfIhJr115_TALbOUBhGsC2wlcZ5WhctEq2xwWyg?e=lKupii</a></p><p>21-Jan-2025</p><p><a href="https://pttep.sharepoint.com/:b:/s/THART/ES8Y-bCZlkVDu0fM1BPIa6EB0c3UwJNBZKjf6-JuHoWdNw?e=xjmAAd">https://pttep.sharepoint.com/:b:/s/THART/ES8Y-bCZlkVDu0fM1BPIa6EB0c3UwJNBZKjf6-JuHoWdNw?e=xjmAAd</a><a href="https://pttep.sharepoint.com/:b:/s/THART/ES8Y-bCZlkVDu0fM1BPIa6EB0c3UwJNBZKjf6-JuHoWdNw?e=xjmAAd" target="_blank"></a></p><p>22-Jan-2025</p><p><a href="https://pttep.sharepoint.com/:b:/s/THART/EU_7mqmI06RDtBzVFCz8HjIB5f27FOKIsmnDCvG4RH8TAg?e=CMucvG" target="_blank">https://pttep.sharepoint.com/:b:/s/THART/EU_7mqmI06RDtBzVFCz8HjIB5f27FOKIsmnDCvG4RH8TAg?e=CMucvG</a><br></p><p>23-Jan-2025</p><p><a href="https://pttep.sharepoint.com/:b:/s/THART/EXZgBi3xOGxAq6ehwfz0pQIB_gVRapiQ0DTskASdIAckAQ?e=g3XoGz">https://pttep.sharepoint.com/:b:/s/THART/EXZgBi3xOGxAq6ehwfz0pQIB_gVRapiQ0DTskASdIAckAQ?e=g3XoGz</a><a href="https://pttep.sharepoint.com/:b:/s/THART/EXZgBi3xOGxAq6ehwfz0pQIB_gVRapiQ0DTskASdIAckAQ?e=g3XoGz" target="_blank"></a></p><p>24-Jan-2025</p><p><a href="https://pttep.sharepoint.com/:b:/s/THART/EbVVws_pPpBJj0Mg8qOMTngBcNwYdgik7rr5FCXKTZzFJA?e=FunAsy">https://pttep.sharepoint.com/:b:/s/THART/EbVVws_pPpBJj0Mg8qOMTngBcNwYdgik7rr5FCXKTZzFJA?e=FunAsy</a><a href="https://pttep.sharepoint.com/:b:/s/THART/EbVVws_pPpBJj0Mg8qOMTngBcNwYdgik7rr5FCXKTZzFJA?e=FunAsy" target="_blank"></a></p><p>25-Jan-2025</p><p><a href="https://pttep.sharepoint.com/:b:/s/THART/EYkdkzwV8qtMupME_9xHs64BpWpsJ3IRIGwINbJv397iUA?e=Ih9Da7" target="_blank">https://pttep.sharepoint.com/:b:/s/THART/EYkdkzwV8qtMupME_9xHs64BpWpsJ3IRIGwINbJv397iUA?e=Ih9Da7</a><br><br><br><br></p>', '2025-01-26 14:26:52', CURRENT_TIMESTAMP, 'PTTEP\\a