  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'G-8925 Replace defective coolant hoses', 'Mechanic', 'PM', 'In Progress', '2025-01-26', '<div><u>Today Activity</u></div><div><div><u><br></u></div><div>Replace the defective coolant hoses, G-8925.&nbsp;</div><div><br></div><div><u>Action</u></div><div><br></div><div><div>- Prepare and Setup equipment to drain coolant.</div><div>- Drained the coolant from both Raw Water &amp; Jacket Water Tank.</div><div>- Removed the pipe clips &amp; defective hose at the downstream of jacket water pump A.</div><div>- Removed the inlet line &amp; gasket of the oil exchangers.</div><div>- Checked and cleaned the mating surfaces for the removed parts.</div><div>- Replaced the new gasket and hose.</div><div>- Installed the inlet line and tightened (17mm ~ 40Nm)</div><div>- Tightened the pipe clips.</div><div><br></div><div>- Removed the pipe clips, the flange clamps &amp; defective hose at the downstream of Raw Water Pump.</div><div>- Removed the outlet line of raw water pump.</div><div>- Checked and cleaned the mating surfaces for the removed parts.</div><div>- Replaced the new gasket and hose.</div><div>- Installed the outlet line of raw water pump.</div><div>- Tightened the pipe clips.</div><div>- Topped Up Coolant.</div><div><br></div><div><br></div></div><div><u><br></u></div><div><u>Required Tools</u></div><div><u><br></u></div><div>- Spanner Set</div><div>- Socket Set.</div><div>- Torque Wrench (10~50Nm)</div><div>- 1/2" to 3/4" Adapter</div><div>- Screwdrivers</div><div>- Coolant Pump</div><div>- Air Compressor</div><div>- E-Extension</div><div>- Flash light</div><div>- Copper Brush</div></div>', 'Swapped the radiator cap from Gas Generator G-8920 to G-8925 for jacket water tank.', '2025-01-26 19:01:20', '2025-01-26 19:08:56', 'PTTEP\\ZOC.Mech-Tec', 'PTTEP\\ZOC.Mech-Tec', false, 'ATL') RETURNING id INTO new_report_id;
