  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-2VFD-5520', 'GBS-2VFD-5520', 'TG AC STARTING MOTOR VFD', NULL, NULL, 'TG AC STARTING MOTOR VFD', 'GBS-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
