  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Support Exterran BC to troubleshooting BC AWP20', 'Automation', 'CM', 'In Progress', '2025-01-24', '<p>Support Exterran BC team to troubleshooting BC AWP20 cannot start.</p>  <p>-&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Requested on site performed insulation test transmitter in loop of AI card slot 7. Found all transmitters were normally.</p>  <p>-&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Replaced the new one of AI card. Then turn on power found power back to normal.</p>  <p>-&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Controller status running normally. But found HMI cannot communication with controller.</p>  <p>-&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Kept unit stop. To be configuration communicate of HMI on tomorrow.</p>  <p>**Next plan**</p>  <p>-&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; To change controller from L541 to L543. (The old one is reconditioned controller)</p>  <p>-&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Re-configuration communication of controller and HMI.&nbsp;</p>', NULL, '2025-01-31 14:41:58', CURRENT_TIMESTAMP, 'PTTEP\\Art.Automation', NULL, false, 'ART') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-C-2061', 'ART-C-2061', 'BOOSTER COMPRESSOR PACKAGE', NULL, NULL, 'BOOSTER COMPRESSOR PACKAGE', 'ART-WP20', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
