  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'PM ME Closed Drain Booster Pump 6M', 'Mechanic', 'PM', 'Completed', '2025-01-10', '<p>10-Jan-25</p><p>"Perform maintenance and inspection as follow activities:</p><p>&nbsp;1. Check that pump is operating in the safe condition.</p><p>&nbsp;2. Visual check coupling and check coupling guards.</p><p>&nbsp;3. Check alignment.</p><p>&nbsp;4. Check the discharge and suction pressure gauge.</p><p>&nbsp;5. Inspect foundation defective e.g. corrosion, looseness, crack, break.</p><p>&nbsp;6. Check foundation bolts for security of attachment and corrosion.</p><p>&nbsp;7. Check seal pot fluid and leakage.</p><p>&nbsp;8. Clean inlet strainer. (Clogged 100% by sludge)&nbsp;</p><p>&nbsp;9. Inspection inlet strainer and housing for deterioration, corrosion and replace if necessary.</p><p>&nbsp;10. Greasing into bearing.</p><p>&nbsp;11. Test run and data recording:</p><p>&nbsp; &nbsp; - Running hour = 6,069.58 Hrs.</p><p>&nbsp; &nbsp; - PIT-4570 = 7.684 BAR</p><p>&nbsp; &nbsp; - PDG-4570 = 0.19-BARG.&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</p><p>&nbsp;12. Check fluid circulate to mechanical seal.</p><p>&nbsp;13. Check for excessive leakage at seal areas.</p><p>&nbsp;14. Check that pump and motor vibration is normal and there are not the abnormal noises.</p><p>&nbsp;15. Cleaned up area skid unit."</p><div><br></div><div><br></div>', NULL, '2025-01-31 16:44:46', CURRENT_TIMESTAMP, 'PTTEP\\AthiwatK', NULL, false, 'ART') RETURNING id INTO new_report_id;
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'ART-CONCOR', NULL, 'EXTERNAL', '2025-01-31 16:44:46', CURRENT_TIMESTAMP, 'PTTEP\\AthiwatK', NULL);
