BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'WO#500556346 PM ME Open Drain Sump Pump 1Y', 'Mechanic', 'PM', 'Completed', '2025-01-12', '<p>12-Jan-25</p><p>Perform maintenance and inspection as follow;</p><p>&nbsp;1. Check foundation holding down bolts and tightening check.</p><p>&nbsp;2. Check for any leaks from gaskets and seals around the pump skid.</p><p>&nbsp;3. Change lubes oil on bearing gearbox and sight glass indicator.</p><p>&nbsp;4. Clean inlet strainer clogged 30 % by some particle.</p><p>&nbsp;5. Check barrier fluid on mechanical seal for leak.</p><p>&nbsp;6. Flushing and cleaning fluid line and orifice plate clogged found and then cleaned.</p><p>&nbsp;7. Check mechanical seal holding bolts and tightening.</p><p>&nbsp;8. Visual checked mechanical seal for leak.</p><p>&nbsp;9. Check coupling guard condition.</p><p>&nbsp;10. Check coupling membrane condition for crack, broken, deterioration.</p><p>&nbsp;11. Alignment check and record value for reference. (No adjustment made).</p><p>&nbsp;12. Coupling bolts check with proper torque applying.</p><p>&nbsp; &nbsp; &nbsp;- Running hour = 6,402 Hrs.</p><p>&nbsp; &nbsp; &nbsp;- Suction pressure = Gravity.</p><p>&nbsp; &nbsp; &nbsp;- Discharge pressure PIT-4530 = 2.058 BAR.</p><div><br></div>', NULL, '2025-01-31 17:36:16', CURRENT_TIMESTAMP, 'PTTEP\\AthiwatK', NULL, false, 'ART') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-P-4530', 'ART-P-4530', 'OPEN DRAIN SUMP PUMP', NULL, NULL, 'OPEN DRAIN SUMP PUMP', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
