  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-PP-RBLCIRPMP.PK', 'ART-PP-RBLCIRPMP.PK', 'APP REBOILER CIRCULATION PUMP PACKAGE', NULL, NULL, 'APP REBOILER CIRCULATION PUMP PACKAGE', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
