  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-C-1910', 'ART-C-1910', 'VRU COMPRESSOR TRAIN 1', NULL, NULL, 'VRU COMPRESSOR TRAIN 1', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'ART-CONCOR', NULL, 'EXTERNAL', '2025-01-31 19:54:14', CURRENT_TIMESTAMP, 'PTTEP\\AthiwatK', NULL);
