  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'PM ME Reboiler Circ Pump 1Y, WO#500556394', 'Mechanic', 'PM', 'Completed', '2025-01-17', '<p>17-Jan-25</p><p>Perform maintenance and inspection as follow;</p><p>&nbsp;1. Check that pump is operating in the safe condition.&nbsp;</p><p>&nbsp;2. Check foundation holding down bolts and tightening check.&nbsp;</p><p>&nbsp;3. Change lubes oil on bearing gearbox and sight glass indicator.&nbsp;</p><p>&nbsp;4. Check barrier fluid on mechanical seal for leak.&nbsp;</p><p>&nbsp;5. Check mechanical seal holding bolts and tightening.&nbsp;</p><p>&nbsp;6. Visual check mechanical seal for leak.&nbsp;</p><p>&nbsp;7. Check coupling membrane condition for crack, broken, deterioration.&nbsp;</p><p>&nbsp;8. Alignment check and record value for reference.&nbsp;</p><p>&nbsp;9. Coupling bolts check with proper torque applying.&nbsp;</p><p>&nbsp;10. Remove suction strainer for inspection and clean clogged.</p><p>&nbsp;11. Inspection inlet strainer and housing for deterioration.</p><p>&nbsp;12. Cleaned up area skid unit.</p><p>&nbsp;13. Unit waiting for temperature rising up to normal temperature before test run.&nbsp;</p><p>&nbsp; &nbsp; - Running hour = 76,333 Hrs.</p><p><br></p><p>18-Jan-25</p><p>1. Test run with data recording as follow.&nbsp;</p><p>&nbsp; &nbsp;- Running hour = 76,333 Hrs.</p><p>&nbsp; &nbsp;- Current = 88.4 Amps.</p><p>&nbsp; &nbsp;- PG-1780 = 10.4 Barg.</p><p>&nbsp; &nbsp;- PDT-1880 = 0.0 Barg.</p><p>&nbsp; &nbsp;- PIT-1881 = 14.8 Barg.</p><p>&nbsp; &nbsp;- PIT-1882 = 14.81 Barg.</p><p>&nbsp; &nbsp;- FIT-1880 = 310.3 m3/h</p><div><br></div><div><br></div>', NULL, '2025-01-31 20:03:10', CURRENT_TIMESTAMP, 'PTTEP\\AthiwatK', NULL, false, 'ART') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-P-1880', 'ART-P-1880', 'REBOILER CIRCULATION PUMP', NULL, NULL, 'REBOILER CIRCULATION PUMP', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'ART-CONCOR', NULL, 'EXTERNAL', '2025-01-31 20:03:10', CURRENT_TIMESTAMP, 'PTTEP\\AthiwatK', NULL);
