  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'PM EL Survival Craft NO.1 6M, WO#500556289', 'Electrical', 'PM', 'Completed', '2025-01-22', '<p>22-Jan-25</p><p>Perform maintenance and inspection as follow;&nbsp;&nbsp;</p><p>&nbsp;1. Re-Tighten terminal and connection wiring.</p><p>&nbsp;2. Record the individual cell temp on battery.</p><p>&nbsp;3. Record the individual cell voltage on battery.&nbsp;&nbsp;</p><p>&nbsp;4. Record the individual cell impedance on battery.&nbsp;</p><p>&nbsp;5. Re-grease or Vaseline for battery terminals.</p><p>&nbsp;6. Re-tighten all fixings, screws, terminals and wirings.</p><p>&nbsp;7. Check all lightings are functional.</p><p>&nbsp;8. Check power cable supply plug.&nbsp;</p><p>&nbsp;9. Insulation test and record resistance of cable.</p><p>10.Measurement and record data of batteries as follow;</p><p>&nbsp; &nbsp;- Main battery = 12.97 Vdc., 3.30 m-ohm @Temp 44.1 oC.&nbsp;</p><p>&nbsp; &nbsp;- Emergency battery = 12.96 Vdc., 3.55 m-ohm @Temp 43.6 oC.</p><p>&nbsp; &nbsp;- VHF battery = 12.92 Vdc., 4.25 m-ohm @Temp 43.0 oC.</p><div><br></div>', NULL, '2025-02-01 12:51:49', CURRENT_TIMESTAMP, 'PTTEP\\AthiwatK', NULL, false, 'ART') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-X-5940-BAT', 'ART-X-5940-BAT', 'BATTERY FOR SURVIVAL CRAFT NO.1', NULL, NULL, 'BATTERY FOR SURVIVAL CRAFT NO.1', 'ART-QP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
