  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'PM EL Survival Craft Winch NO.3 1Y, WO#500556321', 'Electrical', 'PM', 'Completed', '2025-01-24', '<p>24-Jan-25</p><p>Perform maintenance and inspection as follow;&nbsp;&nbsp;</p><p>&nbsp;1. Check equipment name plate, tag number.&nbsp;</p><p>&nbsp;2. Check cable, label and cable tag number are legible.</p><p>&nbsp;3. Re-Tighten terminal and wiring connection.</p><p>&nbsp;4. Measure and record insulation resistance of winding + cable with earth.</p><p>&nbsp;5. Measure and record resistance of winding + cable with earth.</p><p>&nbsp;6. Measure and record insulation resistance of heater.</p><p>&nbsp;7. Lubricate greased bearing DE and NDE point.</p><p>&nbsp;8. Measure and record resistance of feeder.</p><p>&nbsp;9. Measure and record insulation resistance of feeder.</p><p>&nbsp;10. Visual check and cleaning cooling fan motor.</p><p>&nbsp;11. House-keeping on working area.</p><p>&nbsp;12. Test run and data recording.</p><p>&nbsp; &nbsp; &nbsp; - Running hour : 5.6 hrs.&nbsp;</p><p>&nbsp; &nbsp; &nbsp; - Running current : L1 = 20.68 Amps, L2 = 20.81 Amps, L3 = 20.79 Amps.</p><div><br></div>', NULL, '2025-02-01 15:15:03', CURRENT_TIMESTAMP, 'PTTEP\\AthiwatK', NULL, false, 'ART') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-X-5960', 'ART-X-5960', 'SURVIVAL CRAFT NO.3', NULL, NULL, 'SURVIVAL CRAFT NO.3', 'ART-QP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'ART-CONCOR', NULL, 'EXTERNAL', '2025-02-01 15:15:03', CURRENT_TIMESTAMP, 'PTTEP\\AthiwatK', NULL);
