  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'PM ME Survival Craft Davits NO.3 1Y, WO#500568360', 'Mechanic', 'PM', 'Completed', '2025-01-24', '<p>24-Jan-25</p><p>Perform maintenance and inspection as follow;&nbsp;&nbsp;</p><p>&nbsp;1. General visual check equipment is in the safe condition.</p><p>&nbsp;2. Secure lifeboat with pendant lines both end before start the job.</p><p>&nbsp;3. Visual checks davit winch external condition for leak and damaged.</p><p>&nbsp;4. Visual check all driving gears condition.</p><p>&nbsp;5. Replace gear oil.</p><p>&nbsp;6. Checked oil in back stops clutch housing.</p><p>&nbsp;7. Apply grease all pivots, bearings and other greasing points.</p><p>&nbsp;8. Check all safety devices and limit switch for proper working.</p><p>&nbsp;9. Carry out functional test brake by lower the boat to the half way.</p><p>&nbsp;10. Re-store the boat back in place and clean up the unit.</p><p>&nbsp; &nbsp; &nbsp;- Running hour = 5.6 Hrs.</p><p>&nbsp; &nbsp; &nbsp;- Running current = 20.68 Amps.</p><div><br></div>', NULL, '2025-02-01 15:20:11', CURRENT_TIMESTAMP, 'PTTEP\\AthiwatK', NULL, false, 'ART') RETURNING id INTO new_report_id;
