-- Inserting report ID 25409
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'PM ME FW Transfer Pump 6M, WO#500556287', 'Mechanic', 'PM', 'Completed', '2025-01-25', '<p>25-Jan-25</p><p>Perform 6M PM Mechanic Fresh water Transfer Pump (P-5430)</p><p>&nbsp;1. Check that pump is operating in the safe condition.</p><p>&nbsp;2. Visual check coupling and check coupling guards.</p><p>&nbsp;3. Replaced new coupling.</p><p>&nbsp;4. Check alignment.</p><p>&nbsp;5. Check the discharge and suction pressure gauge.</p><p>&nbsp;6. Inspect foundation defective e.g. corrosion, looseness, crack, break.</p><p>&nbsp;7. Check lubricant leaks.</p><p>&nbsp;8. Check foundation bolts for security of attachment and corrosion.</p><p>&nbsp;9. Clean inlet strainer.</p><p>&nbsp;10. Inspection inlet strainer and housing for deterioration, corrosion.</p><p>&nbsp;11. Flush and clean fluid line.</p><p>&nbsp;12. Replace PTT Turbine (Shell Turbo T46 - 0.86 Liters)</p><p>&nbsp;13. Check fluid circulate to mechanical seal.</p><p>&nbsp;14. Check for excessive leakage at seal areas.</p><p>&nbsp;15. Check that pump and motor vibration.</p><p>&nbsp;16. Cleaned up area skid unit.</p><p>&nbsp;17. Test run and data recording as follow;</p><p>&nbsp; &nbsp; &nbsp;- Running hour = 19,081 Hrs.</p><p>&nbsp; &nbsp; &nbsp;- Running current = 30.0 Amps.</p><p>&nbsp; &nbsp; &nbsp;- PG-5430 = 4.5 BARG.</p><div><br></div>', NULL, '2025-02-01 15:31:10', CURRENT_TIMESTAMP, 'PTTEP\\AthiwatK', NULL, false, 'ART') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-P-5430', 'ART-P-5430', 'FRESH WATER TRANSFER PUMP', NULL, NULL, 'FRESH WATER TRANSFER PUMP', 'ART-QP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'ART-CONCOR', NULL, 'EXTERNAL', '2025-02-01 15:31:10', CURRENT_TIMESTAMP, 'PTTEP\\AthiwatK', NULL);
END $$;

