  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Yohun', NULL, 'EXTERNAL', '2025-02-01 18:12:03', '2025-02-01 18:41:29', 'PTTEP\\Bongkot.Elec-Lead', 'PTTEP\\Bongkot.Elec-Lead');
