  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'WPS-06 Perform ESD Test and PLC System YPM', 'Instrument', 'PM', 'Completed', '2025-02-03', '<div class="ewa-rteLine">Perform ESD Test and PLC System YPM for WPS-06.</div><div class="ewa-rteLine">- Performed PM and function ESD tested follow procedures, The result satisfied.</div><div class="ewa-rteLine">- Performed SDV, BDV and ESDV function tested follow procedures The result satisfied.</div><div class="ewa-rteLine">- Verified PLC and tightening connector of PLC system.</div><div class="ewa-rteLine">- Replaced new PLC battery backup as per schedule.</div><div class="ewa-rteLine"><br></div><div class="ewa-rteLine">Equipment malfunction during perform ESD test as below list,</div><div class="ewa-rteLine"><br></div><div class="ewa-rteLine"><div class="ewa-rteLine">2PCV-16200B Malfunction.</div><div class="ewa-rteLine">- Perform overhauled replaced seal kit and set pressure 5 barg.</div><div class="ewa-rteLine"><br></div><div class="ewa-rteLine"><div class="ewa-rteLine">T/S 2SSV-16002B Close by itself.</div><div class="ewa-rteLine">- Function test working as normal.</div><div class="ewa-rteLine"><br></div><div class="ewa-rteLine"><div class="ewa-rteLine">2XV-16004E malfunction.</div><div class="ewa-rteLine">- Function test working as normal.</div><div class="ewa-rteLine"><br></div><div class="ewa-rteLine"><div class="ewa-rteLine">2SSV-16002F malfunction.</div><div class="ewa-rteLine">- Found well not operation and master valve under process isolation.</div></div></div><div class="ewa-rteLine"><br></div><div class="ewa-rteLine">2SDV-16400 shown status fault alarm and not fully close.</div><div class="ewa-rteLine">- Replace completed set solenoid valve by removed from 2XV-16R04.</div><div class="ewa-rteLine"><br></div><div class="ewa-rteLine">- Replaced 3 way valve of offline bypass valve master valve well C and F</div><div class="ewa-rteLine"><br></div><div class="ewa-rteLine">- Replace pressure gauge of pressure regulator for choke valve well C/G/F</div><div class="ewa-rteLine"><br></div><div class="ewa-rteLine"><br></div><div class="ewa-rteLine">Follow up work</div><div class="ewa-rteLine"><br></div><div class="ewa-rteLine">- Found 2PCV-16030 (Back start) gas continue vent at vent port to be replace new one.</div><div class="ewa-rteLine"><br></div><div class="ewa-rteLine"><br></div><div class="ewa-rteLine"><br></div></div></div><div class="ewa-rteLine"> </div>', NULL, '2025-02-03 19:51:31', '2025-02-03 20:05:49', 'PTTEP\\GBS.EI-Workshop', 'PTTEP\\GBS.EI-Workshop', false, 'G2S') RETURNING id INTO new_report_id;
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Theeraphan', NULL, 'EXTERNAL', '2025-02-03 19:51:31', '2025-02-03 20:05:49', 'PTTEP\\GBS.EI-Workshop', 'PTTEP\\GBS.EI-Workshop');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Lue', NULL, 'EXTERNAL', '2025-02-03 19:51:31', '2025-02-03 20:05:49', 'PTTEP\\GBS.EI-Workshop', 'PTTEP\\GBS.EI-Workshop');
