  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S SCADA server 2AOS-3002 cannot run service Arch', 'Automation', 'CM', 'Completed', '2025-02-06', '<p>T/S SCADA server 2AOS-3002 cannot run service ArchestrA.DASABCIP.5</p><p>- Service ArchestrA.DASABCIP.5 (responsible for communication with the Gateway PLC) failed to restart after being deactivated for WPS19 commissioning job. The failure was due to a missing configuration file (dasabcip.aacfg).</p><p>- Copying the file from the redundant server, 2AOS-3003, resolved the issue.</p><p>-The file''s disappearance is suspected to have occurred during vendor-performed SCADA YPM job in December of last year, with the period we updated antivirus software, backed up data, and cleaned all servers and workstations.</p><p>- We recommend deactivating and reactivating all services after each SCADA YPM job as a preventative measure.</p><p>- For more detail and screen capture please find attached or visit link: https://pttep.sharepoint.com/:b:/s/THG2S/ES-ql_gna_JPpok0L2pCsxIBVit5jTT4q2-vNi3bSw3UtA?e=6vgifv</p>', NULL, '2025-02-07 08:58:36', '2025-02-07 09:03:41', 'PTTEP\\GBS.Automation', 'PTTEP\\GBS.Automation', false, 'G2S') RETURNING id INTO new_report_id;
