  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBN-A-3460C', 'GBN-A-3460C', '2ND STAGE DISCHARGE COOLER-TRAIN 3 C FAN', NULL, NULL, '2ND STAGE DISCHARGE COOLER-TRAIN 3 C FAN', 'GBN-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
