  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'PM-1245 Main lube oil pump overhaul ', 'Turbine Mech', 'CM', 'Completed', '2025-02-11', '<div>PM-1245 Main lube oil pump overhaul due to DE vibrtion impact high</div><div>Dismantled pump then cleaning and inspection found:-</div><div>- Driving rotor screw found pitting corrosion 20% on screw surface at discharge port area.</div><div>- Driven screws normal condition.</div><div>&nbsp;- Ball bearing unsmooth rotating by hand.</div><div>- Mechcanical seal is good condition.</div><div>- Spider flex joint coupling found wornout 2 point, reused old part.</div><div>- Replaced Mechanical seal.</div><div>- Replaced O-Rings between pump body and bedplate.</div><div>- O-Ring for pump suction pipe and discharge pipe reused due to don''t have spare part in repare kit.&nbsp;</div><div>- Replaced Ball bearing PP047BME 6308 and snap ring.</div><div>- Replaced shaft bushing</div><div>- Hex Bolts 1/2-13 inch (17 ea) of pump bedplate&nbsp; were coorosions need to be replace by B7 TPFE coating.</div><div>- Reassembled all pump parts.</div><div>- Installed motor and piping.</div><div>- Test run, Normal Pump discharge Pressure 2.77 bar, MLO pressure 1.5 bar, filter diff press 0.45 bar</div><div>- Collect vibration data, Normal.</div>', '<p>Motor overhaul by E&amp;I Team</p><p><br></p><p>Report </p><p>C:\\Users\\Art.MechTurbine\\PTT Exploration and Production Public Company Limited\\ARTHIT Field - SA-Mechanic\\ART-MECH-SMART-DMS\\Turbine\\02. Feed Gas Compressor\\Report\\FGC\\A-1210\\2025</p><p><br></p><p>Pictures</p><p>C:\\Users\\Art.MechTurbine\\PTT Exploration and Production Public Company Limited\\ARTHIT Field - SA-Mechanic\\ART-MECH-SMART-DMS\\Turbine\\21. Picture\\2025\\11 Feb 2025\\PM-1245 Overhaul</p><p><br></p>', '2025-02-12 10:21:07', '2025-02-12 17:49:47', 'PTTEP\\Art.MechTurbine', 'PTTEP\\Art.MechTurbine', false, 'ART') RETURNING id INTO new_report_id;
