  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, ' AQP Crane water bag proof load test.  ', 'Mechanic', 'CM', 'Completed', '2025-02-13', '<p></p><p>&nbsp;AQP Crane water bag proof load test after pad eye repair.</p><p>-Perpare tool and equipment.</p><p>-Crane function test and inspect.</p><p>-Set up water bag and lifting gear.</p><p>-Fill up water to water bag by use fire water to supply.</p><p>-Perform static load test @125% of SWL ,Not over WLL 18 MT.</p><p>As per below crane load chart </p><p>- Working radius = 18 meters - Boom angle = 44 Degrees - Capacity = 13.4 MT</p><p>Step 1 load 25% 3.35 MT operate crane fuction.</p><p>Step 2 load 50% 6.7 MT operate crane fuction.</p><p>Step 3 load 75% 10.05 MT operate crane fuction.</p><p>Step 4 load 100% 13.44 MT operate crane fuction.</p><p>Step 5 load 125% 16.75 MT then stop engine and check angle ,check winch slip.</p><p>-Release water from water bag.</p><p>-Perform MT the pad eye and main hook agian then apply painting.</p>', NULL, '2025-02-13 18:30:15', CURRENT_TIMESTAMP, 'PTTEP\\art.mechcrane', NULL, false, 'ART') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-CR-7020', 'ART-CR-7020', 'PEDESTAL CRANE ART-QP', NULL, NULL, 'PEDESTAL CRANE ART-QP', 'ART-QP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
