  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S fire detection system fault alarm of DG-2378A ', 'Electrical', 'CM', 'Complete', '2025-02-18', '<p>Found alarm "Actuators" at XC-1003-A, show alarm HMI "fire detection system fault alarm".</p><p>&nbsp;- Check loop&nbsp; monitoring coil relay of Main SV/Spare SV (Continue measure = 0.2 Ohm from card XCM 1002 X6-3, X6-4 to coil relay) and all re-tightening.&nbsp;</p><p>&nbsp;- Measure resistance coil relay Main SV = 644.6 Ohm and Spare SV = 640 Ohm (Ref from data sheet line monitoring calibration within a rang 1-900 Ohm)&nbsp; .</p><p>&nbsp;- Replaced battery by new one 2 cell due to battery old condition (Produced on&nbsp; year 2021).</p><p>&nbsp; &nbsp; - Cell 1 = 13.56 Vdc, Cell 2 = 13.51 Vdc and total 27.06 Vdc (Ref from data sheet battery Max/Min rang 22.5 Vdc - 27.6 Vdc).</p><p>&nbsp;- Re-calibration alarm cleared and running generator unit A, unit B stand by.&nbsp; &nbsp; &nbsp;&nbsp;</p>', '<p><a href="http://WP13 TS Diesel generator unit A fire detection fault alarm 24-10-24">WP13 TS Diesel generator unit A fire detection fault alarm 24-10-24</a><br></p>', '2025-02-18 20:36:00', '2025-02-18 20:45:41', 'PTTEP\\Bongkot.Elec-Lead', 'PTTEP\\Bongkot.Elec-Lead', false, 'G2N') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBN-DG-2378A', 'GBN-DG-2378A', 'DIESEL GENERATOR A', NULL, NULL, 'DIESEL GENERATOR A', 'GBN-WP13', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
