  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Troubleshooting low oil level on G-9110 at ZMS.', 'Mechanic', 'CM', 'In Progress', '2025-02-20', '<p>Troubleshooting of low oil level on G-9110 at ZMS.</p><p>- Removed crankcase cover and check inside engine sump oil level.(Found low oil level)</p><p>- Check oil traces inside engine radiator coolant tank. (No abnormality found)</p><p>- Found one engine radiator cap damage and replaced with new one.</p><p>- Check ol traces at turbocharger air inlet by using with bore-scope.(No abnormality found)</p><p>- Removed and random check some spark plugs physical condition .(Found carbon deposit formation)</p><p>- Randomly check cylinders combustion chamber by using with bore-scope.(Found carbon deposit formation on piston crown)</p><p>- Check crankcase air breather filters condition.(No abnormality found)</p><p>- Topped up lube oil (Methana)about 50 liters to engine sump.</p><p>- Inform to Operator to closely monitor on oil consumption and oil level.</p>', NULL, '2025-02-20 17:16:23', CURRENT_TIMESTAMP, 'PTTEP\\ZOC.Mech-Tec', NULL, false, 'ATL') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-MS-G-9110-PACKAGE', 'ATL-MS-G-9110-PACKAGE', 'Gen, ZMS Gas Generator package1', NULL, NULL, 'Gen, ZMS Gas Generator package1', 'MS', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
