-- Inserting report ID 26374
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Calibrate new transmitter FQI89300 of G8930', 'Electrical & Instrument', 'CM', 'Under Monitoring', '2025-02-20', '<div><u>Today activity</u></div><div><p>Calibration and loop test new transmitter FQI-89300 of gas generator G-8930</p><p><br></p><p><u>Action</u></p><p>- Self-isolation FQI-89300</p><p>- Perform loop test 4-20mA</p><p>- Adjust upper range 934.234 to 327.8 stdcuft/min as PMO/I recommend</p><p>- Pressure simulation with manual hand pump</p><p>- Flow values on local and DCS are approximately equal.</p><p>- Now, keep monitoring condition</p><p><br></p><p><u>History (19-Feb2025)</u></p><p>- Found gauge pressure unit was KPa in transmitter display</p><p>- Change gauge pressure unit KPa to Bar by Hart protocol</p><p>- Check configuration of new transmitter</p><p>- Monitor parameters of transmitter by G8930 full load running</p><p><br></p><p><u>History (18-Feb-2025)</u></p><p>- Process isolation by OPT before transmitter replacement</p><p>- Save configuration of old transmitter</p><p>- Dis-assemble transmitter from process line</p><p>- Check transmitter gasket condition (Normal)</p><p>- Replace new transmitter</p><p>- Upload configuration from old transmitter to new</p><p>- New transmitter <u>upper range</u> cannot be over 934.923 Stdcuft/min. </p><p>&nbsp; &nbsp; &nbsp;(5319.96 stdcuft/min in old one)</p><p>- Test run G8930 and monitor parameters of Pressure/ Temperature &amp; Flow rate.</p><p>- Although flow rate value was showed 42.5 Stdcuft/min, just 15.2 Stdcuft/min on DCS during generator&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;load share running.</p><p>- Continue checking configuration of transmitter tomorrow</p></div>', 'MESC- 60.30.67.200.9', '2025-02-20 18:02:48', '2025-02-20 18:03:46', 'PTTEP\\ZOC.Elec-Tec', 'PTTEP\\ZOC.Elec-Tec', false, 'ATL') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-G-8930-PACK', 'ATL-OC-G-8930-PACK', 'Gen, ZOC Gas Generator Package 3', NULL, NULL, 'Gen, ZOC Gas Generator Package 3', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Htet', NULL, 'EXTERNAL', '2025-02-20 18:02:48', '2025-02-20 18:03:46', 'PTTEP\\ZOC.Elec-Tec', 'PTTEP\\ZOC.Elec-Tec');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Bone', NULL, 'EXTERNAL', '2025-02-20 18:02:48', '2025-02-20 18:03:46', 'PTTEP\\ZOC.Elec-Tec', 'PTTEP\\ZOC.Elec-Tec');
