  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Verified unexcepted shutdown ESD1.', 'Instrument', 'CM', 'Complete', '2025-02-20', '<p>Verified unexcepted shutdown ESD1.</p><p>  - Observed the HP2 loop and 5 bar logic pressure lost.</p><p>  - Verified the Versa pilot valve on logic 5 bars loop, found no passing.</p><p>  - Selected the selector valve to use pressure source from HP3 to monitor pressure about 1hr, no pressure drop and passing was found.</p><p>  - Selected the selector valve to use pressure source from HP2 to monitor pressure for 1 hr, observed HP2 pump running sometime.</p><p>  - Verified HP2 hydraulic loop, found the closing solenoid of choke valve well He was internal passing. Swopped the SOV from choke valve well E and function tested, satisfied. </p><p>Area of concern, Voltage is 26.1 Vdc, Positive with ground is 23. 9 Vdc Negative with ground is -2.2 Vdc</p>', NULL, '2025-02-20 18:56:11', CURRENT_TIMESTAMP, 'PTTEP\\Bongkot.Inst-Lead', NULL, false, 'G2N') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBN-WP14', 'GBN-WP14', 'BONGKOT NORTH WELLHEAD PLATFORM WP14', NULL, NULL, 'BONGKOT NORTH WELLHEAD PLATFORM WP14', 'GBN-WP14', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Anuwat', NULL, 'EXTERNAL', '2025-02-20 18:56:11', CURRENT_TIMESTAMP, 'PTTEP\\Bongkot.Inst-Lead', NULL);
