  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Re-config solar charger controler.', 'Electrical', 'OTH', 'Completed', '2025-02-21', '<div class="ewa-rteLine">Verify solar charger system parameter and re-config.</div><div class="ewa-rteLine">- Charger controller unit A (T76), B(T86), C (T96) and D (T106) were changed the parameter setting as EMX E recommended.</div><div class="ewa-rteLine">- Checked and Changed all parameter of custom set points as follows;</div><div class="ewa-rteLine">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Absorption voltage 28.8 V (2.4 Vpc) = 14.4 V&nbsp;</div><div class="ewa-rteLine">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Float voltage 27.0 V (2.25 Vpc) = 13.5 V&nbsp;</div><div class="ewa-rteLine">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Absorption time 1:00:00 hour&nbsp;</div><div class="ewa-rteLine">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Battery high voltage disconnect (HVD) 30.0 V = 15.0 V&nbsp;</div><div class="ewa-rteLine">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Battery high voltage reconnect (HVDR) 28.8 V = 14.4 V&nbsp;</div><div class="ewa-rteLine">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;- Enable Maximum Regulation Limit at 28.8 V = 14.4 V</div><div class="ewa-rteLine"><br></div><div class="ewa-rteLine">Inspect voltage at battry pole and sensing terminal at controller charger result same both point, bank A 28.8 V and bank B 28.3 V.</div>', NULL, '2025-02-21 20:41:18', '2025-02-22 06:16:53', 'PTTEP\\GBS.EI-Workshop', 'PTTEP\\GBS.EI-Workshop', false, 'G2S') RETURNING id INTO new_report_id;
