  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Annual Maintenance Process online AIT-1400', 'Instrument', 'PM', 'In Progress', '2025-02-21', '<table itemprop="copy-paste-table"><tbody><tr><td><p><strong><u>Annual Maintenance Process online gas chromatograph, AIT-1400</u></strong></p><ul><li><strong>Switch the Gas Chromatograph (GC) to Calibration Mode</strong>:</li></ul><p>Ensure the system is set to the appropriate mode for accurate calibration procedures.</p><ul><li><strong>Verify Analysis Results and Chromatograph</strong>:</li></ul><p>Carefully review the analysis results and inspect the chromatograph to confirm data accuracy and system performance.</p><ul><li><strong>Perform an As-Found Check</strong>:</li></ul><p>Conduct an initial assessment of the system''s condition before any maintenance or adjustments are made.</p></td></tr></tbody></table><ul><li><strong>Overhaul six-port valves No. 2 and No. 3</strong>:</li></ul><p>Perform a comprehensive overhaul of six-port valves number 2 and 3,&nbsp;to ensuring all components are cleaned, inspected, and reassembled to restore optimal functionality.&nbsp;</p><table itemprop="copy-paste-table"><tbody><tr><td><ul><li><strong>Reassemble the System and Conduct Overnight Analysis for Purging:</strong></li></ul><p>Reassemble all components and perform an overnight analysis to purge the system, ensuring it is free from contaminants and operating efficiently.</p></td></tr></tbody></table>', NULL, '2025-02-22 17:33:48', CURRENT_TIMESTAMP, 'PTTEP\\Art-Tech-Prod-Maint', NULL, false, 'ART') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-AIT-1400', 'ART-AIT-1400', 'ANALYSIS TRANSMITTER(UOP C6 GC)', NULL, NULL, 'ANALYSIS TRANSMITTER(UOP C6 GC)', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
