  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Verifying for the root cause of platform tripped.', 'Instrument', 'CM', 'Under Monitoring', '2025-02-22', '<p>Continued verifying for the root cause of platform tripped.</p><p>- Replaced the new solenoid valve and relay valve of US-1402 ( ESD-1 at PP).</p><p> </p><p> - Found the HP2 loop and 5 bar logic pressure lost.</p><p>  - Function tested all pilot versa valves on the CP-2400 common alarm, found all were normal.</p><p>  - Isolated main supply valve (1- 36) (1-37) and (1-39) of 5 barg logic to monitor pressure, no pressure drop was found.</p><p>- Found 5 bar logic was dropped from <span style="background-color: rgb(255, 255, 0);">PDSHH-2400</span> loop was passing, then <span style="background-color: rgb(255, 255, 0);">isolate main supply valve (1-35 )</span>. Tobe verify again on tomorrow.</p><p>- Found the PSV-2400M hydraulic passing then swopped from well A to M.</p><p> </p><p> - Function tested on reservoir Level switch-2400, pressure switch-24001, 24002, 24003 and 24004, all were normal. </p><p> - Selected both selector valve to use pressure source from HP3 and keep monitoring.</p><p> - To be continued.&nbsp;</p>', NULL, '2025-02-22 21:54:14', CURRENT_TIMESTAMP, 'PTTEP\\Bongkot.Inst-Lead', NULL, false, 'G2N') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBN-WP14', 'GBN-WP14', 'BONGKOT NORTH WELLHEAD PLATFORM WP14', NULL, NULL, 'BONGKOT NORTH WELLHEAD PLATFORM WP14', 'GBN-WP14', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Anuwata', NULL, 'EXTERNAL', '2025-02-22 21:54:14', CURRENT_TIMESTAMP, 'PTTEP\\Bongkot.Inst-Lead', NULL);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Worrachat', NULL, 'EXTERNAL', '2025-02-22 21:54:14', CURRENT_TIMESTAMP, 'PTTEP\\Bongkot.Inst-Lead', NULL);
