  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, '2MS-3710 Membrane replacement', 'Mechanic', 'CM', 'In Progress', '2025-02-23', '<p align="left">o&nbsp;&nbsp; Remove the elbow line and Taper-Lok flange.</p>  <p align="left">o&nbsp;&nbsp; Disconnect the Taper-Lok tube and membrane element by disconnect the clamp.</p>  <p align="left">o&nbsp;&nbsp; Remove 1<sup>st</sup>, 2<sup>nd</sup> and 3<sup>rd</sup> membrane element by disconnect the clamp, center ring and check valve.</p>  <p align="left">o&nbsp;&nbsp; Clean and inspect membrane housing.</p>  <p align="left">o&nbsp;&nbsp; Clean and inspect elbow flange and Taper–Lok flange.</p>  <p align="left">o&nbsp;&nbsp; Install new membrane to membrane housing. </p>  <p align="left">o&nbsp;&nbsp; Lube high vacuum grease to U-Cup seal of the membrane.</p>  <p align="left">o&nbsp;&nbsp; Replace the check valve, centering, O-ring and taper-lock seal ring.</p>  <p align="left">o&nbsp;&nbsp; Re-install the Taper-Lok flange and elbow line.</p>  <p align="left">o&nbsp;&nbsp; Replace new spiral wound gasket 3”#600.</p>  <p align="left">o&nbsp;&nbsp; Torque taper-lok flange Bolt dia 7/8”, apply Molykote 1000 Friction coefficients=0.125</p>  <p align="left">o&nbsp;&nbsp; Torque value= 150 ft-lb (205 N-M). As per UOP manual.</p>  <p align="left">o&nbsp;&nbsp; Today done tube 1-12 on top and bottom bank. Unless tube 13 continue tomorrow&nbsp;</p>', NULL, '2025-02-23 17:48:14', CURRENT_TIMESTAMP, 'PTTEP\\GBS.Mechanic-WorkS', NULL, false, 'G2S') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-2MS-3710', 'GBS-2MS-3710', 'MEMBRANE UNIT 1', NULL, NULL, 'MEMBRANE UNIT 1', 'GBS-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
