  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Skipt the SGC-1 BUOSM overdue alarm.', 'Turbine E&I', 'CM', 'Completed', '2025-02-23', '<p>Skip BUOSM overdue (Backup overspeed test overdue) by setting the "Last_stest_Hours" by today.</p><p>&nbsp;- Should note, that the CPU must be "REM" position while the Unit was online and load.</p><p>&nbsp;- After Online the Unit PLC application "Logic 5000" &gt; go to "Framwork_5007_11</p><p>&nbsp;- The Open the first "Sub Routin" &gt; _010_OSM_Gear_2S_090.</p><p>&nbsp;- Then Go to "Lung: 13"&nbsp;</p><p>&nbsp;- "Double-click under the "Last_STest_Hours" the key in the number same as the above number. (The current Ening Fire Hours).</p><p>&nbsp;- After Enter, For SGC-1 (Under "TCP") CCR needs to be requested to reset.</p><p><br></p><p></p><p><br></p><p>&nbsp;</p>', NULL, '2025-02-23 21:27:47', CURRENT_TIMESTAMP, 'PTTEP\\Arthit.EI-Turbine', NULL, false, 'ART') RETURNING id INTO new_report_id;
