-- Inserting report ID 26537
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Perform YPM Diesel centrifuge (CONCOR-Hybrid work)', 'Mechanic', 'PM', 'Completed', '2025-02-24', '<p>1. Perform electrical and process isolation.</p><p>2. Drain and top lube oil bearing centrifuge.</p><p>3. Replace driven belt. Found driven normal condition.</p><p>4. Clean and check internal part of centrifuge. Found internal part normal condition.</p><p>&nbsp; &nbsp; &nbsp;4.1 Remove Centripetal pump and fasten hood. (Pipe wrench)<br>&nbsp; &nbsp; &nbsp;4.2 Open centrifuge hood. (Wrench# 3/4")<br>&nbsp; &nbsp; &nbsp;4.3 Remove bowl lock ring. The bowl must be rotate clockwise. (Special tool)</p><p>&nbsp; &nbsp; &nbsp;4.4 Remove&nbsp; and clean distrubutor.</p><p>&nbsp; &nbsp; &nbsp;4.5 Remove and clean separating disk.<br>&nbsp; &nbsp; &nbsp;4.6 Clean inside solids holding space.</p><p>5. Clean strainer. Found strainer a little dirty.</p><p>6. Replace coupling feed pump.</p><p>7. Housekeeping.</p><p>8. Perform electical and process de-isolation.</p><p>9. Test running and monitoring.</p>', '<p><a href="https://pttep.sharepoint.com/sites/THART/Mechanic/Forms/AllItems.aspx?id=%2Fsites%2FTHART%2FMechanic%2FART%2DMECH%2DSMART%2DDMS%2FPump%2FAPP%2FAPP%20Lower%20Deck%2FP%2D5515%2FPicture%2FYPM%20with%20CONCOR%20%28Hydbrid%20work%29&amp;viewid=69417a80%2D5c8c%2D4085%2D8019%2D21267735720d&amp;noAuthRedirect=1" target="_blank">Picture attached please ckick here</a><br><br><a href="https://pttep.sharepoint.com/sites/THART/Mechanic/Forms/AllItems.aspx?id=%2Fsites%2FTHART%2FMechanic%2FMechanical%20%28Most%20Updated%29%2F01%2E%20Main%20Equipment%2F12%2E%20Vendor%20Dossier%2F121%2E%20APP%20Vendor%20Manual%2FPM006%20Diesel%20Centrifuge%20%28comp%29%2FDiesel%20centrifuge%20manual&amp;viewid=69417a80%2D5c8c%2D4085%2D8019%2D21267735720d" target="_blank">Manual please click here</a><br><br><br></p><p></p><p><br>Tool lists.</p><p>1. Wrench# 1/2", 9/16",&nbsp; 5/8", 3/4'', 11/16", 1-1/16"<br>2. Allen wrench 5 mm.</p><p>3. Specail tools for remove centrifuge bowl.<br><br></p>', '2025-02-24 16:35:04', '2025-02-24 16:56:43', 'PTTEP\\Art.MechBC', 'PTTEP\\Art.MechBC', false, 'ART') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-A-5515', 'ART-A-5515', 'DIESEL FUEL CENTRIFUGE PACKAGE', NULL, NULL, 'DIESEL FUEL CENTRIFUGE PACKAGE', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Pawaris L.', NULL, 'EXTERNAL', '2025-02-24 16:35:04', '2025-02-24 16:56:43', 'PTTEP\\Art.MechBC', 'PTTEP\\Art.MechBC');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'CONCOR Team.', NULL, 'EXTERNAL', '2025-02-24 16:35:04', '2025-02-24 16:56:43', 'PTTEP\\Art.MechBC', 'PTTEP\\Art.MechBC');
