  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Troubleshoot lube oil pressure low ', 'Mechanic', 'CM', 'Under Monitoring', '2025-02-25', '<p align="left"><b><u>Troubleshoot lube oil pressure low </u></b></p>  <p align="left">- Found water about 3 liter mix with gear box lube oil</p>  <p>- Investigated suspected water mix with air discharge due to electric auto drain does not function, So line air purging and venturi crank case breather trap from discharge line, Suspected root course remove any water that may have mixed with the oil.</p>  <p><span style="background-color: rgb(255, 255, 0);">- E&amp;I team function test auto drain in unit stop is normal but unit running electric auto drain does not function</span>.</p>  <p>- E&amp;I team acknowledged the problem: they''ve identified the need to replace the faulty electric auto drain.</p>  <p align="left">- Replaced filter gear box breather.</p>  <p align="left">- Replaced lube oil filter.</p>  <p align="left">- Replaced lube oil with Atlas Copco ROTO Z Oil: 80 L.</p>  <p>- Manual drain valve adjustment: the valve was opened 10% in "lead mode" to allow manual draining while further investigation continues.</p>  <p>- Test run found lube oil pressure normal</p>', '<p><a href="https://pttep.sharepoint.com/:w:/r/sites/THG2S/DS03Maintenance/031%20DBS_MM/05.%20Report/52.%20Job%20Completed%20%20report/521.%20PPS%20Completed%20%20Report/Air%20compressor%20(2X-5310)/2K-5310A/2025/2025.02.25%202X-5310A%20TS%20Water%20mix%20with%20lube%20oil.docx?d=w2024f4b2f61c4330b6fbc8c4f3debe40&amp;csf=1&amp;web=1&amp;e=cYTeVv" target="_blank">Report report </a><br></p>', '2025-02-26 10:33:13', '2025-02-26 10:34:40', 'PTTEP\\GBS.Mechanic-WorkS', 'PTTEP\\GBS.Mechanic-WorkS', false, 'G2S') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-2X-5310A', 'GBS-2X-5310A', 'AIR COMPRESSOR PACKAGE A', NULL, NULL, 'AIR COMPRESSOR PACKAGE A', 'GBS-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Surachai J and Patawee J.', NULL, 'EXTERNAL', '2025-02-26 10:33:13', '2025-02-26 10:34:40', 'PTTEP\\GBS.Mechanic-WorkS', 'PTTEP\\GBS.Mechanic-WorkS');
