  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TS BA0267 status show travelling (MOGE PCV)', 'Electrical & Instrument', 'CM', 'Completed', '2025-02-26', '<p><b><u>Today Activity</u></b></p><p>Troubleshoot BA-0267 status show travelling at DCS. On site, show valve open position. at MOGE shelter.</p><p><br></p><p><b><u>Action</u></b></p><p>Perform work permit and tool box talk.</p><p>Go and verify the BA-0267 status.</p><p>Found that valve indicator is travelling status even valve is opening.</p><p>Open the JB and check inside JB.</p><p>Found that open magnetic positioner can''t reach to proximity switch.</p><p>Adjust magnet to reach proximity switch.</p><p>BA-0267 is open status in DCS and back in service. (Complete)</p><p><br></p>', NULL, '2025-02-26 11:45:55', '2025-02-26 11:52:31', 'PTTEP\\ZOC.Elec-Tec', 'PTTEP\\ZOC.Elec-Tec', false, 'ATL') RETURNING id INTO new_report_id;
