  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'To perform mechanical 12 MPM ', 'Mechanic', 'CM', 'In Progress', '2025-02-24', '-&nbsp; Check leak DE mechanical seal for confirm mechanical seal.<p align="left">-&nbsp; &nbsp;Drain barrier fluid and brake flange 3/4”#3-600.</p>  <p align="left">-&nbsp; &nbsp;Drain DE bearing lube oil.</p>  <p align="left">-&nbsp; &nbsp;Turn setting plate of DE mechanical seal to keep seal position.</p>  <p align="left">-&nbsp; &nbsp;Remove coupling spacer and hub.</p>  <p align="left">-&nbsp; &nbsp;Remove DE bearing housing.</p>  <p align="left">-&nbsp; &nbsp;Remove old bearing from sleeve .</p>  <p align="left">-&nbsp; &nbsp;Install new bearing with heat method temperature@110°C</p>  <p align="left">-&nbsp; &nbsp;DE Bearing, Roller SKF MTR NU 313 ECM. Qty 1 ea.</p>  <p align="left">-&nbsp; &nbsp;Replace labyrinth seal (4791) , (4811)</p>  <p align="left">-&nbsp; &nbsp;Install new bearing on pump shaft and install bearing housing.</p>  <p align="left">-&nbsp; &nbsp;Reinstall hub for set DBSE between pump with motor.</p><p align="left">-&nbsp; &nbsp;Reinstall coupling spacer to both hub.</p><p align="left">-&nbsp; &nbsp;Reinstall barrier fluid pipe line to DE mechanical seal.</p><p align="left">-&nbsp; &nbsp;Line up barrier fluid for mech seal leakage. No leak.</p><p align="left">-&nbsp; &nbsp;Top up DE bearing lube oil.</p><p align="left"><br></p>', NULL, '2025-02-26 18:33:31', '2025-02-26 18:42:46', 'PTTEP\\GBS.Mechanic-WorkS', 'PTTEP\\GBS.Mechanic-WorkS', false, 'G2S') RETURNING id INTO new_report_id;
