  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'To perform yearly PM at fire water pump 2P-5201A', 'Mechanic', 'PM', 'Completed', '2025-02-07', '<p>To perform yearly PM.</p><ul type="disc">  <li>Check      and clean air inlet filter, CAT 8N-6309      Quantity 2 ea.</li>  <li>Replace      Primary diesel filter P/N. 925009      Quantity 1 ea.</li> </ul><p align="left">-gasket kit P/N. 8695860571, Quantity 1 ea.</p><p align="left">(replaced the on duty and swap to stand by then)</p><ul type="disc">  <li>Replace      Auxiliary diesel filter (2F-5209A)      CATTERPILLAR P/N: 1R-0756 = two ea.</li>  <li>Replace      Main diesel filter (2F-5210A)      CATTERPILLAR P/N: 1R-0756 = five ea.</li>  <li>Clean      engine breather and flame arrester.</li>  <li>Visual      check belt condition and tension of alternator.</li> </ul><p align="left">·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Visual check fly wheel teeth. No sign of damaged.</p><p>          </p><p align="left">·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Clean suction strainer of engine cooling water exchanger.</p>', NULL, '2025-02-26 21:58:51', CURRENT_TIMESTAMP, 'PTTEP\\DilokT', NULL, false, 'G2S') RETURNING id INTO new_report_id;
