-- Inserting report ID 26652
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Verify and Troubleshoot ESDV 81000 Close', 'Electrical & Instrument', 'CM', 'Completed', '2025-02-27', '<p><u>Today Activity</u></p><p>Verify and Troubleshoot ESDV 81000 Close</p><p><u>Action</u>&nbsp;</p><p>-Verify fuse SOV-81000 and SOV-81718 at SIS Marshalling Cabinet</p><p>-Isolate knife switch SOV-81000 and SOV-81718</p><p>-Remove solenoid from SOV-81718</p><p>-Measure resistance 72,4 Ohm</p><p>-Install solenoid SOV81000 from SOV81718</p><p>-Replace fuse with new one at SOV81718 SIS Marshalling Cabinet</p><p>-Deisolate knife switch</p><p>-Function test is ok&nbsp;</p><p>-Now back to service</p><p><br></p><p>Solenoid&nbsp; -&nbsp; 4154230022</p><p><br></p><p><u>26.2.2025 Activity</u></p><p>Verify and Troubleshoot ESDV 81000 Close</p><p><u>Action</u>&nbsp;</p><p>-Go and Check Field junction box&nbsp;</p><p>-There is no water ingress&nbsp;</p><p>-Put the silica gel inside the junction box</p><p>-Check voltage at SOV 81000, there is no voltage at field junction box&nbsp;</p><p>-Check voltage at SDO-JB81001, there is no voltage at junction box</p><p>-Check voltage SIS Marshalling cabinet, found blown fuse&nbsp;</p><p>-Check and disconnect&nbsp; SOV81000 cable at field , measure resistance cable to ground&nbsp;</p><p>-there is a ground fault at SOV81000</p><p><br></p><p><br></p>', NULL, '2025-02-27 13:54:53', '2025-02-27 16:26:39', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.Inst-Tec', false, 'ATL') RETURNING id INTO new_report_id;
