-- Inserting report ID 26655
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'A-2210 FGC#2 Perform crank soak wash', 'Mechanic', 'CM', 'Completed', '2025-02-26', '<p></p><p>Perfrom engine crank soak&nbsp;</p><p><br></p><p>Confirm for TIT-4212 to inhibited temperature alarm HI HI TAHH-4212<br>- Opened PTW and CO2 inhibited.<br>- Opened enclosure package for check general condition.<br>- Open Gas starting isolation valve inlet starting motor 1 ea.<br>- Preparation Crank Soak wash equipment and connected hose to package.<br>- Open 3 drain valves=&gt; Air inlet duct drain, Engine drain and Power turbine drain for allowing water to drain in hazardous drain.<br>- Informed CCR before change over Control mode from “REMOTE” to “CRANK MODE”.<br>- Cleared all alarm on HMI to prepare engine ready for crank.<br>- Open Window “Start Permissive” for monitor Crank limit time count down and GG Speed.<br>- Press Manual Crank button to start CRANK sequence and waiting until crank limit time 230 sec count down to 0 sec.<br>- Injected mixed detergent Zok27 = 5.5 liters / Distillate water 22 liters 2 times by soaked 15 minutes of each time.<br>- Performed 4 time water rinse washing by distillate water.<br>- Monitor drain water from drain line ensure water color become clear.<br>- Crank dry to remove residual waste inside then engine.<br>- Package internal cleaning and inspection.<br>- Close 3 drain valves<br>- Close PTW and normalized CO2 system.<br>- Change over Control mode from “CRANK MODE” to “REMOTE”<br>- Informed CCR prepare to start engine for fire dry about 15 minutes</p>', NULL, '2025-02-27 16:14:31', '2025-02-27 16:32:02', 'PTTEP\\Art.MechTurbine', 'PTTEP\\Art.MechTurbine', false, 'ART') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-A-2210', 'ART-A-2210', 'FEED GAS COMPRESSION TRAIN 2', NULL, NULL, 'FEED GAS COMPRESSION TRAIN 2', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Thavit', NULL, 'EXTERNAL', '2025-02-27 16:14:31', '2025-02-27 16:32:02', 'PTTEP\\Art.MechTurbine', 'PTTEP\\Art.MechTurbine');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Tinnakorn', NULL, 'EXTERNAL', '2025-02-27 16:14:31', '2025-02-27 16:32:02', 'PTTEP\\Art.MechTurbine', 'PTTEP\\Art.MechTurbine');
