-- Inserting report ID 26657
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Troubleshooting G-8920 unable to start', 'Electrical & Instrument', 'CM', 'In Progress', '2025-02-27', '<p><b><u>Today Activity</u></b></p><p>TS G-8920 unable to start</p><p><br></p><p><u><b>Action</b></u></p><p>1) Adjust PCV 10 to 8 Kpa&nbsp;</p><p>2) Connect with DC desk software to AFR to monitor and save the RPM data.</p><p>3) Connect with Ignition control software to Ignition circuit to monitor and save data.</p><p>4) Test run G8920 with battery starter.</p><p>G8920 can''t start.</p><p><br></p><p><u><b>Mechanic Action</b></u></p><p>1) Installed digital pressure gauge at downstream GCV to monitor.</p><p>2) Adjusted downstream PCV fuel gas pressure up to 8 Kpa.</p><p>3) Inspected breather cartridges in both bank-A and B.</p><p>4) Refitted ignition coil wire connection in both bank-A and B.</p><p>5) Inspected and cleaned air filters.</p><p><br></p><p><b><u style="background-color: rgb(255, 255, 0);">History (26.02.2025)</u></b></p><p><b><u style="background-color: rgb(255, 255, 0);">Today Activity</u></b></p><p><span style="background-color: rgb(255, 255, 0);">G8920 battery charging &amp; speed sensor replacement</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><u><b style="background-color: rgb(255, 255, 0);">Action</b></u></p><p><span style="background-color: rgb(255, 255, 0);">Perform work permit and tool box talk.</span></p><p><span style="background-color: rgb(255, 255, 0);">Charge the battery bank1 at battery room.</span></p><p><span style="background-color: rgb(255, 255, 0);">Install back to test run after magnetic pick up installation done.</span></p><p><span style="background-color: rgb(255, 255, 0);">Replace with new over speed sensor (60.07.79.001.9).</span></p><p><span style="background-color: rgb(255, 255, 0);">Test run G8920 with battery charger.</span></p><p><span style="background-color: rgb(255, 255, 0);">Can''t start the engine. Stuck at starting state.</span></p><p><br></p>', NULL, '2025-02-27 17:01:38', '2025-02-27 17:09:11', 'PTTEP\\ZOC.Elec-Tec', 'PTTEP\\ZOC.Elec-Tec', false, 'ATL') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-G-8920', 'ATL-OC-G-8920', 'Gen, Generator ZOC Gas gen 1', NULL, NULL, 'Gen, Generator ZOC Gas gen 1', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
