  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'WP13: T/S DG-2378A Cerberus fire detection system ', 'Electrical', 'CM', 'In Progress', '2025-02-28', '<div>T/S DG-2378A Cerberus&nbsp;fire detection system fault</div><div>- Found Cerberus show Actuators and Fire control fault alarm, checked loop of both interposing relay and Co2 cylinder solenoid coil, no abnormal found, after reset the alarm disappeared.</div><div>&nbsp; &nbsp; - Loop resistance of Main/Spare Co2 cylinder interposing relay (with cable) = 643/636 ohm</div><div>- Simulated possible root cause actuator alarm by connected external resistance 643 ohm (normal condition of Main interposing relay loop)</div><div>&nbsp; &nbsp; - Low alarm activated at about 548 ohm</div><div>&nbsp; &nbsp; - High alarm activated at about 738 ohm</div><div>- Loop voltage in normal condition 0-1.6Vdc (swing status suspected PWM)</div><div>- Loop voltage in abnormal condition 2.5-3.5Vdc (simulated by remove interposing relay (open circuit) alarm actuators shown)</div><div>- Continue T/S on another possible root cause actuator alarm.</div><div>- Repaired cable X9-1, X9-2 (Monitored input 1), and re-align resistance devices at nearly terminal in order to prevent signal fault.</div><div>- Keep Spare Co2 cylinder on duty for monitoring</div>', '<a href="https://pttep.sharepoint.com/:f:/r/sites/THG2N/DL_Selective_Access/02-PBN-M/02%20MEI/19%20Photos/00%20Electrical%20Photos/WPs%20PICTURES/WP13/DIESEL%20GENERATOR/2025-02-28%20TS%20DG-2378A%20Cerberus%20fire%20detection%20system%20fault?csf=1&amp;web=1&amp;e=C19Tpm">2025-02-28 TS DG-2378A Cerberus fire detection system fault</a><br>', '2025-02-28 20:32:10', '2025-03-11 13:48:12', 'PTTEP\\Bongkot.Elec-Lead', 'PTTEP\\Maintenance-Co', false, 'G2N') RETURNING id INTO new_report_id;
