  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S TG-5610 cannot change over to liquid mode', 'Instrument', 'CM', 'Complete', '2025-03-02', '<p>T/S TG-5610 cannot change over to liquid mode.</p><p>Weekly change over generator.</p><p>&nbsp;TG-5610: Start-up with gas mode.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Change to liquid mode, found engine trip with alarm: Engine Flameout Detected By High Fuel Flow&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Function test flameout pressure switch S349, found its working normally.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; function test liquid fuel shutoff valve L349_2, found it did not open smoothly. Then exercise valve by stroking.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Start-up with gas mode and change over to liquid mode, found working properly.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Change back to gas mode and synchronize to system at 3:15 P.M.</p>', NULL, '2025-03-02 16:15:59', '2025-03-02 16:21:19', 'PTTEP\\Turbine', 'PTTEP\\Turbine', false, 'G2N') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBN-TG-5610-FU', 'GBN-TG-5610-FU', 'FUEL SYSTEM', NULL, NULL, 'FUEL SYSTEM', 'GBN-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Anusorn', NULL, 'EXTERNAL', '2025-03-02 16:15:59', '2025-03-02 16:21:19', 'PTTEP\\Turbine', 'PTTEP\\Turbine');
