  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, '(C)T/S EDG-5610 alarm and could not start.', 'Electrical', 'CM', 'In Progress', '2025-03-02', '<p>(C)T/S EDG-5610 show alarm and could not start. (Since 27-Feb-2025)</p><p>- The EDG-5610 show fault <span style="background-color: rgb(255, 255, 0);">2UA-561072 Communication with Synchro-Coupling System Lost.</span></p><p>- Found EDG being inhibit to start.</p><p>- Found DSP1 watch dog was failure (cause of inhibit to start).</p><p>- Performed back-up PLC communication card by automation.</p><p>- Performed verified LAN and communication cables DSP1 to PLC1A, Found all cables good condition.</p><p>- Performed a power reset on DSP1 and found that the EDG alarm remained.</p><p>- Replaced the communication card and found that the EDG alarm remained, along with additional alarms, including the <span style="background-color: rgb(255, 255, 0);">2UA-561918 AVR fault.</span></p><p>- Re-installed the old communication card because it was not defective.</p><p>- Furthermore, the new DSP1 will be replaced, and we will consult with the electrical engineer.</p>', 'DSP, 2HEnergy, Type: MAGE DSP-C, Software V2.01.2&nbsp;', '2025-03-02 17:20:59', '2025-03-10 07:13:32', 'PTTEP\\GBS.EI-Workshop', 'PTTEP\\GBS.EI-Workshop', false, 'G2S') RETURNING id INTO new_report_id;
