-- Inserting report ID 26927
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, '2Z-5080A,Vessel and elements cleaning.', 'Mechanic', 'CM', 'Completed', '2025-03-03', '<p>2Z-5080A,Vessel and elements cleaning.</p><p align="left">o&nbsp;&nbsp; Request to Process isolation.</p><p align="left">o&nbsp;&nbsp; Remove 2 liquid pipe spools 2” 300# for open the vessel flange.</p><p align="left">o&nbsp;&nbsp; Open vessel flange 20” 300#.</p><p align="left">o&nbsp;&nbsp; Remove all of DSS liners, quantity 45 pieces.</p><p align="left">o&nbsp;&nbsp; Found sand collecting at the bottom of vessel, 40% of the vessel volume. </p><p align="left">o&nbsp;&nbsp; Remove sand and clean up vessel.</p><p align="left">o&nbsp;&nbsp; Request Inspector to inspection the hot spare liners and vessel.</p><p align="left">o&nbsp;&nbsp; Replace all DSS liners by new spare 45EA.</p><p align="left">o&nbsp;&nbsp; Close vessel flange and apply torque at 345 ft-lb (468 Nm), material stainless (660).</p><p align="left">o&nbsp;&nbsp; Reinstall 2 liquid pipe spools 2” 300#, torque at 67 ft-lb. (91 Nm). </p><p align="left">o&nbsp;&nbsp; Request to Process de-isolation for leakage test @ 23 bar.</p><p align="left">o&nbsp;&nbsp; Found no leak and normal operate.</p><p>                        </p><p align="left">o&nbsp;&nbsp; Clean up all dirty DSS liners and keep for hot spare.</p>', NULL, '2025-03-03 16:31:25', CURRENT_TIMESTAMP, 'PTTEP\\GBS.Mechanic-WorkS', NULL, false, 'G2S') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-2Z-5080A', 'GBS-2Z-5080A', 'PRD WATER DEOIL HYDROCYCLONE VESSEL A', NULL, NULL, 'PRD WATER DEOIL HYDROCYCLONE VESSEL A', 'GBS-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Patawee J. Pornthep K. and 4CR', NULL, 'EXTERNAL', '2025-03-03 16:31:25', CURRENT_TIMESTAMP, 'PTTEP\\GBS.Mechanic-WorkS', NULL);
END $$;

