BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S Hypochioinator A-4670 unit A tripped', 'Instrument', 'CM', 'Completed', '2025-03-05', '<div class="ewa-rteLine">T/S Hypochioinator A-4670 unit A tripped.</div><div class="ewa-rteLine">- Found HMI was showing alarm Rectifier-A Fault and System Fault since 4/3/2025 - 17:07</div><div class="ewa-rteLine">&nbsp;</div><div class="ewa-rteLine">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</div><div class="ewa-rteLine"><br></div><div class="ewa-rteLine"><br></div><div class="ewa-rteLine">- Found MCB-100A inside Rectifier-A Control Panel (UCP-PP-4670A) tripped</div><div class="ewa-rteLine"><br></div><div class="ewa-rteLine">&nbsp;&nbsp;</div><div class="ewa-rteLine"><br></div><div class="ewa-rteLine">- Visual check inside UCP-PP-4670A and measured incoming MCB that found voltage is 404 VAC.</div><div class="ewa-rteLine">- Measure outgoing of transformer for supply 24 VDC inside UCP that the wiring are not grounding then closed MCB but it tripped immediately.</div><div class="ewa-rteLine"><br></div><div class="ewa-rteLine">&nbsp;</div><div class="ewa-rteLine"><br></div><div class="ewa-rteLine">- Found SCR Firing Module terminal-P2 and Rectifier Controller Power terminal (24VDC/Com-) were not firm then secure them into the socket and also re-tighten all terminal.</div><div class="ewa-rteLine"><br></div><div class="ewa-rteLine">&nbsp;</div><div class="ewa-rteLine"><br></div><div class="ewa-rteLine">- Reset MCB and function tested, found normal working.</div><div class="ewa-rteLine"><br></div><div class="ewa-rteLine">&nbsp;&nbsp;&nbsp;&nbsp;<br></div><div class="ewa-rteLine"><br></div><div class="ewa-rteLine">- Keep monitoring.</div><div class="ewa-rteLine"><br></div>', '<p>Photo :</p><p>https://pttep.sharepoint.com/sites/THART/EI/Forms/AllItems.aspx?id=%2Fsites%2FTHART%2FEI%2F04%20%2D%20Electrical%5FInstrument%2F18%2DEI%20Pictures%20Database%2F1%5FAPP%2FA%2D4670%5FHypoChloride%2F20250305%5FHypo%5FA%2D4670%5FA%2DTrip&amp;viewid=415f9878%2Da53c%2D45fe%2D8639%2De524c6aa2067</p>', '2025-03-05 17:59:03', '2025-03-05 18:27:34', 'PTTEP\\Art-Tech-Prod-Maint', 'PTTEP\\Art-Tech-Prod-Maint', false, 'ART') RETURNING id INTO new_report_id;
