  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Neon', NULL, 'EXTERNAL', '2025-03-05 17:59:22', CURRENT_TIMESTAMP, 'PTTEP\\ZOC.Mech-Tec', NULL);
