  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'CHAN', NULL, 'EXTERNAL', '2025-03-06 11:02:58', CURRENT_TIMESTAMP, 'PTTEP\\ZOC.Mech-Tec', NULL);
