  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'AWP-33 Troubleshoot BC can not remote start', 'Mechanic', 'CM', 'Completed', '2025-03-06', '<p>Troubleshoot BC can not remote start</p><p>- Found due to BC stop " Comp Suction pressure LO LO during tranfer control mode</p><p>from Normal set point to Auto set point.</p><p><br></p><p>As found</p><p>- During tranfer mode Comp suction pressure LO LO occur becuase no relay timer during transfer.</p><p>As left&nbsp;</p><p>- Infromed EMI for request to additional timer for platform whitch Auto set point.</p><p>Who need to start must be activate MOS Comp suction Pressure LO LO after transfer to auto set point can be remove MOS.</p><p><br></p><p>**If need to start must be inform Mech for local start&nbsp;&nbsp;</p><p><br></p>', NULL, '2025-03-08 08:33:35', CURRENT_TIMESTAMP, 'PTTEP\\art.mechcrane', NULL, false, 'ART') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-WP33-3C-3361.PK', 'ART-WP33-3C-3361.PK', 'BOOSTER COMPRESSOR PACKAGE ART-WP33', NULL, NULL, 'BOOSTER COMPRESSOR PACKAGE ART-WP33', 'ART-WP33', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
