-- Inserting report ID 27285
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Daily EI Turbine activities_2025Mar09', 'Turbine E&I', 'OTH', 'Completed', '2025-03-09', '<p>Daily EI Turbine Status report: 2025-03-09</p><p>Turbo Package Walk-Around Inspection (This morning)</p><p>o&nbsp;&nbsp; All Turbocompressors operating normally. TG-1 is on Standby.</p><p>o&nbsp;&nbsp; The only active alarm is “OSM_Steet_Req” on UCP-2610</p><p><br></p><p>Visisted the Both Lube oil cooling fans of BM-1245, and BM-2240 (Only BM-1245 found significant strange vibration via hand touching. But not sevel or critical. Anyway do to MM activity concerned on the Fan belt and pulley. We aim to replace the motor bearing as the planned.</p><p>o&nbsp;&nbsp;&nbsp;BM-1245 (FGC#1) Lube oil cooler fan&nbsp;:should be replace motor bearing as MM reccomment</p><p>o&nbsp; &nbsp;BM-2240 ( FGC#2) Lube oil cooler fan: Did not sense any vibration or strange noise from the motor. So we should not do anything on this fan motor except support the MM activities.</p><p>------------------------------</p><p>Administrator activities</p><p>- Issued PR for H-4850 spare OR-108, and some parallel swagelok fitting (from PR1300948490- PR13000948499)</p><p>- Update dated WON status.&nbsp;</p><p>- Issued Reservation for Turbing Clamp under <a href="Reserv:985825">Reserv:985825</a>&nbsp;( for WHRU-4840, 4850)</p><p>- Follow up material under MM24E1201127 (Material Extension requested for 60.00.00.236.3 (Self-fusing silicone tape SCOTCH70)</p><p>---------------------------</p><p>Verified FGC Control logic, regarding the "MCC Auxiliaries healthy permissive" It would be affected if the BM-1245 was isolated for maintenance with motor bearing replacement or Mechanical task of the cooler fan of L.O. cooler.</p>', NULL, '2025-03-09 09:18:17', '2025-03-11 06:43:31', 'PTTEP\\Arthit.EI-Turbine', 'PTTEP\\Arthit.EI-Turbine', false, 'ART') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-BM-1245', 'ART-BM-1245', 'MOTOR,ELECTRICAL,LUBE OIL COOLER FAN', NULL, NULL, 'MOTOR,ELECTRICAL,LUBE OIL COOLER FAN', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-BM-2240', 'ART-BM-2240', 'MOTOR,ELECTRICAL,LUBE OIL COOLER FAN', NULL, NULL, 'MOTOR,ELECTRICAL,LUBE OIL COOLER FAN', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
