  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Cleaned the breather Housing Gas Generator,G-9110', 'Mechanic', 'PM', 'Completed', '2025-03-09', '<p><u>Today Activity</u></p><p><u><br></u></p><p>Cleaned the breather Housing Gas Generator, G-9110.</p><p><u><br></u></p><p><u>Working Steps</u></p><p><u><br></u></p><p>- Disconnected the breather down stream lines.</p><p>- Removed the breather housing&nbsp; parts.</p><p>- Cleaned the oil sludge.</p><p>- Replaced the breather. <span style="background-color: rgb(255, 255, 0);">(ONLY BANK "A")&nbsp;</span><br>- Replaced the breather O-Rings.<br>- Installed the breather housing parts.</p><p>- Connected the breather down stream lines.</p><p>- Checked the coolant level.<br>- Checked the radiator cap condition.</p><p>- Took lube oil sample about 300 ml.<br>- Checked the lube oil level.<br>- Topped Up lube oil (Methana - 49 Liters).<br>- Checked and cleaned the air filters.<br>- Housekeeping and test run by sharing load.<br>- Found no abnormality and transferred Full Load.</p><p><br></p><p><u>Required Tools</u></p><p><u><br></u></p><p>- Spanner Set (7mm,13mm, 17mm)</p><p>- Cotton Rag</p><p>- Flash Light</p><p><br></p><p><br></p>', 'Found more oil sludge on Bank "A" rather than Bank "B".<br><br>', '2025-03-10 18:24:11', '2025-03-10 18:35:58', 'PTTEP\\ZOC.Mech-Tec', 'PTTEP\\ZOC.Mech-Tec', false, 'ATL') RETURNING id INTO new_report_id;
