  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S mobile gen no.3 alarm charger alternator fail.', 'Electrical', 'CM', 'Completed', '2025-03-11', '<p>T/S mobile generator no.3 alarm charger alternator fail {Alarm event on HMI is "01/ChrgAlternFail" (Alternator no output voltage)}.</p><p>- Removed alternator to repair at W/S.</p><p>- Found the carbon brushes of alternator was defective to be replaced (no spare on hand) then replaced with the fabricated carbon brushes ( The fabricated carbon brushes shall be installed correctly for the alternator to work properly).</p><p>- Reinstalled alternator and alignmented belt by MM.</p><p>- Running tested mobile generator , found it work properly (Battery charging voltage = 13.21 VDC , Battery charging current = 6.4 A).&nbsp;&nbsp;</p><p><br></p><p>        </p><p>*** Spare part 3 items have been ordered (Details as attachments).</p>', NULL, '2025-03-11 14:49:38', '2025-03-12 08:28:38', 'PTTEP\\Art-Tech-Prod-Maint', 'PTTEP\\Art-Tech-Prod-Maint', false, 'ART') RETURNING id INTO new_report_id;
