  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Overhaul sewage macerator motor B.', 'Electrical', 'CM', 'Completed', '2025-03-11', '<p>Overhaul sewage macerator motor B due to strange noise.</p><p>- Found DE and NDE bearing defective, replaced by new spare bearing Model 6205-2RSH, 2 EA.</p><p>- Overhaul motor pending to touch up paint.</p><p>- Sent motor fan cowl to fabricate and touch up paint.</p><p>- Motor winding resistance 7.8/7.8/7.8 ohm, insulation &gt; 550 Mohm.</p>', '<p>- Please order spare ball bearing model&nbsp;<span style="font-size: 14px;">6205-2RSH, MESC: 58.01.08.405.1,&nbsp;&nbsp;4 EA.</span></p><p><span style="font-size: 15px;">- Please order spare ball bearing model&nbsp;</span>6205-2Z-C3, MESC:&nbsp;58.00.07.905.1,&nbsp;&nbsp;4 EA.<span style="font-size: 14px;"></span></p>', '2025-03-11 15:41:31', CURRENT_TIMESTAMP, 'PTTEP\\GBS.EI-Workshop', NULL, false, 'G2S') RETURNING id INTO new_report_id;
