-- Inserting report ID 27416
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'BM-1245 Replace Fan shaft bearing complete set', 'Turbine Mech', 'CM', 'In Progress', '2025-03-11', '<p>Cooler Fan shaft and bearing high velocity vibration as per Vibration report 30 Jan 2025.</p><p>- Replaced Fan shaft and bearing complete set.</p><p>- Replaced fan belt.</p><p>- Applied grease to both fan shaft bearings.</p><p>- Retighten fan blade nuts and bolts and all structure fitting bolts.</p><p><br></p><p>Night shift 11/02/2025<br>- Reinstalled motor, fan and motor sheeves.<br>- Fan sheeves and belt tension and alignment.<br>- Test run Lube oil cooler, normal.<br>- At 23:06 pm Start up FGC#1 and continue on load.</p><p><br></p>', '<p class="MsoListParagraphCxSpFirst" style="margin-left:18.25pt;mso-add-space:
auto;text-indent:-18.0pt;mso-list:l0 level1 lfo1"><!--[if !supportLists]--><span style="mso-ascii-font-family:Calibri;mso-fareast-font-family:Calibri;
