  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'PP-C-3610, Glycol contractor Level Instrument YPM', 'Instrument', 'PM', 'In Progress', '2025-03-11', '<p>C-3610, Glycol contractor Level Instrument YPM. 60% inprogress</p><p>Performed function-tested LSHH-3611 and LSLL-3612 as per procedure.</p><p>-On LT-3616 background reading spike high, today remove sensor probe to cleaning at W/S and inspection of condition probe, re-installed sensor probe and use the gasket (graphite type, not original)&nbsp;</p><p>-Performed filling water in the chamber at 50% but transmitter reading still high at 150% all time and then hard reset by disconnecting power supply of transmitter back to reading and checked transmitter reading span more time but reading still high alarm same last time.&nbsp;</p><p>-Replaced new transmitter by new and uploading configuration from the old transmitter.&nbsp;</p><p>-Config parameter damping from 20 sec to 4 sec, LRV from 0 mm to 17 mm. and URV from 400 mm. to 373 mm. function tested compare reading with CCR.</p><p><br></p>', '<span style="font-size: 14px;">LT-3616, , LSHH-3611, and LSLL-3612 are waiting for torque flange joints by the construction team.</span>', '2025-03-11 22:13:39', '2025-03-12 08:58:08', 'PTTEP\\Bongkot.Inst-Lead', 'PTTEP\\Bongkot.Inst-Lead', false, 'G2N') RETURNING id INTO new_report_id;
