-- Inserting report ID 27446
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Continue TroubleshootG-8920 unable to start day 6', 'Electrical & Instrument', 'CM', 'Under Monitoring', '2025-03-12', '<p><b><u>Today Activity</u></b></p><p>-Continue TroubleshootG-8920 unable to start day 6</p><p><b><u><br></u></b></p><p><b><u>Action</u></b></p><p>-Test run after mechanic team coolant pipe replacement.</p><p>-Test run with no load OK. but shut down with shared load.</p><p>-Adjust 12 KPa to 15 KPa of fuel gas PCV.</p><p>-Test run with free load 30 min (OK).</p><p>-Test run with shared load 30 min (OK).</p><p>-As of 12th march, G8920 is running with full load. (under monitoring)</p><p><b><u><br></u></b></p><p><b><u style="background-color: rgb(255, 255, 0);">History (05-03-2025)</u></b></p><p><b><u style="background-color: rgb(255, 255, 0);">Today activity</u></b></p><p><span style="background-color: rgb(255, 255, 0);">Continue troubleshoot G8920 unable to start day 5.</span></p><p><b><u style="background-color: rgb(255, 255, 0);"><br></u></b></p><p><b><u style="background-color: rgb(255, 255, 0);">Action</u></b></p><p><span style="background-color: rgb(255, 255, 0);">1) Replaced with new speed sensor (Magnetic pick up 2) and test run. (Sensor gap = half turn)</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp;- G8920 can run 5 min with shared load and shut down with alarms.(radiator fan fault, reverse power).</span></p><p><span style="background-color: rgb(255, 255, 0);">2) Checked the radiator fan condition and test run again. (Fan OK)</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp;- G8920 can run 15 min and coolant pipe was broken during test run.</span></p><p><span style="background-color: rgb(255, 255, 0);">3) E-Stopped G-8920 due to coolant water come out.</span></p><p><span style="background-color: rgb(255, 255, 0);">&nbsp; &nbsp;- Clean and housekeeping G-8920.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><b><u style="background-color: rgb(255, 255, 0);"><br></u></b></p><p><b><u style="background-color: rgb(255, 255, 0);">History (04-03-2025)</u></b></p><p><b><u style="background-color: rgb(255, 255, 0);">Today Activity</u></b></p><p><span style="background-color: rgb(255, 255, 0);">Continue TroubleshootG-8920 unable to start day 4</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><b><u style="background-color: rgb(255, 255, 0);">Action</u></b></p><p><span style="background-color: rgb(255, 255, 0);">1) Replace old timing sensor, perform test run, can''t start.</span></p><p><span style="background-color: rgb(255, 255, 0);">2) Swap magnetic pick up 1 from G8925, perform test run, can''t start.</span></p><p><span style="background-color: rgb(255, 255, 0);">3) Replace old magnetic pick up 2, perform test run , show under RPM alarm.</span></p><p><span style="background-color: rgb(255, 255, 0);">4) replace G8925''s pick up to it original position, perform G-8925 test run with load shared for readiness.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><b><u style="background-color: rgb(255, 255, 0);">History (02.03.2025)</u></b></p><p><b><u style="background-color: rgb(255, 255, 0);">Today Activity&nbsp;</u></b></p><p><span style="background-color: rgb(255, 255, 0);">Continue troubleshoot G8920 unable to start (Day3)</span></p><p><u><b style="background-color: rgb(255, 255, 0);"><br></b></u></p><p><u><b style="background-color: rgb(255, 255, 0);">Action</b></u></p><p><span style="background-color: rgb(255, 255, 0);">1) Adjust Magnetic pick up 1 and verify the sensor condition</span></p><p><span style="background-color: rgb(255, 255, 0);">- found that sensor top is dent</span></p><p><span style="background-color: rgb(255, 255, 0);">- check sensor condition with multimeter, (367.1 Ohm)</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><span style="background-color: rgb(255, 255, 0);">2) Adjust Magnetic pick up 2</span></p><p><span style="background-color: rgb(255, 255, 0);">Test run G8920, still can''t run.</span></p><p><b><u style="background-color: rgb(255, 255, 0);"><br></u></b></p><p><span style="background-color: rgb(255, 255, 0);"><u>History (27.02.2025)</u><b><u></u></b></span></p><p><b><u style="background-color: rgb(255, 255, 0);">Today Activity</u></b></p><p><span style="background-color: rgb(255, 255, 0);">Continue troubleshoot G8920 unable to start</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><b><u style="background-color: rgb(255, 255, 0);">Action</u></b></p><p><span style="background-color: rgb(255, 255, 0);">1) Replace new fuel gas filter at dog house.</span></p><p><span style="background-color: rgb(255, 255, 0);">2) Clean the fuel gas regulator filter.</span></p><p><span style="background-color: rgb(255, 255, 0);">3) Replace GIS relay base at control panel.</span></p><p><span style="background-color: rgb(255, 255, 0);">4) Adjust timing sensor position. (found under RPM alarm)</span></p><p><span style="background-color: rgb(255, 255, 0);">5)Test run G8920 with battery charger , G8920 can''t start (no alarm, stop at RPM 200 to 300).</span></p><p><b><u style="background-color: rgb(255, 255, 0);"><br></u></b></p><p><span style="background-color: rgb(255, 255, 0);"><u>History (27.02.2025)</u><b><u></u></b></span></p><p><b><u style="background-color: rgb(255, 255, 0);">Today Activity</u></b></p><p><span style="background-color: rgb(255, 255, 0);">TS G-8920 unable to start</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><u><b style="background-color: rgb(255, 255, 0);">Action</b></u></p><p><span style="background-color: rgb(255, 255, 0);">1) Adjust PCV 10 to 8 Kpa&nbsp;</span></p><p><span style="background-color: rgb(255, 255, 0);">2) Connect with DC desk software to AFR to monitor and save the RPM data.</span></p><p><span style="background-color: rgb(255, 255, 0);">3) Connect with Ignition control software to Ignition circuit to monitor and save data.</span></p><p><span style="background-color: rgb(255, 255, 0);">4) Test run G8920 with battery starter.</span></p><p><span style="background-color: rgb(255, 255, 0);">G8920 can''t start.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><u><b style="background-color: rgb(255, 255, 0);">Mechanic Action</b></u></p><p><span style="background-color: rgb(255, 255, 0);">1) Installed digital pressure gauge at downstream GCV to monitor.</span></p><p><span style="background-color: rgb(255, 255, 0);">2) Adjusted downstream PCV fuel gas pressure up to 8 Kpa.</span></p><p><span style="background-color: rgb(255, 255, 0);">3) Inspected breather cartridges in both bank-A and B.</span></p><p><span style="background-color: rgb(255, 255, 0);">4) Refitted ignition coil wire connection in both bank-A and B.</span></p><p><span style="background-color: rgb(255, 255, 0);">5) Inspected and cleaned air filters.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><b><u style="background-color: rgb(255, 255, 0);">History (26.02.2025)</u></b></p><p><b><u style="background-color: rgb(255, 255, 0);">Today Activity</u></b></p><p><span style="background-color: rgb(255, 255, 0);">G8920 battery charging &amp; speed sensor replacement</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><u><b style="background-color: rgb(255, 255, 0);">Action</b></u></p><p><span style="background-color: rgb(255, 255, 0);">Perform work permit and tool box talk.</span></p><p><span style="background-color: rgb(255, 255, 0);">Charge the battery bank1 at battery room.</span></p><p><span style="background-color: rgb(255, 255, 0);">Install back to test run after magnetic pick up installation done.</span></p><p><span style="background-color: rgb(255, 255, 0);">Replace with new over speed sensor (60.07.79.001.9).</span></p><p><span style="background-color: rgb(255, 255, 0);">Test run G8920 with battery charger.</span></p><p><span style="background-color: rgb(255, 255, 0);">Can''t start the engine. Stuck at starting state.</span></p><p><br></p>', NULL, '2025-03-12 15:09:50', '2025-03-12 15:12:09', 'PTTEP\\ZOC.Elec-Tec', 'PTTEP\\ZOC.Elec-Tec', false, 'ATL') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-G-8920', 'ATL-OC-G-8920', 'Gen, Generator ZOC Gas gen 1', NULL, NULL, 'Gen, Generator ZOC Gas gen 1', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Noble', NULL, 'EXTERNAL', '2025-03-12 15:09:50', '2025-03-12 15:12:09', 'PTTEP\\ZOC.Elec-Tec', 'PTTEP\\ZOC.Elec-Tec');
