-- Inserting report ID 27466
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Continue TS PCV-81202B Travelling status error', 'Electrical & Instrument', 'CM', 'In Progress', '2025-03-12', '<p><b><u>Today Activity</u></b></p><p>Continue TS PCV-81202B Travelling status error</p><p><br></p><p><b><u>Action</u></b></p><p>Disconnect the power cable from JB.</p><p>Connect with HART calibrator.</p><p>Calibrate PCV-81202B with auto calibration.&nbsp;</p><p>Function test with CCR and monitor 4to 20 mA with Fluke meter.</p><p>CCR commend work properly due to get mA signal from JB through mA meter.(16mA ~10% open, 20mA ~ 25% open)</p><p>In Progress.</p><p>&nbsp;</p><p><b><u style="background-color: rgb(255, 255, 0);">History (11-03-2025)</u></b></p><p><b><u style="background-color: rgb(255, 255, 0);">Today Activity</u></b></p><p><span style="background-color: rgb(255, 255, 0);">TS PCV-81202B Travelling status error</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><u><b style="background-color: rgb(255, 255, 0);">Action</b></u></p><p><span style="background-color: rgb(255, 255, 0);">Check and verify the cable connection.</span></p><p><span style="background-color: rgb(255, 255, 0);">Found one cable is loosen (- cable)</span></p><p><span style="background-color: rgb(255, 255, 0);">Connect back to termination.</span></p><p><span style="background-color: rgb(255, 255, 0);">Function test with CCR&nbsp;</span></p><p><span style="background-color: rgb(255, 255, 0);">Found that positioner is not comply with CCR commend.(100%commend - 10% open)</span></p><p><span style="background-color: rgb(255, 255, 0);">Isolate knife switch.</span></p><p><span style="background-color: rgb(255, 255, 0);">Communicate with HART and inject output supply through HART.</span></p><p><span style="background-color: rgb(255, 255, 0);">Function test 100% commend- 14% open valve.</span></p><p><span style="background-color: rgb(255, 255, 0);">To be continue tomorrow.</span></p><p><br></p><p><br></p><p><br></p>', NULL, '2025-03-12 18:17:02', '2025-03-12 18:21:51', 'PTTEP\\ZOC.Elec-Tec', 'PTTEP\\ZOC.Elec-Tec', false, 'ATL') RETURNING id INTO new_report_id;
