  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'G2N-MOD-21026: Pressure Drop in the Dry Gas Seal.', 'Electrical', 'CM', 'In Progress', '2025-03-14', '<p>G2N-MOD-21026: Pressure Drop in the Dry Gas Seal System Improvement for TEK-3200</p><p><u>Measurement insulation and resistance of heater.</u></p>  <p>&nbsp;Insulation </p>  <p>L1-E = 100 Mohm, L2-E = 100 Mohm, L3-E = 100 Mohm.</p>  <p>Resistance</p>  <p>L1-L2 = 20.3 Ohm, L2-L3 = 20.4 Ohm, L1-L3 = 20.2 Ohm.</p><p><u><br></u></p><p><u>Function alarm tested (Stop heater).</u></p><p>- ESD safety result (KA1) = Pass.</p><p>- Control panel safety (Set point 45°C) (KA2) result = Pass.</p><p>- Earth leakage (Set point 300mA, T= 1 Sec) (KA3) result = Pass.</p><p>- Heating element Hi/Hi temperature (KA4) (Set point 120 °C(10.42 mA)), (Reset 118°C(10.27 mA) result = Pass.&nbsp; &nbsp; &nbsp;</p><p>            </p><p>- Gas Hi/Hi temperature ( KA6) (Set point 80 °C(8.31mA)) , (Reset 78°C(8.18 mA) result = Pass. &nbsp;</p><p>- Emergency&nbsp;result = Pass.&nbsp;</p><p><u>Malfunction equipment.</u>&nbsp;&nbsp;</p><p>- Vessel Hi/Hi temperature (KA5) (Set point 120 °C) (Simulate 10 mA = 113 °C Tripped) result = Not pass&nbsp;</p><p>&nbsp;</p><p><u >Function test QV1 (Thyristor unit)</u></p><p>- Temp set point = 70 °C voltage output trigger = 280-380 VAC </p><p>- Outlet gas LOW temperature alarm set point = 60 °C output trigger = 280-380 VAC</p><p>      </p><p>- Outlet gas HI temperature alarm set point = 77 °C output trigger = 280 VAC</p><p><br></p>', '<a href="https://pttep.sharepoint.com/:f:/r/sites/THG2N/DL_Selective_Access/02-PBN-M/02%20MEI/19%20Photos/00%20Electrical%20Photos/PP/TEK%203200/Verify%20heater%20and%20control%20panel%20E3270%20dry%20gas%20seal%20unit%20on%2014-3-2025?csf=1&amp;web=1&amp;e=v8KXOw">Verify heater and control panel