  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'PM 2X-2673 PEDESTAL CRANE PULL TEST', 'Mechanic', 'PM', 'Completed', '2025-03-14', '<div>Perform Pull test 100% capacity by beam clamp.&nbsp;</div><div>&nbsp; &nbsp;- Main hoist setup beam clamp with dynamometer at boom angle 66.1 degree and boom&nbsp;</div><div>&nbsp; &nbsp; &nbsp;radius 9.0 M.&nbsp;</div><div>&nbsp; &nbsp;- Main hoist pull load, dynamometer reading 15.16 tons, crane display indicator reading&nbsp;</div><div>&nbsp; &nbsp; &nbsp;15.1 tons.&nbsp;</div><div>&nbsp; &nbsp;- Performed re-calibration main load indicator.&nbsp;</div><div>&nbsp; &nbsp;- Checked main hoist slippage, shut down engine mark main hoist and hold load for 5&nbsp;</div><div>&nbsp; &nbsp; &nbsp;minutes (not slippage)&nbsp;</div><div>&nbsp; &nbsp;- Fly hoist setup beam clamp with dynamometer at position boom angle 69.0 degree and&nbsp;</div><div>&nbsp; &nbsp; &nbsp;boom radius 9.1 M.&nbsp;</div><div>&nbsp; &nbsp;- Fly hoist pull load, dynamometer reading 3.54 tons, crane display indicator reading 3.5&nbsp;</div><div>&nbsp; &nbsp; &nbsp;tons.&nbsp;</div><div>&nbsp; &nbsp;- Performed re-calibration fly load indicator.&nbsp;</div><div>&nbsp; &nbsp;- Checked fly hoist slippage, shut down engine mark main hoist and hold load for 5&nbsp;</div><div>&nbsp; &nbsp; &nbsp;minutes (not slippage)&nbsp;</div><div>&nbsp; &nbsp;- Inspected main and fly wire rope to check any damage found good condition&nbsp;</div><div>&nbsp; &nbsp;- Performed inspection crane after pull test found crane normal condition.&nbsp;</div><div>&nbsp; &nbsp;- Housekeeping and cleaned up working area.</div>', NULL, '2025-03-16 09:40:04', '2025-03-16 09:49:55', 'PTTEP\\GBS.Mechanic-WorkS', 'PTTEP\\GBS.Mechanic-WorkS', false, 'G2S') RETURNING id INTO new_report_id;
