  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Verify UCV-1550 and function tested.', 'Instrument', 'CM', 'Completed', '2025-03-16', '<ul type="disc">  <li>Function test control      loop and monitor action of UCV-1550.By requested CRO share load for J-T      valve and Turbo-Ex (50/50) . Tried adjusting set point (SP=94) to more      than the as found process variable (PV=92). Confirming the valve responded      correctly. This demonstrates the valve’s ability to react to changes in SP      and maintain control.</li>  <li>Performed PID tuning      used parameters from 2021 (SP=85, PG=0.6, TI=5.0) were applied. Requested      CRO slowly close J-T valve. Then monitor control response of the antisurge      valve. The PV decreased correspondingly with an increase in valve      position, ultimately reaching the setpoint (PV=SV). This indicates proper      PID control, as the valve effectively compensated for the changing      conditions created by closing the J-T valve.</li> </ul>', NULL, '2025-03-16 16:34:27', CURRENT_TIMESTAMP, 'PTTEP\\Art-Tech-Prod-Maint', NULL, false, 'ART') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-A-1550-ANTV', 'ART-A-1550-ANTV', 'COMPRESSOR ANTI-SURGE VALVE', NULL, NULL, 'COMPRESSOR ANTI-SURGE VALVE', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Piriyut K.', NULL, 'EXTERNAL', '2025-03-16 16:34:27', CURRENT_TIMESTAMP, 'PTTEP\\Art-Tech-Prod-Maint', NULL);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Saralrat K.', NULL, 'EXTERNAL', '2025-03-16 16:34:27', CURRENT_TIMESTAMP, 'PTTEP\\Art-Tech-Prod-Maint', NULL);
