  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'PM EL Battery and Solar system 1Y', 'Electrical', 'PM', 'Completed', '2025-03-05', '<div>"Perform maintenance and inspection as follow;</div><div>Battery</div><div>&nbsp;1. Check all around the battery box for any sign of damage.&nbsp;</div><div>&nbsp;2. Visually inspect battery each cell for external condition.</div><div>&nbsp;3. Verify tightness of battery main cable and cross bars.</div><div>&nbsp;4. Clean up and apply grease on the battery poles to prevent corrosion.&nbsp;</div><div>&nbsp;5. Measure and record data each batteries cell (see below recording)</div><div>&nbsp; &nbsp;- BAT-17-440 output = 28.73 Vdc. / 12.37 Amps.</div><div>Solar Array</div><div>1. Check all around the Solar array for any sign of damage.&nbsp;</div><div>&nbsp;2. Verify tightness of all electrical connections and power cables condition.</div><div>&nbsp;3. Junction boxes inspection and tightening check inside connection</div><div>&nbsp;4. Gently clean solar array by soft cloth as much as possible.</div><div>&nbsp;5. Measure and record output data each panel (see below recording)</div><div>&nbsp; &nbsp;- SP-17-440A output = 34.82 Vdc. / 5.42 Amps.</div><div>&nbsp; &nbsp;- SP-17-440B output = 34.84 Vdc. / 6.15 Amps.</div><div>&nbsp; &nbsp;- SP-17-440C output = 34.86 Vdc. / 6.08 Amps.</div><div>&nbsp; &nbsp;- SP-17-440D output = 34.85 Vdc. / 5.79 Amps."</div><div><br></div>', NULL, '2025-03-17 09:00:32', CURRENT_TIMESTAMP, 'PTTEP\\AthiwatK', NULL, false, 'ART') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-WP17-ELE-PWD-DC', 'ART-WP17-ELE-PWD-DC', 'POWER DISTRIBUTION (DC)', NULL, NULL, 'POWER DISTRIBUTION (DC)', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
