  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'PM IN Thermo Electric Generator Package 1Y', 'Instrument', 'PM', 'Completed', '2025-03-05', '<div>"Perform maintenance and inspection as follow;</div><div>&nbsp;1. General visual inspection all around the skid for damage.</div><div>&nbsp;2. All junction box inspection and re-tighten all wiring connections.</div><div>&nbsp;3. Control panel condition checked and cleaning.</div><div>&nbsp;4. Main inlet fuel gas filter changed out.</div><div>&nbsp;5. Replaced all exhaust arrestors.</div><div>&nbsp;6. Replaced all inlet arrestors.</div><div>&nbsp;7. Restart and fine tune output by adjust fuel gas pressure and air ratio.</div><div>&nbsp; &nbsp;- All TEG output = 28.96 Vdc. / 2.30 Amps.</div><div>&nbsp;8. Performance testing with data recording."</div><div><br></div>', '<div>"Replaced parts as follow.</div><div>&nbsp;- G1791A replaced Spark rod connector + Exshaust rain shield.</div><div>&nbsp;- G1791B replaced Ignition board (Low performance, FG=80 Kpa @ 6.0 VDC). Issued Noti#100658800 to ART-MEI</div><div>&nbsp;- G-1791C replaced Spark rod connector + Control ignition board + Ignition board + Ignition battery.</div><div>&nbsp;- G-1791D replaced Spark rod connector + Spark rod.</div><div>&nbsp;- G1791E replaced Spark rod connector."</div>', '2025-03-17 09:01:43', CURRENT_TIMESTAMP, 'PTTEP\\AthiwatK', NULL, false, 'ART') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-G-1791', 'ART-G-1791', 'THERMO ELECTRIC GENERATOR PACKAGE', NULL, NULL, 'THERMO ELECTRIC GENERATOR PACKAGE', 'ART-WP17', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
