  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-WP20-UTL-ELEC-PWDIST-ASSY', 'ART-WP20-UTL-ELEC-PWDIST-ASSY', 'POWER DISTRIBUTION ASSEMBLY', NULL, NULL, 'POWER DISTRIBUTION ASSEMBLY', 'ART-WP20', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
