  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'PM ME Closed Drain Sump Pump Unit 1Y', 'Mechanic', 'PM', 'Completed', '2025-03-12', '<div>"Copntinue maintenance and inspection as follow;</div><div>&nbsp;1. Checked and changed filter utility gas for pump driven.&nbsp;</div><div>&nbsp;2. Inspect suction strainer and cleaning (30% clogged by sludge).</div><div>&nbsp;3. Check oil mist level and filled up lube oil.</div><div>&nbsp;4. Inspect foundation for corrosion, looseness, crack, breaking, etc.</div><div>&nbsp;5. Suction &amp; discharger pulsation dampers check and normal found.</div><div>&nbsp;6. Unit function test run and data recording."</div><div><br></div>', '<div>As found pump cannot running. Applied many lubricant into spool valve and then function test again. Pump can working as normal.</div><div><br></div>', '2025-03-17 10:21:52', CURRENT_TIMESTAMP, 'PTTEP\\AthiwatK', NULL, false, 'ART') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-P-0352', 'ART-P-0352', 'CLOSED DRAIN SUMP PUMP', NULL, NULL, 'CLOSED DRAIN SUMP PUMP', 'ART-WP03', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
