-- Inserting report ID 27820
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'PM EL Battery Discharge test (BAT-QP-330B) 2Y', 'Electrical', 'PM', 'Completed', '2025-03-14', '<div>"Perform maintenance and discharge test on BAT-QP-330B1/B2</div><div>&nbsp;1. Re-Tighten terminal and connection wiring.</div><div>&nbsp;2. Check voltage of battery.</div><div>&nbsp;3. Check current of battery.</div><div>&nbsp;4. Discharge test battery.</div><div>BAT-QP-330B1</div><div>&nbsp;1. Battery voltage before discharge = 200.7 Volt.</div><div>&nbsp;2. Battery total current discharge test = 200 AH.</div><div>&nbsp;3. Battery voltage after discharge = 185.4 Volt.</div><div>&nbsp; &nbsp;- The discharge test was aborted by manual at&nbsp; min 150/210 min. Due to voltage dropped lower than 1.60 volt = 1 cell (cell# 71).</div><div>&nbsp; &nbsp;- As found low performance 9/90 cells voltage drop lower than 1.80 volt (by calculation formula table @ 300 mins). There are cell#10, 41, 50, 51, 67, 71, 79, 85 and 87.</div><div>BAT-QP-330B2</div><div>&nbsp;1. Battery voltage before discharge = 198.7 Volt.</div><div>&nbsp;2. Battery total current discharge test = 280 AH.</div><div>&nbsp;3. Battery voltage after discharge = 181.7 Volt.</div><div>&nbsp; &nbsp;- Auto stop by full time discharge test at 210 minutes.</div><div>&nbsp; &nbsp;- As found low performance 11/90 cells voltage drop lower than 1.80 volt (by calculation formula table @ 300 mins). There are cell#94, 103, 111, 124, 128,&nbsp; 137, 139, 153, 156, 165 and 166.</div><div>&nbsp;4. De-isolate charger and measure data as follow.</div><div>&nbsp; &nbsp;- Battery boost charging current after discharge = 37.5 Amps.</div><div>&nbsp; &nbsp;- Battery boost charging voltage after discharge = 387.2 Volts."</div><div><br></div>', NULL, '2025-03-17 11:04:10', CURRENT_TIMESTAMP, 'PTTEP\\AthiwatK', NULL, false, 'ART') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-QP-UTL-ELEC', 'ART-QP-UTL-ELEC', 'AQP POWER DISTRIBUTION SYSTEM', NULL, NULL, 'AQP POWER DISTRIBUTION SYSTEM', 'ART-QP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'CONCOR', NULL, 'EXTERNAL', '2025-03-17 11:04:10', CURRENT_TIMESTAMP, 'PTTEP\\AthiwatK', NULL);
