  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-PP-GASDET.ASY', 'ART-PP-GASDET.ASY', 'APP FIRE GAS DETECTOR ASSEMBLY', NULL, NULL, 'APP FIRE GAS DETECTOR ASSEMBLY', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
