-- Inserting report ID 27844
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'PM ME Produced Water Injection Pump B 6M', 'Mechanic', 'PM', 'Completed', '2025-03-16', '<div>"Perform maintenance and inspection as follow.</div><div>&nbsp;1. Check foundation holding down bolts and tightening check.</div><div>&nbsp;2. Check for any leaks from gaskets and seals around the pump skid.</div><div>&nbsp;3. Change lubes oil on bearing gearbox and sight glass indicator.(3.60 Liters.)</div><div>&nbsp;4. Check barrier fluid on mechanical seal for leak.</div><div>&nbsp;5. Check mechanical seal holding bolts and tightening.</div><div>&nbsp;6. Visual checked mechanical seal for leak.</div><div>&nbsp;7. Check coupling guard condition.</div><div>&nbsp;8. Check coupling membrane condition for crack, broken, deterioration.</div><div>&nbsp;9. Alignment check and record value for reference.</div><div>&nbsp;10. Coupling bolts check with proper torque applying.</div><div><br></div><div>Seal pot system:</div><div>&nbsp;1. Open the tank cover and clean internal tank.</div><div>&nbsp;2. Visual inspection internal tank for any abnormal and corrosion.</div><div>&nbsp;3. Inspect and cleaning suction and discharge filter.</div><div>&nbsp;4. Test run and data recording.</div><div>&nbsp; &nbsp; - Running hour = 70,912 Hrs.</div><div>&nbsp; &nbsp; - Running current = 57.6 Amps.</div><div>&nbsp; &nbsp; - Suction pressure PT-01606 = 3.337 BAR</div><div>&nbsp; &nbsp; - Discharge pressure PT-01608 = 118.22 BAR</div><div>&nbsp; &nbsp; - Pressure diff across strainer PDT-01605 = 0.104 BARD.</div><div>&nbsp; &nbsp; - Discharge flow FT-01602A = 68.48 in H2O&nbsp;</div><div>&nbsp; &nbsp; - Discharge flow FT-01602B = 68.47 in H2O&nbsp;</div><div>&nbsp; &nbsp; - Water seal pressure DE side PT-01615A = 7.61 BAR</div><div>&nbsp; &nbsp; - Water seal pressure NDE side PT-01615B = 6.96 BAR</div><div>&nbsp; &nbsp; - Water tank level = 97.4%"</div><div><br></div>', NULL, '2025-03-17 11:31:59', CURRENT_TIMESTAMP, 'PTTEP\\AthiwatK', NULL, false, 'ART') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-P-0161B', 'ART-P-0161B', 'PRODUCED WATER INJECTION PUMP B', NULL, NULL, 'PRODUCED WATER INJECTION PUMP B', 'ART-WP01', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'CONCOR', NULL, 'EXTERNAL', '2025-03-17 11:31:59', CURRENT_TIMESTAMP, 'PTTEP\\AthiwatK', NULL);
