-- Inserting report ID 27846
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'CM 2TG-5520 Fix lube oil leak and BSI', 'Mechanic', 'CM', 'Completed', '2025-03-17', '<p><b>Back ground</b></p><p>After verify leak on 11 Mar 2025, can not found root cause lube oil leak.</p><p>- Open package to check leak during engine 100% no load.</p><p>- Not found root cause of leakage.</p><p>unit to be continue run as schedule. (Time limited)</p><p>Closely monitor leak at enclosure exhaust flapper and lube oil level.</p><p>Still found oil drop from enclosure exhaust flapper and lube oil level slightly continue decrease.</p><p>&nbsp;</p><p><b>On 17 Mar 2025.</b></p><p>Perform 2TG-5520 Turbo Generator 2 perform fix lube oil leak at RGB.</p><p><b>Remedy:</b></p><p>Remove conduit connection of gas turbine vibration and speed sensor from RGB.</p><p>- Found 90 elbow fitting of conduit pipe of SE-1011 was crack. (Speed sensor conduit)</p><p>-<span style="background-color: rgb(255, 255, 0);">&nbsp;The crack is located on the back of the joint and cannot be clearly seen.</span></p><p>- Replace new 90 elbow fitting.</p><p>- Fix leak at conduit nipple of SE-1011 and junction box JB32&nbsp;</p><p>&nbsp; &nbsp;- Remove nipple to clean and recondition thread.</p><p>&nbsp; &nbsp;- Apply Lotite 567 thread sealant.</p><p>- Perform BSI at RGB gear found normal condition. @ R/H:2920 hrs.</p><p>&nbsp; &nbsp;- Normal condition.</p><p></p>', NULL, '2025-03-17 14:27:54', '2025-04-27 15:44:57', 'PTTEP\\KittipongSam', 'PTTEP\\GBS.Turbine-Mech', false, 'G2S') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-2TG-5520', 'GBS-2TG-5520', 'GAS TURBINE GENERATOR SOLAR TAURUS 70', NULL, NULL, 'GAS TURBINE GENERATOR SOLAR TAURUS 70', 'GBS-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
