  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S LIC-1570(DCS) & LIC-1571(SIS) show discrepancy', 'Instrument', 'CM', 'In Progress', '2025-03-18', '<div>T/S LIC-1570(DCS) &amp; LIC-1571(SIS) show discrepancy alarm</div><div>- Normally when LIC-1570 &amp; LIT-1571 different +- 10% will generate discrepancy alarm on DCS system.</div><div>- After verify, LIC-1570 reading 36% and LIT-1571 reading 31%, they''re both still normal and no any alarm occurred on level transmitters.</div><div>- But sometime both level swing and got discrepancy alarm due to the process condition and after that 1-3 second it will return to normal by itself, it should be add delay time on DCS system to avoid spurious alarm.</div><div>- Temporary change damping time from 4 second to 6 second for LIT-1571(SIS).</div><div>- Temporary increase Process value filter 5 second (from 10 to 15) for LIC-1570(DCS).&nbsp; &nbsp;&nbsp;</div><div>- Keep monitoring.&nbsp;</div>', NULL, '2025-03-18 16:42:19', '2025-03-19 13:16:38', 'PTTEP\\Art-Tech-Prod-Maint', 'PTTEP\\PaitoonW', false, 'ART') RETURNING id INTO new_report_id;
