-- Inserting report ID 27940
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'WP-01 : Support G2N-MOD-21011', 'Electrical', 'MD', 'Under Monitoring', '2025-03-19', '<p>WP-01 : Support G2N-MOD-21011 Upgrade Water Injection System</p><p>- Unit startup for performance test, The details as below.</p><p>- 07:30 Meeting all party concern @CCR.</p><p>- Document review before S/U.</p><p>- Electrical De-isolation (LOTO Clearance) @PP Switchgear Room.</p><p>- 08:30 Onsite preparation to startup. @WP-01 and PP Switchgear Room.</p><p>- 08:45 P-5070B Booster Pump Running.</p><p>- 09:00 P-5080B Unit startup <span style="background-color: rgb(0, 255, 0);">Step 0_Starting Motor (154 m3/h)</span></p><p>- 09:33&nbsp;<span style="background-color: rgb(0, 255, 0);">Step 1_Rated Flow (170 m3/h)</span></p><p>- 09:53&nbsp;<span style="background-color: rgb(0, 255, 0);">Step 2_End of Preferred Operating Range (176 m3/h)</span></p><p>- 10:10&nbsp;<span style="background-color: rgb(0, 255, 0);">Step 3_Maximum Allowable Operating Flow (187 m3/h)</span></p><p>- 10:28 <span style="background-color: rgb(0, 255, 0);">Step 4_Between 95 and 99% (163 m3/h)</span></p><p>- 10:47&nbsp;<span style="background-color: rgb(0, 255, 0);">Step 5_Min of Preferred Operating Range (117 m3/h)</span></p><p>- 11:11&nbsp;<span style="background-color: rgb(0, 255, 0);">Step 6_Minimum Stable Flow (62 m3/h)</span></p><p><span style="background-color: rgb(255, 255, 0);">"Endurance Test 72 Hrs. Running"</span></p><p>- 11:30 Start counter 4 Hrs. Mechanical Run Test (170 m3/h)</p><p>- 15:30 Completed for 4 Hrs. Mechanical Run Test (170 m3/h)</p><p>Note; Record all parameter and all values measurement every 0.5 Hrs.</p><p>- 18:00 Start counter 68 Hrs. Mechanical Run Test&nbsp;</p><p>- <span style="background-color: rgb(255, 0, 0);">18:05 Unit tripped from external trip (Vibration high_VT-5083B top vibration NDE)</span></p><p>- 18:21 Restart P-5080B and Resume to Endurance Test 72 Hrs. Running</p><p>Note; Record all parameter and all values measurement every 6 Hrs.</p>', '<a href="https://pttep.sharepoint.com/sites/THG2N/DL_Selective_Access/Forms/AllItems.aspx?newTargetListUrl=%2Fsites%2FTHG2N%2FDL%5FSelective%5FAccess&amp;viewpath=%2Fsites%2FTHG2N%2FDL%5FSelective%5FAccess%2FForms%2FAllItems%2Easpx&amp;id=%2Fsites%2FTHG2N%2FDL%5FSelective%5FAccess%2F02%2DPBN%2DM%2F02%20MEI%2F17%20Deviation%20MOC%2F2025%2FG2N%2DMOD%2D21011%20water%20injection%20pump%20upgrade%2F2025%2D03%2D19%20P%2D5080B%20Endurance%20Test%2072%20Hrs&amp;viewid=dce8e204%2D2273%2D4c5e%2Da20c%2Dcbf12e9b5007">BONGKOT NORTH (G2N) - 2025-03-19 P-5080B Endurance Test 72 Hrs - All Documents</a>', '2025-03-19 15:18:15', '2025-03-19 18:34:43', 'PTTEP\\Bongkot.Elec-Lead', 'PTTEP\\Bongkot.Elec-Lead', false, 'G2N') RETURNING id INTO new_report_id;
