  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S Combination Oven malfunction.', 'Electrical', 'CM', 'In Progress', '2025-03-20', '<p><b>Troubleshooting Combination Oven Malfunctions</b></p><p><b>Combination Oven 1:</b></p><p>- Insulation testing revealed that the heater had low insulation (&lt;1MOhm).</p><p>- Verification was done by disconnecting the heater''s power cable. Upon starting the combi oven, it&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;&nbsp;operated normally, and the MCB did not trip.</p><p>- The heater needs to be replaced with a new one.</p><p><b>Combination Oven 4:</b></p><p>- Wired the new heater power cable.</p><p>- Started the combi oven, but alarm Ept3 (meat probe in open circuit) was displayed.</p><p>- Replaced the meat probe and main board, then set the default programming parameters.</p><p>- Restarted the combi oven, but alarm Ept3 still appeared.The combi oven is operational, but it cannot track &nbsp;&nbsp;&nbsp;the cooking time to completion.</p><p>- Further troubleshooting is required.</p>', NULL, '2025-03-20 17:40:30', '2025-03-20 17:41:59', 'PTTEP\\Art-Tech-Prod-Maint', 'PTTEP\\Art-Tech-Prod-Maint', false, 'ART') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-74AG114', 'ART-74AG114', 'COMBINATION OVEN 1', NULL, NULL, 'COMBINATION OVEN 1', 'ART-QP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Saralrat K.', NULL, 'EXTERNAL', '2025-03-20 17:40:30', '2025-03-20 17:41:59', 'PTTEP\\Art-Tech-Prod-Maint', 'PTTEP\\Art-Tech-Prod-Maint');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Worapong A.', NULL, 'EXTERNAL', '2025-03-20 17:40:30', '2025-03-20 17:41:59', 'PTTEP\\Art-Tech-Prod-Maint', 'PTTEP\\Art-Tech-Prod-Maint');
