  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'PM 2P-5030B : To perform 12 MPM', 'Mechanic', 'PM', 'Completed', '2025-03-20', '<table border="0" cellspacing="0" cellpadding="0" width="702"><tbody><tr><td width="139" valign="bottom"><p align="left">Produced Water Re-injection Pump</p></td><td width="113" valign="bottom"><p align="left">Ref. Platform:</p></td><td width="102" colspan="3" valign="bottom"><p align="left">PPS</p></td><td width="56" valign="bottom"><p align="left">AREA:</p></td><td width="89" colspan="3" valign="bottom"><p align="left">Lower deck</p></td></tr><tr><td width="67" valign="bottom"><p align="left">Tag No.:</p></td><td width="276" colspan="3" valign="bottom"><p align="left">2P-5030 B</p></td><td width="113" valign="bottom"><p align="left">WON:</p></td><td width="222" colspan="5" valign="bottom"><p align="left">&nbsp;</p></td><td width="24" colspan="2"><p>&nbsp;</p></td></tr><tr><td width="67" valign="bottom"><p align="left"><br></p></td><td width="276" colspan="3" valign="bottom"></td><td width="141" colspan="3" valign="bottom"></td><td width="206" colspan="4" valign="bottom"></td><td width="12"><p>&nbsp;</p></td></tr><tr><td width="67" valign="bottom"><p align="left">Date:</p></td><td width="276" colspan="3" valign="bottom"><p align="left">20 March 2025</p></td><td width="129" colspan="2" valign="bottom"><p align="left">Running hour:</p></td><td width="206" colspan="4" valign="bottom"><p align="left">&nbsp; &nbsp;Hrs.</p></td><td width="24" colspan="2"><p>&nbsp;</p></td></tr><tr height="0"><td width="67"></td><td width="55"></td><td width="82"></td><td width="139"></td><td width="113"></td><td width="16"></td><td width="12"></td><td width="74"></td><td width="56"></td><td width="65"></td><td width="12"></td><td width="12"></td></tr></tbody></table><p align="left">1.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<u>Suction Strainer</u></p><p align="left">Cleaning strainer.&nbsp;(68% blocked)</p><p align="left">Visual strainer condition.</p><p align="left">Clean sealing surface on RTJ groove.</p><p align="left">Replace RTJ gasket R45D.</p><p align="left">Torque value: 597 ft-lb (809Nm)</p><p align="left">2.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<u>Min flow check valve</u></p><p align="left">Cleaning.</p><p align="left">Visual check sealing surface on body and disc.<u></u></p><p align="left">Visual check mechanism.</p><p align="left">Replace new flapper spring.<u></u></p><p align="left">Clean sealing surface on RTJ groove.</p><p align="left">Replace RTJ R37D gasket.</p><p align="left">Ensure flow direction is correctly.</p><p align="left">Torque value: 597 ft-lb (809Nm)</p><p align="left">3.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<u>Discharge check valve</u></p><p align="left">Cleaning<u></u></p><p align="left">Visual check sealing surface on body and disc.</p><p align="left">Visual check mechanism. (good condition)</p><p align="left">Clean sealing surface on RTJ groove.</p><p align="left">Replace RTJ R45D gasket.</p><p align="left">Ensure flow direction is correctly.</p><p align="left"></p><p align="left">Torque value: 597 ft-lb (809Nm)</p><p align="left">4.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<u>Lube oil bearing</u></p><p align="left">Lubrication: PTT Hydraulic 46</p><p align="left">Drain, flushing and check condition</p><p align="left">Replace bronze gasket (if necessary)</p><p align="left">DE Capacity: 0.82 liter</p><p align="left"></p><p align="left">NDE Capacity: 0.77 liter</p><p align="left">5.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<u>Mechanical Seal</u></p><p align="left">Retighten mounting bolt.</p><p align="left"></p><p align="left">No liquid seep or leaking.</p><p align="left">6.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<u>Barrier fluid system</u></p><p align="left">Check N2 Pre-charge pressure:</p><p align="left">DE= 7.0 Bars.</p><p align="left">NDE=7.0 Bars.</p><p align="left">Spec: 7.2 Bar.</p><p align="left">Check pressure/temperature gauge condition.</p><p align="left"></p><p align="left">Check any leakage at flange joint/fin tube.</p><p align="left">7.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<u>Coupling</u></p><p align="left">Retighten bolt.</p><p align="left">Check condition of membrane element.</p><p align="left"></p><p align="left">Remove rust and preserve.</p><p align="left">8.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<u>Alignment</u></p><p align="left"></p><p align="left">Recheck alignment.</p><p align="left">Alignment value is in acceptable. No need to realignment.</p><p align="left">9.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<u>Cleaning and Preserve package</u></p><p align="left">Remove corroded and rusty on structure and bolt nut.</p><p align="left">Preserve with grease/soft seal/Zing It</p><p align="left"></p><p align="left">Cleaning with Oiler-1</p><p align="left"><u></u></p><div align="center"><table border="1" cellspacing="0" cellpadding="0" width="673"><tbody><tr><td width="673" colspan="2" valign="top"><p align="center"><u>Test Run</u></p><div align="center"><table border="0" cellspacing="0" cellpadding="0" width="564"><tbody><tr><td width="226" colspan="2"><p align="center">Description</p></td><td width="91"><p align="center">Tag No.</p></td><td width="100" nowrap=""><p align="center">Acceptance</p></td><td width="57" nowrap=""><p align="center">Unit</p></td><td width="90" nowrap=""><p align="center">Reading</p></td></tr><tr><td width="34" nowrap="" rowspan="3"><p align="center"><br></p></td><td width="192" nowrap=""><p align="left">Suction Pressure.</p></td><td width="91" nowrap=""><p>2PI-50408</p></td><td width="100" nowrap=""></td><td width="57" nowrap=""><p align="center">Bars</p></td><td width="90" nowrap=""><p align="center">4.2</p></td></tr><tr><td width="192" nowrap=""><p align="left">Discharge Pressure.</p></td><td width="91" nowrap=""><p>2PI-50400</p></td><td width="100" nowrap=""></td><td width="57" nowrap=""><p align="center">Bars</p></td><td width="90" nowrap=""><p align="center">98.9</p></td></tr><tr><td width="192" nowrap=""><p align="left">Flow rate&nbsp; 60.6 m3/h.</p><p align="left">Balancing line press:&nbsp; 7.27 bar.</p></td><td width="91" nowrap=""><p>&nbsp;</p></td><td width="100" nowrap=""><p align="center">&nbsp;</p></td><td width="57" nowrap=""><p align="center"><br></p></td><td width="90" nowrap=""></td></tr><tr><td width="34" nowrap="" rowspan="4"><p align="center"><br></p></td><td width="192" nowrap=""><p align="left">DE</p><p align="left">Lube oil Level.</p></td><td width="91" nowrap=""><p>&nbsp;</p></td><td width="100" nowrap=""><p align="center">@ Half</p></td><td width="57" nowrap=""></td><td width="90" nowrap=""><p align="center">OK</p></td></tr><tr><td width="192" nowrap=""><p align="left">Fluid barrier pressure</p></td><td width="91" nowrap=""><p>2PI-50351</p></td><td width="100" nowrap=""><p align="center">11.0 ~ 9.0</p></td><td width="57" nowrap=""><p align="center">Bars</p></td><td width="90" nowrap=""><p align="center">11.93</p></td></tr><tr><td width="192" nowrap=""><p align="left">Fluid barrier temp.</p></td><td width="91" nowrap=""><p>2TI-50352</p></td><td width="100" nowrap=""><p align="center">80</p></td><td width="57" nowrap=""><p align="center">°C</p></td><td width="90" nowrap=""><p align="center">37</p></td></tr><tr><td width="192" nowrap=""><p align="left">Bearing temp</p></td><td width="91" nowrap=""><p>&nbsp;</p></td><td width="100" nowrap=""><p align="center">80</p></td><td width="57" nowrap=""><p align="center">°C</p></td><td width="90" nowrap=""><p align="center">44</p></td></tr><tr><td width="34" nowrap="" rowspan="4"><p align="center"><br></p></td><td width="192" nowrap=""><p align="left">NDE</p><p align="left">Lube oil Level.</p></td><td width="91" nowrap=""><p>&nbsp;</p></td><td width="100" nowrap=""><p align="center">@ Half</p></td><td width="57" nowrap=""></td><td width="90" nowrap=""><p align="center">OK</p></td></tr><tr><td width="192" nowrap=""><p align="left">Fluid barrier pressure</p></td><td width="91" nowrap=""><p>2PI-50354</p></td><td width="100" nowrap=""><p align="center">11.0 ~ 9.0</p></td><td width="57" nowrap=""><p align="center">Bars</p></td><td width="90" nowrap=""><p align="center">11.55</p></td></tr><tr><td width="192" nowrap=""><p align="left">Fluid barrier temp.</p></td><td width="91" nowrap=""><p>2TI-50355</p></td><td width="100" nowrap=""><p align="center">80</p></td><td width="57" nowrap=""><p align="center">°C</p></td><td width="90" nowrap=""><p align="center">45</p></td></tr><tr><td width="192" nowrap=""><p align="left">Bearing temp</p></td><td width="91" nowrap=""><p>&nbsp;</p></td><td width="100" nowrap=""><p align="center">80</p></td><td width="57" nowrap=""><p align="center">°C</p></td><td width="90" nowrap=""><p align="center">51</p></td></tr></tbody></table></div></td></tr></tbody></table></div>', NULL, '2025-03-20 18:11:05', CURRENT_TIMESTAMP, 'PTTEP\\DirekT', NULL, false, 'G2S') RETURNING id INTO new_report_id;
