  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'PM 2A-4370A Perform 12MPM', 'Mechanic', 'PM', 'Completed', '2025-03-21', '<p>2A-4370A Running Hour : 115,884</p><p><br></p><p>Remove move protection guard.</p><p>Remove fan belt.</p><p>Check driven pulley/sprocket condition.</p><p>Check lock hub and re-tightening.</p><p>Retighten bolts and check cooler fan shaft &amp; bearing top and bottom.</p><p>Re-grease cooler fan shaft bearing top and bottom.</p><p>Install new fan belt and check belt tension.</p><p>Check blades clearance between blade edge and casing (plenum).&nbsp;</p><p>Measure blades angle.</p><p>Install protection guard and test run.</p>', '<p>Photo Link :&nbsp;<a href="https://pttep.sharepoint.com/:f:/r/sites/THG2S/DS03Maintenance/031%20DBS_MM/6.%20Picture/61.%20PPS%20Equipment%20Picture/Air%20cooler/2A-4370/2A-4370A/2025/20250321%20Perform%2012MPM?csf=1&amp;web=1&amp;e=GowQMX">20250321 Perform 12MPM</a></p><p><br></p><p><span style="color: rgb(69, 90, 100); text-wrap-mode: nowrap; background-color: rgb(249, 249, 249);">58.13.96.105.9 :&nbsp;&nbsp;</span><span style="background-color: rgb(249, 249, 249); color: rgb(69, 90, 100); font-size: 12px; text-wrap-mode: nowrap;">BELT,TIMING,DRIVE METRIC,GT3-2400-8MGT</span></p>', '2025-03-21 14:14:18', '2025-03-26 17:56:53', 'PTTEP\\GBS.Mechanic-WorkS', 'PTTEP\\GBS.Mechanic-WorkS', false, 'G2S') RETURNING id INTO new_report_id;
