  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Troubleshooting UCV-1551 not function', 'Automation', 'CM', 'Under Monitoring', '2025-03-16', '<div>Troubleshooting UCV-1551 antisurge control valve not function.</div><div>Asfound PID tuning SP 25, PG 0.02 and TI 1.2. It consequence to UCV-1551 not move since september 2025.</div><div>- Today we performed function test antisurge valve (UCV-1551) as follow step below.</div><div>- Function test control loop and monitor action of UCV-1550.By requested CRO share load for J-T valve and Turbo-Ex (50/50) . Tried adjusting set point (SP 94) to more than the as found process variable (PV 92). Confirming the valve responded correctly. This demonstrates the valve s ability to react to changes in SP and maintain control.</div><div>- Performed PID tuning used parameters from 2021 (SP 85, PG 0.6, TI 5.0) were applied. Requested CRO slowly close J-T valve. Then monitor control response of the antisurge valve. The PV decreased correspondingly with an increase in valve position, ultimately reaching the setpoint (PV SV). This indicates proper PID control, as the valve effectively compensated for the changing conditions created by closing the J-T valve.</div><div><br></div>', NULL, '2025-03-22 10:44:01', CURRENT_TIMESTAMP, 'PTTEP\\Art.Automation', NULL, false, 'ART') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-ZT-1551', 'ART-ZT-1551', 'POSITION TRANSMITTER', NULL, NULL, 'POSITION TRANSMITTER', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-UCV-1551', 'ART-UCV-1551', 'ANTI SURGE CONTROL VALVE', NULL, NULL, 'ANTI SURGE CONTROL VALVE', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Piriyut K.', NULL, 'EXTERNAL', '2025-03-22 10:44:01', CURRENT_TIMESTAMP, 'PTTEP\\Art.Automation', NULL);
END $$;

