  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S Combination Oven malfunction.', 'Electrical', 'CM', 'Completed', '2025-03-22', '<p><b>Troubleshooting Combination Oven Malfunctions</b></p><p><b>Combination Oven 1:</b></p><p>- Insulation testing revealed that the heater had low insulation (&lt;1MOhm).</p><p>- Awaiting replacement of the heater.</p><p><b>Combination Oven 3:</b></p><p>- Performed Cleaning of the Combi Oven</p><p><b>Combination Oven 4:</b></p><p>- Restarted the combi oven, but alarm Ept3 still appeared.The combi oven is operational, but it cannot track &nbsp;&nbsp;&nbsp;the cooking time to completion.</p><p>- Entered program mode and disabled probe 3 (changed parameter P8 from 2 to 0, under vendor supervision).</p><p>- Restarted the combi oven and conducted a function test, confirming normal operation.</p><p><br></p>', NULL, '2025-03-22 16:44:30', '2025-03-22 17:07:15', 'PTTEP\\Art-Tech-Prod-Maint', 'PTTEP\\Art-Tech-Prod-Maint', false, 'ART') RETURNING id INTO new_report_id;
