-- Inserting report ID 28134
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Troubleshoot fire truck water level indicator', 'Electrical & Instrument', 'CM', 'Completed', '2025-03-24', '<p><b><u>Today Activity</u></b></p><p>Troubleshoot level indicator of fire truck at maintenance workshop.</p><p><br></p><p><u><b>Action</b></u></p><p>- Repair broken cable.</p><p>- Check pressure transducer and cable condition.</p><p>- Found loosen points in cable connector.</p><p>- Replaced and calibrate the level indicator</p><p>- Level indicator can show correct level of fire truck water tank</p><p>- Reassemble level indicator in junction box.</p><p>- Checked all cable condition.</p><p>- Repair other damaged cables.</p><p>- Finish</p><p><br></p><p><b><u>22.3.25 (History Record)</u></b></p><p>- Checked continuity of level indicator of fire truck. (Abnormal)</p><p>- Hence, open junction box and checked all cables condition.</p><p>- Found most cables are damaged by rat bite.</p><p>- Tomorrow will continue repairing.</p>', NULL, '2025-03-24 17:50:33', '2025-03-24 17:51:12', 'PTTEP\\ZOC.Elec-Tec', 'PTTEP\\ZOC.Elec-Tec', false, 'ATL') RETURNING id INTO new_report_id;
