  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Htet', NULL, 'EXTERNAL', '2025-03-24 17:50:33', '2025-03-24 17:51:12', 'PTTEP\\ZOC.Elec-Tec', 'PTTEP\\ZOC.Elec-Tec');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Jack', NULL, 'EXTERNAL', '2025-03-24 17:50:33', '2025-03-24 17:51:12', 'PTTEP\\ZOC.Elec-Tec', 'PTTEP\\ZOC.Elec-Tec');
