  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S LIT-2260 and LIT-2261 FGC2 reading discrepancy', 'Instrument', 'CM', 'Completed', '2025-03-25', '<p>T/S LIT-2260 and LIT-2261 level of discharge scrubber FGC2 reading discrepancy</p><p> suspect that form LIT-2261(SIS) reading error.</p><p>- Found LIC2260 Discrepancy alarm and Recover many time since 20/3/2025 on DCS</p><p>- Found LIT-2261 (SIS/4-20mA) was reading up to 14% while LIT-2260 (Fieldbus) still reading around 4% from Historical Trend.</p><p>- As found LIT-2261 (SIS/4-20mA - JM4)&nbsp;by fill up water in chamber, the level is reading properly from 0-100% but the float is quite unsmooth travelling for 0-25 %, then soak the chamber by Oiler, it''s getting better.</p><p>- As found LIT-2260 (FF - JM3) fill up water in chamber, the level was update slowly and fluctuated.</p><p>- Fine-Tune config parameter by decrease Filter Time from 30 sec to 10 sec for reduced latency updating and reduced sensitiviy from 10 to 9 to avoid extra float detect.</p><p><br></p><p>Both Level are proper reading.</p><p><br></p><p>&nbsp;</p>', '<p>Picture Link:</p><p>https://pttep.sharepoint.com/sites/THART/EI/Forms/AllItems.aspx?id=%2Fsites%2FTHART%2FEI%2F04%20%2D%20Electrical%5FInstrument%2F18%2DEI%20Pictures%20Database%2F1%5FAPP%2FLIT%5FLevel%2FLIT%2D2260%5F61&amp;viewid=415f9878%2Da53c%2D45fe%2D8639%2De524c6aa2067</p>', '2025-03-25 15:12:13', '2025-03-26 20:13:47', 'PTTEP\\Art-Tech-Prod-Maint', 'PTTEP\\Art-Tech-Prod-Maint', false, 'ART') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-LIT-2260', 'ART-LIT-2260', 'LEVEL INDICATOR TRANSMITTER(ESD)', NULL, NULL, 'LEVEL INDICATOR TRANSMITTER(ESD)', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-LIT-2261', 'ART-LIT-2261', 'LEVEL INDICATOR TRANSMITTER', NULL, NULL, 'LEVEL INDICATOR TRANSMITTER', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Winyoo N.', NULL, 'EXTERNAL', '2025-03-25 15:12:13', '2025-03-26 20:13:47', 'PTTEP\\Art-Tech-Prod-Maint', 'PTTEP\\Art-Tech-Prod-Maint');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Nitipong I.', NULL, 'EXTERNAL', '2025-03-25 15:12:13', '2025-03-26 20:13:47', 'PTTEP\\Art-Tech-Prod-Maint', 'PTTEP\\Art-Tech-Prod-Maint');
