-- Inserting report ID 28160
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Inspect lighting inverter connected load at ZBV-1', 'Electrical & Instrument', 'CM', 'Completed', '2025-03-25', '<p><b><u>Today Activity</u></b></p><p>Inspected connected load of lighting inverter at ZBV-1 as per PMO/E requested.</p><p><u><b>Action</b></u></p><p>- Checked input DC voltage of main breaker MCB-01. (26 Vdc is normal)</p><p>- Install temporary inverter to check outlet AC voltage.</p><p>- Outlet AC voltages of 2 socket. (250.9 VAC)</p><p>- Turned on outlet AC breaker MCCB-01 to MCCB-06</p><p>- MCCB-06 which is G-8020 charging breaker.</p><p>- Total maximum ampere was over 42.5 A and inverter was tripped.</p><p>- Turned off MCCB-06 and switch on inverter again.</p><p>- Total ampere was over 35.6 A and increases slightly due to switch on lighting in ITR room.</p><p>- Then, inverter was tripped again.</p><p>- Turned off MCCB-01,06 and other breaker were turning on.</p><p>- Maximum total ampere was around 35A and stable.</p><p>- In conclusion, inverter was tripped by MCCB-01 and MCCB-06.</p><p>- Other breaker outlet ampere are stable and normal condition.</p><p><br></p>', NULL, '2025-03-25 15:14:41', CURRENT_TIMESTAMP, 'PTTEP\\ZOC.Elec-Tec', NULL, false, 'ATL') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-FIRE INTERVENTION TRUCK', 'ATL-OC-FIRE INTERVENTION TRUCK', 'Fire Intervention Truck', NULL, NULL, 'Fire Intervention Truck', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Htet', NULL, 'EXTERNAL', '2025-03-25 15:14:41', CURRENT_TIMESTAMP, 'PTTEP\\ZOC.Elec-Tec', NULL);
