-- Inserting report ID 28162
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'PP : TG-5620 HVCB temporary replacement', 'Electrical', 'CM', 'In Progress', '2025-03-25', '<p>.PP : TG-5620 HVCB (1BX-01) temporary replacement</p><p><b style="background-color: rgb(255, 255, 0);">Background</b></p><p>&gt;&gt; Regarding improper closing problem of TG-5620 HVCB, </p><p>the new HVCB, which is modified from new M-5080B HVCB, shall temporarily replace the problem one.</p><p>- HVCB is the same Model/Function/Wiring with existing one.</p><p>&gt;&gt; After replaced, the problemed HVCB will be sent to Schneider factory for root cause finding and repair</p><p><b><br></b></p><p><b style="background-color: rgb(255, 255, 0);">Today activities;</b></p><div class="O1">- To check and compare the schematic diagram between no.51267440 and 51268176</div><div class="O1">- Individual New HVCB function test according to Schneider procedure as list,</div><div class="O1">1.Visual Inspection and Function Test included with Arcing contact wear check</div><div class="O1"><br></div><div class="O1">2.Main Contact Resistance Measurement at 100 A. by Micro-Ohm MOSTEC</div><div class="O1">Result : 44.96/43.61/45.88 micro-ohm.</div><div class="O1"><br></div><div class="O1">3.Insulation Resistance Measurement at 5 kV. by Megger Tester</div><div class="O1">Result : &gt;10 T-Ohm.</div><div class="O1">&nbsp;</div><div class="O1">4.Timing Measurement by Megger EGIL Breaker Analysis</div><div class="O1"><br></div><div class="O1">5.Disconnecting Contact Finger by&nbsp;Vernier calipers.</div><div class="O1"><br></div><div class="O1">-&nbsp;X2 Pin contact compare between Existing and New HVCB by multimeter</div>  <div class="O2">* Aux contact at X2 of HVCB shall be verified to ensure 2 HVCBs are same.</div>', '<a href="https://pttep.sharepoint.com/sites/THG2N/DL_Selective_Access/Forms/AllItems.aspx?newTargetListUrl=%2Fsites%2FTHG2N%2FDL%5FSelective%5FAccess&amp;viewpath=%2Fsites%2FTHG2N%2FDL%5FSelective%5FAccess%2FForms%2FAllItems%2Easpx&amp;id=%2Fsites%2FTHG2N%2FDL%5FSelective%5FAccess%2F02%2DPBN%2DM%2F02%20MEI%2F19%20Photos%2F00%20Electrical%20Photos%2FPP%2FTG%2D5620%2F2025%2D03%2D25%20HVCB%20Temporary%20replacement&amp;viewid=dce8e204%2D2273%2D4c5e%2Da20c%2Dcbf12e9b5007">BONGKOT NORTH (G2N) - 2025-03-25 HVCB Temporary replacement - All Documents</a>', '2025-03-25 15:52:49', '2025-03-25 16:14:15', 'PTTEP\\Bongkot.Elec-Lead', 'PTTEP\\Bongkot.Elec-Lead', false, 'G2N') RETURNING id INTO new_report_id;
