-- Inserting report ID 28258
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Perform 2KPM on G-8930 (Day#1)', 'Mechanic', 'PM', 'In Progress', '2025-03-27', '<p></p><p>1.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Remove spark plugs.</p>  <p>2.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Remove rocker box cover.</p>  <p>3.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Adjust valve clearances and apply torque adjuster screw lock nut 19 mm (50 N-m).</p><p>  </p><p></p><p>4.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Clean the rocker box covers.</p><p>5.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Install new rocker box cover seals.</p><p>6.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Reinstall rocker box cover and tighten with the torque 20 N-m.</p><p>7.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Check and clean the spark plugs with contact cleaner.</p><p>8.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Install the spark plug and tighten with the torque 50 N-m.</p><p>9.&nbsp; &nbsp; &nbsp; Check and clean the air inlet filters.</p><p>10.&nbsp; &nbsp; &nbsp; Check the air inlet indicators.&nbsp;</p><p>11.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Housekeeping around the working area.</p><p></p><br><p></p><p></p>Valve Clearances Table,<p></p><p><br></p><p></p><table border="1" cellspacing="0" cellpadding="0"><tbody><tr>   <td width="357" colspan="3" valign="top">   <p align="center">BEFORE</p>   </td>   <td width="357" colspan="3" valign="top">   <p align="center">AFTER</p>   </td>  </tr>  <tr>   <td width="94" valign="top">   <p>Cylinder No</p>   </td>   <td width="138" valign="top">   <p>Inlet</p>   </td>   <td width="124" valign="top">   <p>Exhaust</p>   </td>   <td width="98" valign="top">   <p>Cylinder No</p>   </td>   <td width="130" valign="top">   <p>Inlet</p>   </td>   <td width="129" valign="top">   <p>Exhaust</p>   </td>  </tr>  <tr>   <td width="94" valign="top">   <p align="center">A1</p>   </td>   <td width="138" valign="top">   <p>0.4 mm</p>   </td>   <td width="124" valign="top">   <p>0.4 mm</p>   </td>   <td width="98" valign="top">   <p align="center">A1</p>   </td>   <td width="130" valign="top">   <p align="center">0.4 mm</p>   </td>   <td width="129" valign="top">   <p align="center">0.4 mm</p>   </td>  </tr>  <tr>   <td width="94" valign="top">   <p align="center">A2</p>   </td>   <td width="138" valign="top">   <p>0.45 mm</p>   </td>   <td width="124" valign="top">   <p>0.45 mm</p>   </td>   <td width="98" valign="top">   <p align="center">A2</p>   </td>   <td width="130" valign="top">   <p align="center">0.4 mm</p>   </td>   <td width="129" valign="top">   <p align="center">0.4 mm</p>   </td>  </tr>  <tr>   <td width="94" valign="top">   <p align="center">A3</p>   </td>   <td width="138" valign="top">   <p>0.45 mm</p>   </td>   <td width="124" valign="top">   <p>0.4 mm</p>   </td>   <td width="98" valign="top">   <p align="center">A3</p>   </td>   <td width="130" valign="top">   <p align="center">0.4 mm</p>   </td>   <td width="129" valign="top">   <p align="center">0.4 mm</p>   </td>  </tr>  <tr>   <td width="94" valign="top">   <p align="center">A4</p>   </td>   <td width="138" valign="top">   <p>0.4 mm</p>   </td>   <td width="124" valign="top">   <p>0.45 mm</p>   </td>   <td width="98" valign="top">   <p align="center">A4</p>   </td>   <td width="130" valign="top">   <p align="center">0.4 mm</p>   </td>   <td width="129" valign="top">   <p align="center">0.4 mm</p>   </td>  </tr>  <tr>   <td width="94" valign="top">   <p align="center">A5</p>   </td>   <td width="138" valign="top">   <p>0.4 mm</p>   </td>   <td width="124" valign="top">   <p>0.4 mm</p>   </td>   <td width="98" valign="top">   <p align="center">A5</p>   </td>   <td width="130" valign="top">   <p align="center">0.4 mm</p>   </td>   <td width="129" valign="top">   <p align="center">0.4 mm</p>   </td>  </tr>  <tr>   <td width="94" valign="top">   <p align="center">A6</p>   </td>   <td width="138" valign=