  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Replace helium gas cylinder at OGC shelter.', 'Electrical & Instrument', 'OTH', 'Completed', '2025-03-28', '<div><u><b>Today Activity&nbsp;</b></u></div><div><p>Replace helium gas cylinder no.1 &amp; 3 of OGC AIT-81906 and AIT-81907 at OGC shelter.</p><p><br></p><p><b><u>Action</u></b></p><p>- Replace empty helium gas cylinder no.1 of OGC AIT-81906.</p><p>- Serial no.991080 (Used)</p><p>- Serial no. 991101 (New)</p><p>- Follow the procedure of helium gas cylinder replacement.</p><p>- After replacement, check LOPC on connector of gas cylinder regulator. (Normal)</p><p>- Gas cylinder no.2 (old) is lead 120 psi and no.1 (New) is lag 110 psi.</p><p>- Finish</p><p><br></p><p>- Replace empty helium gas cylinder no.3 of OGC AIT-81907.</p><p>- Serial no.991078 (Used)</p><p>- Serial no. 991097 (New)</p><p>- Follow the procedure of helium gas cylinder replacement.</p><p>- After replacement, check LOPC on connector of gas cylinder regulator. (Normal)</p><p>- Gas cylinder no.4 (old) is lead 120 psi and no.3 (New) is lag 110 psi.</p><p>- Finish</p><p>- Found downstream pressure gauges of cylinder no.3 pressure regulator is not working properly.</p><p>- Gas cylinder no.4 regulator does also need to replace.</p></div>', NULL, '2025-03-28 18:57:33', '2025-03-28 19:01:39', 'PTTEP\\ZOC.Elec-Tec', 'PTTEP\\ZOC.Elec-Tec', false, 'ATL') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-AIT-81906', 'ATL-OC-AIT-81906', 'Gas chromatograph metering N2 and CO2 1', NULL, NULL, 'Gas chromatograph metering N2 and CO2 1', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
