-- Inserting report ID 28429
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'TG#1 Crank soak wash', 'Turbine Mech', 'PM ', 'Completed', '2025-03-30', '<p>Perform Crank soak wash with wash down water.Fire hour 36,029 hrs.</p><p>- Process Isolation on Fuel gas supply, SDV-6100, Manual block valve, Diesel supply valve to package.</p><p>- CO2 inhibited at Enclosure package.</p><p>- Disconnected Fuel gas Metal flexible hose inlet manifold in package and blinded it''s.</p><p>- Removed Fuel Injector No.1,2 &amp;12. then installed air hose connection flange.</p><p>- Removed Bleed manifold stage 6th both left and Right side and installed blind flange and air connecting flange.</p><p>-&nbsp; Disconnected Spark plug cable and protected.</p><p>- Disconnected Torch drain line, Pilot gas and diesel line then plug it''s.</p><p>- Removed PCD transmitter tubing.</p><p>- Installed Air flexible hoses see details in WIS.</p><p>- Crank soak wash with ZOK27 20 Liters + Washdown water 80 Liters 1 time.</p><p>- Rinse wash with Washdown water 100 Liters 3 time.</p><p>- Removed Torch drain and Fuel gas manifold plug.</p><p>- Crank dry 1 time for 10 minutes.</p><p>- Removed Air hose for crank soak wash kit.</p><p>- Reinstalled all accessories.</p><p>- Hand back PTW , Process de-isolation, Normalized CO2.</p><p>- At 18:17 hrs Start TG#1 to fire dry for 30 minutes and continue run on load.</p><p><br></p>', NULL, '2025-03-31 07:05:12', '2025-03-31 09:10:55', 'PTTEP\\Art.MechTurbine', 'PTTEP\\Art.MechTurbine', false, 'ART') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-A-6100', 'ART-A-6100', 'MAIN POWER GENERATOR PACKAGE', NULL, NULL, 'MAIN POWER GENERATOR PACKAGE', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
