-- Inserting report ID 28512
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S LIT-1753 level display no signal alarm', 'Instrument', 'CM', 'Completed', '2025-04-02', '<p>T/S LIT-1753 (Condensate Surge Drum) level display no signal alarm.</p><p>- Found LIT-1753 IOP alarm on DCS (CRO switched LIT-1754 (SIS) to control LIC-1753)</p><p>- Found FF transmitter JM3 display status <i>NoSignal</i> then verified History Event which found <i>Flt1Fail</i> (No Level Detect from Float) and <i>NoSignal</i> (No Level Being Detected)</p><p>- Reset History Event, found new event are <i>NoSignal</i> and <i>Flt1Fail</i>&nbsp;</p><p>- Monitor F1 Counts (Raw Data Detection) which found 2 values fluctuated are 2,1xx (Current Level 40%) and 31,xxx (Fail by out of range value)</p><p>&nbsp;</p><p><br></p><p>- Increase Sensitivity from 2 to 4, the level signal is appear but still found some failure signal.</p><p>- Cleaning dirty connector on Electronics Module by Contact Cleaner. Still found some failure signal.</p><p>- Decrease Treshold from 80 to 50, Raw Data count is only one value which changing follow current float level properly.</p><p><br></p><p>CRO swithed LIT-1753 back to control properly.&nbsp;</p><p>&nbsp;&nbsp;<br></p><p><br></p>', '<p><a href="https://pttep.sharepoint.com/sites/THART/EI/Forms/AllItems.aspx?id=%2Fsites%2FTHART%2FEI%2F04%20%2D%20Electrical%5FInstrument%2F18%2DEI%20Pictures%20Database%2F1%5FAPP%2FLIT%5FLevel%2FLIT%2D1753%5FCondySurgeDrum%2F20250402%5FLIT1753%5FFF%5FIOP&amp;viewid=415f9878%2Da53c%2D45fe%2D8639%2De524c6aa2067">Picture</a><br></p><p><br></p><p><span style="color: rgb(0, 0, 255); font-family: Calibri; font-size: 21.3333px; text-align: center; white-space-collapse: preserve;">WO: 500611492</span></p>', '2025-04-02 14:13:02', '2025-04-02 15:39:11', 'PTTEP\\Art-Tech-Prod-Maint', 'PTTEP\\Art-Tech-Prod-Maint', false, 'ART') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-LIT-1753', 'ART-LIT-1753', 'LEVEL INDICATOR TRANSMITTER', NULL, NULL, 'LEVEL INDICATOR TRANSMITTER', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Panyawut B.', NULL, 'EXTERNAL', '2025-04-02 14:13:02', '2025-04-02 15:39:11', 'PTTEP\\Art-Tech-Prod-Maint', 'PTTEP\\Art-Tech-Prod-Maint');
