  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S 2XV-31113E discrepancy alarm.', 'Instrument', 'CM', 'Completed', '2025-04-04', '<p>T/S 2XV-31113E discrepancy alarm.&nbsp;</p><p><br></p><p>Issue Identification: </p><p>- The valve was found to be stuck closed about 90% of the time, which triggered the discrepancy alarm.</p><p>- The actuator or main valve was suspected to be the cause of the issue.</p><p><br></p><p>Actuator Check:</p><p> - Disassembled the actuator from the valve and conducted a function test, which showed the actuator was moving normally.</p><p>- Valve Inspection After performing cleaning and exercising the main valve, it was found to be working normally.</p><p>- Reassembly and Testing: Reassembled the actuator to the valve and performed a function test. The valve remained stuck at approximately 95% closed, but the discrepancy alarm was no longer present.</p><p><br></p><p>Next Steps: Inform to team leader decided to order a new actuator for replacement.</p>', NULL, '2025-04-04 13:11:29', '2025-04-04 13:16:11', 'PTTEP\\PooritadT', 'PTTEP\\PooritadT', false, 'G2S') RETURNING id INTO new_report_id;
