-- Inserting report ID 28591
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'SPP: Assist Mech team crane pull load test. ', 'Electrical', 'CM', 'Complete', '2025-04-04', '<p>SPP: Assist Mech team crane pull load test.</p><p>- Assist Mech team crane pulls load test by water bag at 20 Ton.</p><p>- Found MIPEG load indicator reading error difference load inspection test 0.7 ton at pulls load.</p><p>- Re-calibration max load and load functional tested it was satisfactory result.</p><p>- MIPEG calibration parameter result see as below.</p><p>&nbsp; - at point 0 (0.0 Ton) sensor data = 399.9 Hz.</p><p>&nbsp; - at point 1 (20.0 Ton) sensor data = 356.4 Hz.</p><p><br></p><p><br></p>', '<p><br></p><div class="note-dropzone" style="box-sizing: border-box; position: absolute; z-index: 100; display: table; color: rgb(135, 206, 250); background-color: white; opacity: 0.95; width: 700px; height: 99px;"><div class="note-dropzone-message" style="box-sizing: border-box; display: table-cell; font-size: 28px; font-weight: bold; text-align: center; vertical-align: middle;">Drag image or text here</div></div><p><br></p><div class="note-toolbar panel-heading" style="box-sizing: border-box; padding: 0px 0px 5px 5px; border-bottom: 1px solid rgb(221, 221, 221); border-top-left-radius: 3px; border-top-right-radius: 3px; color: rgb(51, 51, 51); background-color: rgb(245, 245, 245); border-top-color: rgb(221, 221, 221); border-right-color: rgb(221, 221, 221); border-left-color: rgb(221, 221, 221); margin: 0px;"><div class="note-btn-group btn-group note-insert" style="box-sizing: border-box; position: relative; display: inline-block; vertical-align: middle; margin-top: 5px; margin-right: 5px; margin-left: 0px;"><button type="button" class="note-btn btn btn-default btn-sm" tabindex="-1" title="" data-original-title="Link (CTRL+K)" style="box-sizing: border-box; margin: 0px; font-style: inherit; font-variant: inherit; font-weight: 400; font-stretch: inherit; font-size: 12px; line-height: 1.5; font-family: inherit; font-optical-sizing: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit; color: rgb(51, 51, 51); overflow: visible; text-transform: none; appearance: button; cursor: pointer; display: inline-block; padding: 5px 10px; text-align: center; white-space: nowrap; vertical-align: middle; touch-action: manipulation; user-select: none; background-image: none; border: 1px solid rgb(204, 204, 204); border-radius: 3px; background-color: rgb(255, 255, 255); transition: all 0.2s ease-in-out 0s; position: relative; float: left;"><i class="note-icon-link" style="box-sizing: border-box;"></i></button></div></div><p><br></p><div class="note-editing-area" style="box-sizing: border-box; position: relative; overflow: hidden;"><div class="note-handle" style="box-sizing: border-box;"></div><br class="Apple-interchange-newline"></div><p><a href="https://pttep.sharepoint.com/:f:/r/sites/THG2N/DL_Selective_Access/02-PBN-M/02%20MEI/19%20Photos/00%20Electrical%20Photos/SPP/Crane/Assist%20Mech%20team%20crane%20load%20test%20by%20water%20bag?csf=1&amp;web=1&amp;e=5MfpjH">Assist Mech team crane load test by water bag</a></p>', '2025-04-04 16:17:37', '2025-04-04 16:20:31', 'PTTEP\\Bongkot.Elec-Lead', 'PTTEP\\Bongkot.Elec-Lead', false, 'G2N') RETURNING id INTO new_report_id;
