-- Inserting report ID 28805
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Troubleshoot gas detector GD81021 at inlet ESDV', 'Electrical & Instrument', 'CM', 'Completed', '2025-04-07', '<p><b><u>Today activity</u></b></p><p>Troubleshoot&nbsp;gas detector GD81021 at inlet ESDV area<b><u></u></b></p><p><b><u><br></u></b></p><p><b><u>Action</u></b></p><p>1) Replace Surge protector SPDAI-50 at ITR room.</p><p>2) Replace defective fuse of power supply located inside ITR room.</p><p>3) Measured the voltage (24VDC).</p><p>4) Reinstalled back original gas detector at field side</p><p>5) Function tested with methane spam gas.</p><p>6) GD81021 is back to service.</p><p><b><u><br></u></b></p><p><b><u style="background-color: rgb(255, 255, 0);">History (6.4.2025)</u></b></p><p><span style="background-color: rgb(255, 255, 0);">Troubleshoot&nbsp;gas detector GD81021 at inlet ESDV area</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p> <u><b style="background-color: rgb(255, 255, 0);">Action&nbsp;</b></u></p><p><span style="background-color: rgb(255, 255, 0);">1) Change the connection with new spare pair cable of GD from field JB to GD. (6.3VDC , GD LED no light)</span></p><p><span style="background-color: rgb(255, 255, 0);">2) Check the cable condition inside JB.</span></p><p><span style="background-color: rgb(255, 255, 0);">Found that ground fault at 0 V cable of SPD.</span></p><p><span style="background-color: rgb(255, 255, 0);">3) Reinstate with original pair cable connected to GD81021.&nbsp;</span></p><p><span style="background-color: rgb(255, 255, 0);">4) Now, open knight switch of gas detector.</span></p><p><span style="background-color: rgb(255, 255, 0);">5) Tomorrow, we will replace SPD.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><b><u style="background-color: rgb(255, 255, 0);">History (5.4.25)</u></b></p><p><span style="background-color: rgb(255, 255, 0);">- Checked fuse connection of Gas Detector.</span></p><p><span style="background-color: rgb(255, 255, 0);">- Normal condition.</span></p><p><span style="background-color: rgb(255, 255, 0);">- Continue checking tomorrow.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><b><u style="background-color: rgb(255, 255, 0);">History (3.4.25)</u></b></p><p><span style="background-color: rgb(255, 255, 0);">- Calibrate spare gas detector in task room. (Pass)</span></p><p><span style="background-color: rgb(255, 255, 0);">- Install calibrated gas detector in local.</span></p><p><span style="background-color: rgb(255, 255, 0);">- Found voltage dropped (6.8Vdc)</span></p><p><span style="background-color: rgb(255, 255, 0);">- Checked power supply fuse in ITR room cabinet. (Normal)</span></p><p><span style="background-color: rgb(255, 255, 0);">- Continuity test of instrument cable from ITR to local. (7 ohm)</span></p><p><span style="background-color: rgb(255, 255, 0);">- Checked cable terminal condition in local junction box.</span></p><p><span style="background-color: rgb(255, 255, 0);">- Continue troubleshooting next days.</span></p>', NULL, '2025-04-07 21:01:21', '2025-04-08 06:58:26', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.Se-EI', false, 'ATL') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-GD-81021', 'ATL-OC-GD-81021', 'Point Type GD, Process Area', NULL, NULL, 'Point Type GD, Process Area', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Noble', NULL, 'EXTERNAL', '2025-04-07 21:01:21', '2025-04-08 06:58:26', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.Se-EI');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Htet Aung', NULL, 'EXTERNAL', '2025-04-07 21:01:21', '2025-04-08 06:58:26', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.Se-EI');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Bone', NULL, 'EXTERNAL', '2025-04-07 21:01:21', '2025-04-08 06:58:26', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.Se-EI');
