  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, '6M PM 2DG-2277 Mobile generator', 'Mechanic', 'PM', 'Completed', '2025-04-07', '<p>- 6M PM 2DG-2277 Mobile generator package used at WPS-20</p><p>- Replace engine lube. <span style="background-color: rgb(255, 255, 0);">(As per running hours condition at 1015 hrs.)&nbsp;</span></p>  <p>- Replace lube oil filter. 18.71.68.002.3 Lube oil filter</p><p>- Check water coolant level.</p>  <p>- Replace air intake filter.18.71.49.007.3 Air filter element (Outer), 18.71.49.008.3 Air filter element (Inner)</p>  <p>- Replace Fuel / Water Separator. 58.43.55.001.9 Fuel / Water Separator</p>  <p>- Replace fuel filter. 58.43.55.002.9 Fuel Filter</p>  <p>- Check hydraulic oil and filter.</p>  <p>- Clean exhaust frame arrestor and breather cap.</p>  <p>- Check pinion gear and hydraulic starter condition.</p>  <p>- Check diesel fuel level at 50 % of tank.</p>  <p>- Check hydraulic level at 35%of tank and charge hydraulic all accumulator at 2500 psi. </p>  <p>- Check engine belt tension and condition.</p>  <p>- Check alternator belt condition and adjust it.</p>  <p>- Test run unit about 15 minutes. Not found alar and function ESD test.</p>  <p>- Clean inside package.</p>', '<p><a href="https://pttep.sharepoint.com/:f:/r/sites/THG2S/DS03Maintenance/031%20DBS_MM/6.%20Picture/66.%20Mobile%20Equipment%20Picture/Mobile%20Generator/G-04%20(2DG-2277)(G13J0031)/2025/2025-04-07%202DG-2277%206M%20PM?csf=1&amp;web=1&amp;e=wqqpKv">https://pttep.sharepoint.com/:f:/r/sites/THG2S/DS03Maintenance/031%20DBS_MM/6.%20Picture/66.%20Mobile%20Equipment%20Picture/Mobile%20Generator/G-04%20(2DG-2277)(G13J0031)/2025/2025-04-07%202DG-2277%206M%20PM?csf=1&amp;web=1&amp;e=wqqpKv</a><br></p>', '2025-04-08 10:38:37', '2025-04-08 11:12:37', 'PTTEP\\GBS.Mechanic-WorkS', 'PTTEP\\GBS.Mechanic-WorkS', false, 'G2S') RETURNING id INTO new_report_id;
