-- Inserting report ID 28871
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S 2UCP-34600 Condensate Auto Sampler not counter', 'Instrument', 'CM', 'Completed', '2025-04-09', '<p data-start="114" data-end="170" class=""><strong data-start="114" data-end="170">T/S 2UCP-34600 Condensate Auto Sampler not countering</strong></p> <ul data-start="172" data-end="695"> <li data-start="172" data-end="249" class=""> <p data-start="174" data-end="249" class=""><strong data-start="174" data-end="184">Issue:</strong> The condensate auto-sampler was not properly countering samples.</p> </li> <li data-start="253" data-end="451" class=""> <p data-start="255" data-end="268" class=""><strong data-start="255" data-end="268">Findings:</strong></p> <ul data-start="271" data-end="451"> <li data-start="271" data-end="358" class=""> <p data-start="273" data-end="358" class="">The pressure control device was functioning correctly and taking samples as expected.</p> </li> <li data-start="361" data-end="451" class=""> <p data-start="363" data-end="451" class="">The bite checker movement was not smooth, possibly due to lack of lubrication.</p> </li> </ul> </li> <li data-start="453" data-end="608" class=""> <p data-start="455" data-end="473" class=""><strong data-start="455" data-end="473">Actions Taken:</strong></p> <ul data-start="476" data-end="608"> <li data-start="476" data-end="537" class=""> <p data-start="478" data-end="537" class="">Disassembled the bite checker for cleaning and lubrication.</p> </li> <li data-start="540" data-end="608" class=""> <p data-start="542" data-end="608" class="">Performed a function test, and the system is now working properly.</p> </li> </ul> </li> <li data-start="610" data-end="695" class=""> <p data-start="612" data-end="627" class=""><strong data-start="612" data-end="627">Next Steps:</strong></p> <ul data-start="630" data-end="695"> <li data-start="630" data-end="695" class=""> <p data-start="632" data-end="695" class="">Continue to monitor the system to ensure it operates correctly.</p></li></ul></li></ul>', NULL, '2025-04-09 16:38:25', CURRENT_TIMESTAMP, 'PTTEP\\PooritadT', NULL, false, 'G2S') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-2CMP-3465', 'GBS-2CMP-3465', 'CONDENSATE ALLOCATION METERING PANEL', NULL, NULL, 'CONDENSATE ALLOCATION METERING PANEL', 'GBS-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
