  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'WP-13:T/S LT-2360 level transmitter reading error', 'Instrument', 'CM', 'Complete', '2025-04-09', '<p>-Found level transmitter LT-2360 Orion JM4 display is off but level gauge reading around 84% but at the CCR reading 1%, and then measure voltage supply 21.69 vdc, +V/E=22.44 vdc and -V/E=0.749 vdc.</p><p>-Performed replace new level transmitter Orion JM4 and then configure all parameter and re-calibrated and checked reading with the CCR found normal readings.</p><p>-Function test by drain CI found float stuck at below 0% and then try to exercise the float by fill the CI and insert the tubing and push the float from the hole service above of the chamber, It was found that the float slowly floated up , after that trying to exercise float many time found the float normally.</p><p>-Right now level transmitter reading the same with the CI tank 83.4% and If this happens again should be prepare the gasket for clean the chamber or verify the float .</p>', '<p><a href="https://pttep.sharepoint.com/sites/THG2N/DL_Selective_Access/02-PBN-M/02 MEI/19 Photos/01 Instrument Photos/01.Remote Platform/WP13/LSHH-2360 and LT-2360/LT-2360 TS level reading error on 9 Apr 25">https://pttep.sharepoint.com/sites/THG2N/DL_Selective_Access/02-PBN-M/02 MEI/19 Photos/01 Instrument Photos/01.Remote Platform/WP13/LSHH-2360 and LT-2360/LT-2360 TS level reading error on 9 Apr 25</a><br></p>', '2025-04-09 20:56:59', CURRENT_TIMESTAMP, 'PTTEP\\Bongkot.Elec-Lead', NULL, false, 'G2N') RETURNING id INTO new_report_id;
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Ekachai', NULL, 'EXTERNAL', '2025-04-09 20:56:59', CURRENT_TIMESTAMP, 'PTTEP\\Bongkot.Elec-Lead', NULL);
