-- Inserting report ID 28912
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Verify G8010 unable to start at ZBV1', 'Electrical & Instrument', 'CM', 'In Progress', '2025-04-10', '<p><b><u>Today Activity</u></b></p><p>Verify G8010 unable to start at ZBV1</p><p><br></p><p><b><u>Found&nbsp;</u></b></p><p>Found that G8010 can''t run ,stop at crunking state, no engine start.<b><u></u></b></p><p>Even CR relay active when engine start command energize, Starter motor can''t be started.</p><p><br></p><p><b><u>Action</u></b></p><p>Tested run G8010 with manual mode. (can''t start)</p><p>Checked CR relays (88Ohm OK). Contact worked properly when start engine.</p><p>Checked Battery charger condition.(OK)</p><p>Checked Oil pressure sensor cable termination defective.</p><p>Replaced with new oil pressure sensor.</p><p>Planned to verify and troubleshoot the next day.</p><p><br></p><p><b><u style="background-color: rgb(255, 255, 0);"><br></u></b></p><p><u><b style="background-color: rgb(255, 255, 0);">History(08-04-2025)</b></u></p><p><b><u style="background-color: rgb(255, 255, 0);">Today Activity&nbsp;</u></b></p><p><span style="background-color: rgb(255, 255, 0);">Verify G8010 unable to start at ZBV1</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><u><b style="background-color: rgb(255, 255, 0);">Found&nbsp;</b></u></p><p><span style="background-color: rgb(255, 255, 0);">Found that G8010 can''t run ,stop at crunking state, no engine start.</span></p><p><span style="background-color: rgb(255, 255, 0);">Found that one oil pressure sensor terminal was broken.</span></p><p><span style="background-color: rgb(255, 255, 0);">Found that B03 terminal have only 8V against G8020.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><u style="background-color: rgb(255, 255, 0);"><b></b></u></p><p><u><b style="background-color: rgb(255, 255, 0);">Action</b></u></p><p><span style="background-color: rgb(255, 255, 0);">Tested run G8010 with manual mode.</span></p><p><span style="background-color: rgb(255, 255, 0);">Checked CR relays (88Ohm OK).</span></p><p><span style="background-color: rgb(255, 255, 0);">Checked Battery charger condition.(OK)</span></p><p><span style="background-color: rgb(255, 255, 0);">Checked Display controller (Comapp).</span></p><p><span style="background-color: rgb(255, 255, 0);">Checked Oil pressure sensor cable termination defective.&nbsp;</span></p><p><span style="background-color: rgb(255, 255, 0);">Planned to verify and troubleshoot the next day.</span></p>', NULL, '2025-04-10 17:41:34', '2025-04-10 17:42:54', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.Inst-Tec', false, 'ATL') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-BV1-G-8010', 'ATL-BV1-G-8010', 'Gen, Diesel Engine generator No1', NULL, NULL, 'Gen, Diesel Engine generator No1', 'BV1', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Noble', NULL, 'EXTERNAL', '2025-04-10 17:41:34', '2025-04-10 17:42:54', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.Inst-Tec');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Htet Aung', NULL, 'EXTERNAL', '2025-04-10 17:41:34', '2025-04-10 17:42:54', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.Inst-Tec');
