-- Inserting report ID 28921
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'SPP: T/S DEP-8210 cannot normally stop ', 'Electrical', 'CM', 'Under Monitoring', '2025-04-10', '<p>T/S DEP-8210 fire water pump unit cannot normally stop in remote/local mode.</p><p>&nbsp;- Found no clear evidence root cause&nbsp;</p><p>&nbsp;- Checked and tightened on normally stop loop circuit (normal stop pushbutton [S4], timer [T2], controller, relay [RL12] and fuel shut-off solenoid (energized to stop))</p><p>&nbsp;- Cleaned and lubricated on fuel shut-off solenoid,&nbsp;</p><p>&nbsp;- Start engine for running tested (3 times normal stop and 1 time emergency stop), with satisfactory results</p><p>&nbsp;- Fuel shut-off solenoid parameter;</p><p>&nbsp; &nbsp; - Resistance 4.4 ohm</p><p>&nbsp; &nbsp; - IR 15.32 M.ohm at 50Vdc</p><p>&nbsp; &nbsp; - Current 6.3 A at supply voltage 26.20 Vdc (solenoid energized 6 sec. after stop command)</p><p><br></p><p>- To be reserved new fuel shut-off solenoid for spare</p>', 'Photo link;&nbsp;<a href="https://pttep.sharepoint.com/:f:/r/sites/THG2N/DL_Selective_Access/02-PBN-M/02%20MEI/19%20Photos/00%20Electrical%20Photos/SPP/Fire%20water%20pump/2025-04-10%20TS%20DEP-8210%20cannot%20normally%20stop?csf=1&amp;web=1&amp;e=YpXyrS">2025-04-10 TS DEP-8210 cannot normally stop</a>', '2025-04-10 18:58:02', '2025-04-12 08:50:41', 'PTTEP\\Bongkot.Elec-Lead', 'PTTEP\\Bongkot.Elec-Lead', false, 'G2N') RETURNING id INTO new_report_id;
