  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'WP-13:T/S LT-2360 reading error', 'Instrument', 'CM', 'Complete', '2025-04-09', '<p>-Found level transmitter at the local (Orion Jupiter model JM4) display is off, the level gauge is reading around 84%, and the CCR is reading 1%.</p><p>-Measure the voltage supply 221.69 vdc, +V/E 22.44 vdc and -V/E 0.74 vdc.</p><p>- Replaced the new level transmitter with the same model (Orion Jupiter model JM4), configured the parameter, and recalibrated after that function test by filling and drain the liquid. The float was found stuck at the bottom of 0% (the chamber might have been dirty), so we tried to exercise the float by filling it with liquid and using the tubing to push the float from the top of the chamber. It was found that the float slowly floated up. after that, do this many times until the float is normal.</p><p>-Right now level transmitter reading the same, with the CI tank&nbsp; and the CCR around 84%, If the same problem occurs again, you should be prepared the gasket to clean the chamber or verify the float.</p>', NULL, '2025-04-10 19:54:02', '2025-04-10 20:17:48', 'PTTEP\\Bongkot.EI-lead1', 'PTTEP\\Bongkot.EI-lead1', false, 'G2N') RETURNING id INTO new_report_id;
