-- Inserting report ID 29044
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Verify diesel leak at filter.', 'Mechanic', 'PM', 'Completed', '2025-04-12', '<div>1.&nbsp; Found diesel leak from filter.</div><p></p><p>&nbsp; &nbsp; - Visual check and found seal damage and replace new filter and new seal.</p><p><br></p><p>2. Assume back pressure return from injector pump.</p><p>&nbsp; &nbsp; - Install check valve 3/8" at downstream of sentinel valve.</p><p><br></p><p>3. Assume return line to fuel tank was block.</p><p>&nbsp; &nbsp; - Verify and found return line not blocked.</p><p><br></p><p>4. Housekeeping and test running.</p><p>&nbsp; &nbsp; - Operating pressure 20 - 25 PSI.</p><p>&nbsp; &nbsp; - Stop engine pressure 0 PSI.</p><p>&nbsp; &nbsp; - Function test and normal condition.</p><p><br></p><p>Spare part</p><p>1. FUEL FILTER, DONALDSON, P/N. P550440&nbsp; &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;MESC: 18.31.00.005.3&nbsp; &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;1 ea.</p><p>2.&nbsp;FUEL FILTER, PRIMARY, FLEETGUARD, FS1280&nbsp; &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;MESC:&nbsp;18.31.00.003.3&nbsp; &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;1 ea.</p>', '<p><br></p>', '2025-04-12 14:43:45', CURRENT_TIMESTAMP, 'PTTEP\\Art.MechBC', NULL, false, 'ART') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-X-1491', 'ART-X-1491', 'PEDESTAL CRANE ART-WP14', NULL, NULL, 'PEDESTAL CRANE ART-WP14', 'ART-WP14', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Pawaris L.', NULL, 'EXTERNAL', '2025-04-12 14:43:45', CURRENT_TIMESTAMP, 'PTTEP\\Art.MechBC', NULL);
END $$;

