-- Inserting report ID 29105
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'CM 2P-5030B Replace mech seal NDE ', 'Mechanic', 'CM', 'Under Monitoring', '2025-04-13', '<p>- Release pressure in barrier fluid and loosen piping.</p>  <p>- Drain lube oil and remove bearing housing.</p>  <p>- Remove bearing housing and bearing</p>  <p>- Remove mechanical seal and cleaning all part.</p>  <p>- Inspect bearing found pitting corrosion (Last replaced Nov 2018) </p>  <p>- Remove old bearing by press machine and install new bearing on sleeve by heat method at 110 C and Measurement bore of bearing housing and bearing outer race. for make sure bearing properly seated.</p>  <p>- Install new mechanical seal. (With overhaul part) torque at 136 NM.</p>  <p>- Install bearing sleeve with bearing into shaft and tighten locking nut.</p>  <p>- Reinstall bearing housing and apply torque at 267 NM.</p>  <p>- Replace lube oil with PTT hydraulic 46 for 1 liter.</p>  <p>- Re-installed all fluid barrier piping and pressurized for leak test found no sign of leak.</p>  <p>- Test running. Normal condition, barrier fluid maintain at 11.7 bar.</p>', NULL, '2025-04-13 17:26:40', CURRENT_TIMESTAMP, 'PTTEP\\GBS.Mechanic-WorkS', NULL, false, 'G2S') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-2P-5030B', 'GBS-2P-5030B', 'PRODUCED WATER RE-INJECTION PUMP B', NULL, NULL, 'PRODUCED WATER RE-INJECTION PUMP B', 'GBS-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Apinan I.', NULL, 'EXTERNAL', '2025-04-13 17:26:40', CURRENT_TIMESTAMP, 'PTTEP\\GBS.Mechanic-WorkS', NULL);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Surachai J.', NULL, 'EXTERNAL', '2025-04-13 17:26:40', CURRENT_TIMESTAMP, 'PTTEP\\GBS.Mechanic-WorkS', NULL);
