  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Support PMO/I for Ball valve (BA-0248)replacement.', 'Mechanic', 'CM', 'Completed', '2025-04-13', '<p><b>Replacement of (BA-0248) ball valve-12" 900lb activity.(with service ball valve) At Filter Separator-A.</b></p><p><b>-&nbsp;</b>Safety<b>&nbsp;toolbox talk before start the activity.</b></p><p><b>-</b>&nbsp;Removed the 12" ball valve stud bolts.(By using pneumatic impact tool).</p><p>- Set up the lifting gears to 12'' ball valve.</p><p>- Removed the 12" ball valve and lift the valve by using with Tadano Crane.</p><p>- Removed the old RTJ gasket-R-57 Oct(2EA).</p><p>- Check and clean the flange gasket seating with area.(No abnormality found)</p><p>- Set up the lifting gears and install the serviced 12" ball valve with new RTJ gaskets(2EA).</p><p>- Pre-Tighten the flange stud bolts evenly with pneumatic impact tool and check the flange alignment.</p><p><br></p><p><b>&nbsp;FLange stud-bolts Torque tightening with Hydratight tools by three steps &amp; apply</b></p><p><b>&nbsp;Flange 20 bolts tightening sequence</b></p><p><b>-1st</b>&nbsp;torque tightening step- 740 psi.</p><p>-<b>2nd</b> torque tightening step- 1400 psi.</p><p>-<b>Final</b> torque tightening step- 2300 psi.</p>', NULL, '2025-04-13 18:44:30', '2025-04-14 12:36:13', 'PTTEP\\ZOC.Mech-Tec', 'PTTEP\\ZOC.Mech-Tec', false, 'ATL') RETURNING id INTO new_report_id;
