-- Inserting report ID 29129
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, '(C)T/S 2XV-53261B malfunction show discrepancy.', 'Instrument', 'CM', 'Completed', '2025-04-14', '<p data-start="119" data-end="199" class=""><strong data-start="119" data-end="129">Issue:</strong><br data-start="129" data-end="132"> T/S 2XV-53261B malfunction <em data-start="161" data-end="182">"Discrepancy Alarm"</em> appeared on HMI.</p><p data-start="201" data-end="216" class=""><strong data-start="201" data-end="214">Findings:</strong></p><p data-start="201" data-end="216" class=""><strong data-start="201" data-end="214">&nbsp;-&nbsp;</strong>Identified excessive wear on the actuator shaft drive groove that connects to the positioner feedback mechanism.</p><p data-start="201" data-end="216" class="">- Due to the wear, the positioner travel was incomplete, resulting in incorrect feedback and triggering the alarm.</p><p data-start="450" data-end="474" class=""><strong data-start="450" data-end="472">Corrective Action:</strong></p><p data-start="450" data-end="474" class=""><strong data-start="450" data-end="472">-&nbsp;</strong>Installed a shim plate to restore proper fit and alignment in the actuator shaft drive groove.</p><p data-start="450" data-end="474" class="">- Re-adjusted the magnetic proximitor sensor to correct position feedback.</p><p data-start="450" data-end="474" class="">- Performed a full functional test and confirmed the positioner now operates normally, and the alarm cleared.</p><p><br></p>', NULL, '2025-04-14 16:22:50', '2025-04-14 16:25:04', 'PTTEP\\GBS.EI-Workshop', 'PTTEP\\GBS.EI-Workshop', false, 'G2S') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-2XV-53261B', 'GBS-2XV-53261B', 'ACTUATED VALVE', NULL, NULL, 'ACTUATED VALVE', 'GBS-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-2XZH-53261B', 'GBS-2XZH-53261B', 'PROXIMITY SWITCH HIGH', NULL, NULL, 'PROXIMITY SWITCH HIGH', 'GBS-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'GBS-2XZL-53261B', 'GBS-2XZL-53261B', 'PROXIMITY SWITCH LOW', NULL, NULL, 'PROXIMITY SWITCH LOW', 'GBS-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Theeraphan', NULL, 'EXTERNAL', '2025-04-14 16:22:50', '2025-04-14 16:25:04', 'PTTEP\\GBS.EI-Workshop', 'PTTEP\\GBS.EI-Workshop');
