-- Inserting report ID 29144
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Verify G8010 charger alternator condition', 'Electrical & Instrument', 'CM', 'In Progress', '2025-04-14', '<p><b><u>Today Activity</u></b></p><p>Verify G8010 charger alternator condition.</p><p><b><u><br></u></b></p><p><b><u>Action</u></b></p><p>-Test run G8010 without D+ cable of alternator charger&nbsp;with CCR.</p><p>-G8010 can start without D+ voltage.</p><p>-Stop G8010 and measure the cable insulation.</p><p>-Found that D+ cable is 58.1Mohm.</p><p>-Planned to replace with new cable in next day.</p><p><b><u><br></u></b></p><p><b><u style="background-color: rgb(255, 255, 0);">History (11.04.2025)</u></b></p><p><b><u style="background-color: rgb(255, 255, 0);">Today Activity</u></b></p><p><span style="background-color: rgb(255, 255, 0);">Verify G8010 unable to start at ZBV1</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><b><u style="background-color: rgb(255, 255, 0);">Found</u></b></p><p><span style="background-color: rgb(255, 255, 0);">Malfunction charger alternator.</span></p><p><span style="background-color: rgb(255, 255, 0);">G8010 can be started with no D+ voltage.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><b><u style="background-color: rgb(255, 255, 0);">Action</u></b></p><p><span style="background-color: rgb(255, 255, 0);">-Replaced starter motor from G8020 to G8010 and test run G8010. (No OK)</span></p><p><span style="background-color: rgb(255, 255, 0);">-Check all relays conditions.</span></p><p><span style="background-color: rgb(255, 255, 0);">-Found CR CR1 CR2 cable''s connection had voltage dropped (10Vtg).</span></p><p><span style="background-color: rgb(255, 255, 0);">-Replace CR1 relay.</span></p><p><span style="background-color: rgb(255, 255, 0);">-Follow that cables connection through control panel to engine side.</span></p><p><span style="background-color: rgb(255, 255, 0);">-Remove one cable of alternator and test run G8010.</span></p><p><span style="background-color: rgb(255, 255, 0);">-G8010 can be crank. but shut down with oil pressure fault.</span></p><p><span style="background-color: rgb(255, 255, 0);">-Check and replaced with new oil pressure and change orientation of oil pressure housing from up to down.</span></p><p><span style="background-color: rgb(255, 255, 0);">-G8010 can be started with no D+ voltage.</span></p><p><b><u style="background-color: rgb(255, 255, 0);"><br></u></b></p><p><b><u style="background-color: rgb(255, 255, 0);"><br></u></b></p><p><b><u style="background-color: rgb(255, 255, 0);">History(10.04.2025)</u></b></p><p><b><u style="background-color: rgb(255, 255, 0);">Today Activity</u></b></p><p><span style="background-color: rgb(255, 255, 0);">Verify G8010 unable to start at ZBV1</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><b><u style="background-color: rgb(255, 255, 0);">Found&nbsp;</u></b></p><p><span style="background-color: rgb(255, 255, 0);">Found that G8010 can''t run ,stop at cranking state, no engine start.<b><u></u></b></span></p><p><span style="background-color: rgb(255, 255, 0);">Even CR relay active when engine start command energize, Starter motor can''t be started.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><b><u style="background-color: rgb(255, 255, 0);">Action</u></b></p><p><span style="background-color: rgb(255, 255, 0);">Tested run G8010 with manual mode. (can''t start)</span></p><p><span style="background-color: rgb(255, 255, 0);">Checked CR relays (88Ohm OK). Contact worked properly when start engine.</span></p><p><span style="background-color: rgb(255, 255, 0);">Checked Battery charger condition.(OK)</span></p><p><span style="background-color: rgb(255, 255, 0);">Checked Oil pressure sensor cable termination defective.</span></p><p><span style="background-color: rgb(255, 255, 0);">Replaced with new oil pressure sensor.</span></p><p><span style="background-color: rgb(255, 255, 0);">Planned to verify and troubleshoot the next day.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><b><u style="background-color: rgb(255, 255, 0);"><br></u></b></p><p><u><b style="background-color: rgb(255, 255, 0);">History(08-04-2025)</b></u></p><p><b><u style="background-color: rgb(255, 255, 0);">Today Activity&nbsp;</u></b></p><p><span style="background-color: rgb(255, 255, 0);">Verify G8010 unable to start at ZBV1</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><u><b style="background-color: rgb(255, 255, 0);">Found&nbsp;</b></u></p><p><span style="background-color: rgb(255, 255, 0);">Found that G8010 can''t run ,stop at cranking state, no engine start.</span></p><p><span style="background-color: rgb(255, 255, 0);">Found that one oil pressure sensor terminal was broken.</span></p><p><span style="background-color: rgb(255, 255, 0);">Found that B03 terminal have only 8V against G8020.</span></p><p><span style="background-color: rgb(255, 255, 0);"><br></span></p><p><u style="background-color: rgb(255, 255, 0);"><b></b></u></p><p><u><b style="background-color: rgb(255, 255, 0);">Action</b></u></p><p><span style="background-color: rgb(255, 255, 0);">Tested run G8010 with manual mode.</span></p><p><span style="background-color: rgb(255, 255, 0);">Checked CR relays (88Ohm OK).</span></p><p><span style="background-color: rgb(255, 255, 0);">Checked Battery charger condition.(OK)</span></p><p><span style="background-color: rgb(255, 255, 0);">Checked Display controller (Comapp).</span></p><p><span style="background-color: rgb(255, 255, 0);">Checked Oil pressure sensor cable termination defective.&nbsp;</span></p><p><span style="background-color: rgb(255, 255, 0);">Planned to verify and troubleshoot the next day.</span></p>', '<span style="font-size: 14px;">Insulation fail of charger alternator D+ cable.</span>', '2025-04-14 18:30:52', '2025-04-14 18:31:10', 'PTTEP\\ZOC.Elec-Tec', 'PTTEP\\ZOC.Elec-Tec', false, 'ATL') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-BV1-G-8010', 'ATL-BV1-G-8010', 'Gen, Diesel Engine generator No1', NULL, NULL, 'Gen, Diesel Engine generator No1', 'BV1', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Noble', NULL, 'EXTERNAL', '2025-04-14 18:30:52', '2025-04-14 18:31:10', 'PTTEP\\ZOC.Elec-Tec', 'PTTEP\\ZOC.Elec-Tec');
  INSERT INTO task_owner (report_id, name, email, type, created_date, updated_date, created_at, updated_at) VALUES (new_report_id, 'Bone', NULL, 'EXTERNAL', '2025-04-14 18:30:52', '2025-04-14 18:31:10', 'PTTEP\\ZOC.Elec-Tec', 'PTTEP\\ZOC.Elec-Tec');
