  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Fix air leakage on instrument air compressor-B.', 'Mechanic', 'CM', 'Completed', '2025-04-16', '<p><b>Verify and fix on instrument air compressor A-8980B air leakage.</b></p><p><b>-</b>Start the air compressor manually and verify the air leakage location by applying <b>Snoop.</b></p><p>-Found the air leakage at compressor 2nd stage discharge flexible hose(<b>1" Hose</b>).</p><p>-Perform isolation on both electrical &amp; process for A-9200A.</p><p>-Removed the compressor pulley belt cover &amp; damage flexible hose.</p><p>-Cleaning the male fitting threads and apply the seal tape.</p><p>-Install the new spare flexible hose(1") and compressor belt cover.</p><p>-Perform De-isolation for A-9200A.</p><p>-Perform test running and check any leakage.</p><p>-No leakage and abnormality was found.</p><p><br></p><p>Required Tools</p><p>-Spanner-13mm,14mm,17mm,19mm,41mm</p><p>-Adjustable Wrench</p><p>-Pipe Wrench</p><p>-Snoop</p><p>-Seal Tape(Swagelok)</p>', NULL, '2025-04-16 18:26:10', CURRENT_TIMESTAMP, 'PTTEP\\ZOC.Mech-Tec', NULL, false, 'ATL') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-A-8980B', 'ATL-OC-A-8980B', 'ZOC IA Compressor B', NULL, NULL, 'ZOC IA Compressor B', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
