BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'WP-11: T/S PSLL 2150A/B Malfunction', 'Instrument', 'CM', 'Complete', '2025-04-16', '<p>WP-11: T/S PSLL 2150A/B Malfunction</p><p>1. T/S PSLL-2150B activated low alarm all the time.</p><p>- Overhauled pressure switch and function tested&nbsp;</p><p>- Set pressure alarm low at 25 bar</p><p>- Found unit running working properly</p><p>2. T/S PSLL-2150A found CI leak at body. (Set pressure alarm low at 25 bar)</p><p>- Overhauled pressure switch and function tested, no leak at body PSLL</p><p>- Performed second function test, found CI pump not running&nbsp;</p><p>- To be verify</p><p><br></p><p>Note: XV-2510A command open, valve status is open and feed back CI pump not show running in CCR</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Found XV-2510A cannot close after command from CCR (XV-2510A is instrument gas supply to drive CI pump)</p>', NULL, '2025-04-16 19:48:29', '2025-04-16 19:50:48', 'PTTEP\\Bongkot.Elec-Lead', 'PTTEP\\Bongkot.Elec-Lead', false, 'G2N') RETURNING id INTO new_report_id;
