  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-HVAC-AHU1', 'ATL-OC-HVAC-AHU1', 'Air Handling Unit 1', NULL, NULL, 'Air Handling Unit 1', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
