  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Remove PCV-5292 to install a temporary point at LD', 'Instrument', 'CM', 'Complete', '2025-04-19', '<div>-Remove PCV-5292 (old valve) and install it at a temporary point at PP-LD beside the P-5210 for support repair of the GRP pipe.</div><div>-Function tested the PCV-5292 by hand pump and found the valve open around 10.5 bar/close 8.6 bar.</div><div>-Performed de-process isolation and normalize the PCV found that at fire ring main pressure reading 8.1 bar, but the pressure gauge at the PCV read around 9.1 bar due to the different point, and then re-adjusted the PCV pressure (adjust 1-1/2 turn) from valve open 10.5 bar/close 8.6 bar to open 12 bar/close 10 bar.</div><div>-Performed normalize the PCV again found the PCV can control fire ring main pressure around 10 bar</div><div>&nbsp; Start 1 jocky pump pressure = 10 bar</div><div>&nbsp; Start both jocky pumps pressure = 12.2 bar</div><div><br></div><div>*Tool</div><div>- Spiral wound gasket 2"150 2 pcs.</div><div>- Rubber gasket 3"150 1 pcs.</div><div>- Wrench no. 27 mm.</div>', '<a href="https://pttep.sharepoint.com/:f:/r/sites/THG2N/DL_Selective_Access/02-PBN-M/02%20MEI/19%20Photos/01%20Instrument%20Photos/03.PP/PCV-5292/PCV-5292%20Remove%20valve%20to%20temporary%20install%20at%20PP-LD%20on%2019%20Apr%2025?csf=1&amp;web=1&amp;e=AL9GcB">PCV-5292 Remove valve to temporary install at PP-LD on 19 Apr 25</a>', '2025-04-19 18:38:51', '2025-04-19 19:22:51', 'PTTEP\\Bongkot.EI-lead1', 'PTTEP\\Bongkot.EI-lead1', false, 'G2N') RETURNING id INTO new_report_id;
