  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S QPS/PPS Fire water pump could not start.', 'Electrical', 'CM', 'Completed', '2025-04-20', '<p>T/S QPS/PPS Fire water pump could not start.</p><p>- Found that fire water pumps 2X-6201 and 2X-5200B could not be started by the electrical system due to a tripped circuit breaker. (reference to G2S-SMD-24014)</p><p>- Temporarily reinstalled the original fuse in place of the circuit breaker at fire water pump units 2X-5200A, 2X-5200B, and 2X-6201.</p><p>- All units were tested and found to be operating normally, with no alarms present.</p><p>- Starting current at the circuit breaker was verified to be 20.7A.</p>', NULL, '2025-04-20 21:30:15', CURRENT_TIMESTAMP, 'PTTEP\\GBS.EI-Workshop', NULL, false, 'G2S') RETURNING id INTO new_report_id;
