  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'T/S 2LIT-36552 and 2LIT-36550 reading error', 'Instrument', 'CM', 'Completed', '2025-04-24', '<p><b>T/S 2LIT-36552 and 2LIT-36550 reading error</b></p><p>- Found 2LIT-36550 and 2LIT-36552 reading value is difference&nbsp; and reading spike time to time</p><p>- Found 2LG-36551 sigh glass stuck at bottom position cannot movement.</p><p><b>Performed as below :</b></p><p> </p><p>&nbsp; &nbsp; &nbsp;<b>2LIT-36552</b> : 1.Remove remote seal flange for inspect diaphragm found a lot of sludge and mercury</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;2.Temporary replace by new level transmitter spare for compare data.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;3.Change&nbsp; sg config from sg 0.96 to sg 0.75 ( LRV&nbsp; -1314.0&nbsp; / URV -414.0 mmH2O )</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;4.Calibrate and function test completed</p><p>&nbsp; &nbsp; &nbsp; <b>2LIT-36550</b> : 1.Remove remote seal flange for inspect diaphragm found a lot of sludge and mercury</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;2.Clean and flushing lower flange.</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;3.Install flange and re-calibrate change sg form 0.96 to 0.75 ( LRV&nbsp; -1314.0&nbsp; / URV -414.0 mmH2O )</p><p>&nbsp; &nbsp; &nbsp;<b>2LG-36551 </b>:1. Remove float for inspect, found float is damaged case of water inside&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;2. Old float model : F1F-1500-060 sg.0.58268 - 1.012&nbsp;</p><p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;3. Replace to new float model : F1F-1500-060 sg.0.58268 - 1.012&nbsp;</p><p>&nbsp;- Online back to normal 2LIT-26550 reading 53% , 2LIT-36552 reading 54% , 2LG-36551 reading 85%</p><p><br></p><p><span style="background-color: rgb(255, 255, 0);">*** For SG <b><i>0.75</i></b> discuss with Lab (Ton), CCR (Nung, Art, Berm), EI&nbsp; </span>&nbsp; &nbsp; &nbsp; &nbsp;</p>', '<p><a href="https://pttep.sharepoint.com/:f:/r/sites/THG2S/DS03Maintenance/032%20DBS_MEI/3214%20Photo,%20Picture/INSTRUMENT/PPS/2LIT-36550,2LIT-36552?csf=1&amp;web=1&amp;e=KMJOwv">2LIT-36550,2LIT-36552</a>&nbsp;Picture file link</p><p><br></p>', '2025-04-25 07:58:56', '2025-05-05 17:15:19', 'PTTEP\\GBS.EI-Workshop', 'PTTEP\\PongsakR', false, 'G2S') RETURNING id INTO new_report_id;
