-- Inserting report ID 29756
DO $$
DECLARE
  new_report_id INTEGER;
BEGIN
  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'YPM Mercury (Hg) analyzer AIT-1681 (iLabFluid)', 'Instrument', 'PM', 'In Progress', '2025-04-28', '<p>YPM Mercury (Hg) analyzer AIT-1681 (iLabFluid Vendor)</p><p>- Validated data (Span Check) with Hg sample by Manual Cal Box. Found Max-Absorb is lower than Factory recommended.</p><p>- Calibrated UT-3000 (Low Range / UltraTracer), Max-Absorb is still quite low.</p><p>- Tried to replaced GoldTrap back to recently then validated (Span Check) with Mercury Manual Cal Box, Max-Absorb is still low.</p><p>- Check Flow inside UT-3000 comprisist of Heating Flow, Sampling Flow and Cooling Flow), normal in require rate.</p><p>- Check and Clean Syringe for inject calibration port by Acetonce.</p><p>- Check line-tube inside UT-3000&nbsp;</p><p>- Calibrated UT-3000, Max-Absorb is low.</p><p>- Validated data (Span Check) with MC-3000 (Mercury Calibrator) by run detector2 feed Hg 45 ug/m3, found Max-Absorb is around 0.0153 that too low and cause to Hg concentration reading low.</p><p>- Tried to feed Hg 100 ug/m3 from MC-3000 (Mercury Calibrator) to UT-3000, found Max-Absorb is around 0.0312 that too low and cause to Hg concentration reading low.</p><p>- Consult manufacturer (MI-Mercury Instruments Germany), waiting for next solution.&nbsp;&nbsp;</p><p><br></p><p>- Verified Pressurized System in Housing skid (Ex-P), found pressure is around&nbsp;4.15 mBar&nbsp;and Volume Flow was 4.0 l/sec which lower than criteria (Required Pressure &gt; 0.8-15 mBar and Min Volume Flow 5.0 l/sec).</p><p>- Replaced new Door Seal Rubber, Monitor improved Pressure and adjusted pressure regulator to 10.55 mBar&nbsp;and&nbsp;Flow Rate is 6.5 l/sec.</p><p>- Test Function key Operate/Bypass for Ex Cabinet.</p><p><br></p><p>- Inspect and adjust sampling conditioner skid for 4 streams from MRU (AE-1681A/B/C : XSV-1120/1121/1130) and SGM (AE-1681D : XSV-1681)</p><p>- Found pressure gauge of AE-1681A/B/C are damaged by unable to zero point when isolated sample in. There is no PG spare part 2.5" (0-35 psi / 0-2.5 Bar)&nbsp;</p><p><i>&nbsp; &nbsp;*Stream-B (AE-1681B) is closed sample inlet valve due to process required (MRU V-1120 outlet)</i></p><p><i>-&nbsp;</i>Found pressure gauge of&nbsp; Instrument Air Supply in cabinet (SCS/P2) pointer damaged. There is no PG spare part 2.5" (0-200 psi / 0-14 Bar</p><p><br></p><p>Progress 75% of plan 100%&nbsp;</p><p><br></p><p>_/_/_/_/_/_/_/_/_/_/ Next Plan _/_/_/_/_/_/_/_/_/_/&nbsp;</p><p>- T/S (CM) Max-Absorbance is lower than Factory recommended.</p><p><br></p><p><br></p>', '<p><a href="https://pttep.sharepoint.com/sites/THART/EI/Forms/AllItems.aspx?id=%2Fsites%2FTHART%2FEI%2F04%20%2D%20Electrical%5FInstrument%2F00%2DInstrument%2F04%20%2D%20Mercury%20Analyzer%5F1681%2F2025%20Report%2F20250425%2D28%5FYPM%5FHg%2DAnalyzer%5FiLabFluid&amp;viewid=415f9878%2Da53c%2D45fe%2D8639%2De524c6aa2067">20250425-28_YPM_Hg-Analyzer_iLabFluid</a><br></p>', '2025-04-28 10:03:59', '2025-04-30 15:36:52', 'PTTEP\\Art-Tech-Prod-Maint', 'PTTEP\\Art-Tech-Prod-Maint', false, 'ART') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-SK-1681', 'ART-SK-1681', 'SALES GAS HG ANALYSER', NULL, NULL, 'SALES GAS HG ANALYSER', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ART-AT-1681A', 'ART-AT-1681A', 'ANALYSIS TRANSMITTER', NULL, NULL, 'ANALYSIS TRANSMITTER', 'ART-PP', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
