  INSERT INTO daily_reports (work_order_no, activities_subject, discipline, activities_type, work_status, report_created, task_description, task_remark, created_date, updated_date, created_at, updated_at, is_deleted, asset) VALUES (NULL, 'Troubleshoot EDG8935 SD stop fail alarm', 'Electrical & Instrument', 'CM', 'Under Monitoring', '2025-04-28', '<p><b><u>Today Activity</u></b></p><p>Troubleshoot EDG8935 SD stop fail alarm</p><p><b><br></b></p><p><u><b>Action</b></u></p><p>Perform electrical isolation including earthing.</p><p>Open alternator JB.</p><p>Check fuse and CT coil condition (all fine 0 ohm)</p><p>Replace used ComAp controller from EI test room.</p><p>Test run with shared load for 1 hour.</p><p>G8935 running normal and no more alarm.</p><p>G8935 is back in service (now auto mode).</p><p><b><br></b></p><p><b><br></b></p><p><b><br></b></p><p><b><br></b></p><p><b>History (27/04/2025)</b></p><p><b>Today''s Activity</b><br></p><p>Weekly test run diesel generator G8935</p><p><u><b><br></b></u></p><p><u><b>Found</b></u></p><p>G8935 stop with following alarms during shared load 30 min.</p><p><u>alarms:</u></p><p>1)BOC L1 under</p><p>2)sd stop fail&nbsp;</p><p><br></p><p><b><u>Action</u></b></p><p><b><u>G8935</u></b></p><p>- Performed test run by manual.</p><p>- Performed test run with shared load 30mins.&nbsp;</p><p>- Checked all parameters during generator running with shared load.</p><p>- All lightings inside cabin are working properly.</p><p>-G8935 stop with alarms during shared load 30 min.</p><p>-Cleared alarm and set auto mode of G8935</p><p><br></p><p><br></p><p><br></p>', NULL, '2025-04-28 17:26:45', '2025-04-29 10:37:54', 'PTTEP\\ZOC.Inst-Tec', 'PTTEP\\ZOC.Se-EI', false, 'ATL') RETURNING id INTO new_report_id;
  INSERT INTO tags (report_id, equipment_no, technical_id_no, technical_object_description, superior_functional_location, superior_equipment, text, location, children, created_date, updated_date) VALUES (new_report_id, 'ATL-OC-G-8935', 'ATL-OC-G-8935', 'Gen, Generator ZOC Diesel Gas Package', NULL, NULL, 'Gen, Generator ZOC Diesel Gas Package', 'OC', false, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
